WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[89560] = { title = "A Quiet Farewell", description = "Now we set up de bonfire to burn de body. Destroying the body means it cannot be used by de Vilebranch for evil and makes sure de spirit finds rest.\n\nIt still chills me how quiet she is now.\n\nThe tribe should be gatherin' down at de Funerary Coast.", objectives = "Setup the bonfire for Chana and Iz'ken.", progress = "It's time. We are ready.", completion = "Thank you for helpin' us on dis journey, <name>.\n\nI didn't think Iz'ken would come, and he didn't think he'd be welcome.\n\nI think Iz'ken and I realize now... de worst trick our mother pulled was pittin' us against each other." }
WordHunterWoW_QuestEN[89561] = { title = "Wrapped Up", description = "Shad'anis has told me about you--a fleshling with the ability to travel to Untethered Space. How do you accomplish such a feat? Wait--let me deduce.\n \nIt must be those wraps you wear as a cloak. They have been modified by a Reshii Ribbon. I have not seen such a thing since the Devouring War. Very nice. Classic.\n \nDo you want classic? Or do you want powerful? I can enhance your Reshii Wraps with modern technomancy techniques to better face the dangers of Untethered Space.", objectives = "Talk to Hashim about your Reshii Wraps.", progress = "Enhancing the Reshii Wraps is paramount to your survival.", completion = "Thank you, <name>. Your adventures in Untethered Space will help clear the way for our Phase Divers to recover the energy that would have been lost to the Void." }
WordHunterWoW_QuestEN[89565] = { title = "The Path of Mourning", description = "Hash'ura, could I ask for your aid?\n\nMy mother passed recently, and I'm de one responsible for performin' her death rituals. It's a lotta work for one person to do.\n\nMost would get help from their family, but I don't have any left. Can you help me?", objectives = "Meet Chana in the Solemn Valley.", completion = "My younger brother left us when I was just comin' of age.\n\nHe sent word he would come and help but... we did not part on good terms.\n\nBut here he is. After all dis time." }
WordHunterWoW_QuestEN[89585] = { title = "Nightfall", description = "", objectives = "" }
WordHunterWoW_QuestEN[89590] = { title = "Infinite Research: Time to Raid, Hope's End", description = "We require information about how multiple timerunners and their artifacts interact when faced with powerful opposition.\n\nSeek out others to help you conquer Hope's End.", objectives = "Complete the Hope's End wing of Antorus, the Burning Throne on any difficulty.", progress = "Time is running short and we need that group data, <name>.", completion = "The sum strength of a group of timerunners armed with potent artifacts is greater than that of the individuals. Much greater than anticipated. Intriguing." }
WordHunterWoW_QuestEN[89591] = { title = "Infinite Research: Time to Raid, Seat of the Pantheon", description = "We require information about how multiple timerunners and their artifacts interact when faced with powerful opposition.\n\nSeek out others to help you conquer Seat of the Pantheon.", objectives = "Complete the Seat of the Pantheon wing of Antorus, the Burning Throne on any difficulty.", completion = "The sum strength of a group of timerunners armed with potent artifacts is greater than that of the individuals. Much greater than anticipated. Intriguing." }
WordHunterWoW_QuestEN[89592] = { title = "Infinite Research: Antorus, the Burning Throne, Normal", description = "Some challenges cannot be faced alone. While numbers do matter, good teamwork is even more potent.\n\nGather your most trusted allies to help you conquer this incarnation of Antorus.", objectives = "Defeat 2 bosses in Antorus, the Burning Throne on Normal difficulty or higher.", completion = "Teamwork makes the dream work, or so they say. It would appear that the rhyme carries truth to it. Hmmm.\n\n<Eternus pauses for a moment in thought.>\n\nI wonder what other rhymes carry such power. That bears some future experimentation." }
