WordHunterWoW_QuestEN[90081] = { title = "Arcane Runed Sigil", description = "An Arcane Runed Sigil is essential in proving an item's authenticity as a true masterpiece of Azure artisans. Of course, they can be affixed to any object, turning a flea market trinket into something that appears to be a priceless work of art.\n\nI could create something like that, and it might turn a great profit. If you travel to the Azure Vault and gather the parts I need, we can use them to craft a Sigil.\n\nBring me enough parts for two, and I shall keep one as my fee for the service.", objectives = "Enter the Archival Assault delve and collect 24 Etched Fragments.", progress = "Have you collected the parts?", completion = "Excellent, this is more than enough to construct what you require." }
WordHunterWoW_QuestEN[90087] = { title = "Distance Tracker (DNT)", description = "Testing distance tracking. Do not translate. Not player facing.", objectives = "Find things." }
WordHunterWoW_QuestEN[90093] = { title = "Prey Contract: Murloc Shadowhunter", description = "A MURLOC SHADOWHUNTER has been spotted in Zul Aman!\n\nDifficulty: Hard\n\nAffixes: Mark of the Prey\n\nYour target will occasionally mark you, decreasing your damage done and increasing damage taken.", objectives = "" }
WordHunterWoW_QuestEN[90094] = { title = "Echo of the Hunt", description = "Haranir are fierce and ferocious--cunning and canny. In time, we became the most feared beasts upon the mountain.\n\nA great many wise and powerful beasts roamed the hills of our old mountain. But in time, we came to master them all.\n\nToday, you shall hunt as we once did.", objectives = "Complete the second trial at the Den of Echoes.", completion = "You have proven yourself a capable hunter like our ancestors of old. But simply being the strongest did not prove succor enough for the minds of our people." }
WordHunterWoW_QuestEN[90095] = { title = "Echo of the Call", description = "When the haranir began to grow restless, they looked to new sources of purpose. Some cast their gazes upward, toward the stars and the moon. Others, such as the Hara'ti, heard a call from deep within the world.\n\nThe moment the first of the Hara'ti heard the Song echoing from the roots, we knew that we had found a new purpose. We would seek out the source of the Song, and discover the truth of it for ourselves.\n\nBut it would be a difficult road. Strange stone monsters sought to block our path.", objectives = "Complete the third trial at the Den of Echoes.", completion = "Now you know how the Hara'ti came to walk amongst the roots.\n\nOne final trial remains--the most difficult, but most important, of them all.\n\nHagar awaits you, and will guide you through the next challenge." }
WordHunterWoW_QuestEN[90096] = { title = "Infinite Research: Worldly Deeds", description = "All across the Broken Isles there are people in need. They search for hope but are hard pressed to find any. You can be that hope.\n\nSeek out those in peril in the Broken Isles and be the champion they so desperately need.\n\nIt is through such acts that legends are made.", objectives = "Complete 4 world quests.", progress = "Somewhere, someone is in need. All they need is a champion to save them.", completion = "A single heroic act can turn the tide. A single whisper of hope can turn back despair. This is what gives legends their power." }
WordHunterWoW_QuestEN[90097] = { title = "Infinite Research: Invasion Points", description = "The Legion does not fight conventionally. They deceive, manipulate, and undermine their opposition at every turn.\n\nThere are no battle lines against the Legion. They will open rifts at a weak point and then spill out of it sowing death and destruction. When they invade, it is on their terms.\n\nHowever, this strategy is not invincible. Potent champions, able to move and react swiftly, can stop these invasions at their source. Stop the Legion Invasion. Show people that the Legion can be defeated.", objectives = "Complete a Legion invasion point.", completion = "The power you and your artifact possess were able to halt a Legion invasion. But was it you, or the artifact you wield, that is responsible? On that I will require more information." }
WordHunterWoW_QuestEN[90098] = { title = "Infinite Research: Greater Invasion Points", description = "Once the Legion has sown confusion and chaos, then they will begin their real assault. Huge invasion rifts will open and the Legion will march forth in great numbers. The defenders, scattered to protect against smaller rifts, will lack sufficient strength anywhere to stop them.\n\nThat is when champions like you are most needed.\n\nSeek out one of the Legion's major invasions and throw everything you have at it. \n\nShow the people that with enough determination you can cancel the apocalypse.", objectives = "Complete a greater Legion invasion point.", completion = "Just as I predicted. You were able to stop a massive Legion invasion. It was not you, or your artifact that did this. Rather it was the combination of both that won the day." }
WordHunterWoW_QuestEN[90099] = { title = "Infinite Research: Combat Studies, Rare", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a rare study, so focus on fighting rare opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", objectives = "Kill 6 rare enemies.", progress = "We need more fight data to complete our study, and time is running short.", completion = "Well done, <name>. Moratari will be overjoyed to see these new data points." }
WordHunterWoW_QuestEN[90100] = { title = "Infinite Research: Combat Studies, Rare Elites", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a rare elite study, so focus on fighting rare elite opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", objectives = "Kill 2 rare elite enemies.", progress = "We need more fight data to complete our study, and time is running short.", completion = "Well done, <name>. Moratari will be overjoyed to see these new data points." }
WordHunterWoW_QuestEN[90101] = { title = "Infinite Research: Terrors of the Broken Isles", description = "It is time to put both you and your artifact to the test.\n\nSeek out a Terror of the Broken Isles and defeat them.\n\nI am certain that, no matter the outcome, you will provide us with much to think about. I will be watching with great interest.", objectives = "Kill a world boss.", progress = "How fares the research?", completion = "A fascinating outcome, <name>. This will shed some much needed light on our research." }
WordHunterWoW_QuestEN[90102] = { title = "Infinite Research: Champion of the Broken Isles", description = "Our research suggests that power is only part of the equation--what one does with it is also of great importance.\n\nThe people of the Broken Isles need a champion. Come to their aid and drive the Legion from their shores and your legend will grow.\n\nWhere you choose to start is up to you--the Legion is everywhere, so one place is just as good as another.", objectives = "Complete any Legion zone campaign chapter.", completion = "Your legend has grown, <name>. The timeline reverberates with not just the substance of your deeds, but it compounds as it impacts those around you. This has been a most fruitful addition to our research." }
WordHunterWoW_QuestEN[90103] = { title = "Infinite Research: Champion of the Order Hall", description = "Your legend will not be satisfied with just being another {class}--you must prove yourself to be more.\n\nProve yourself within your Order Hall. Gain the respect of your peers, and become the first among equals.\n\nIn this way we may yet determine what limits you have and whether it is a person, or their artifact, that defines the legend.", objectives = "Complete a chapter of your Order Hall campaign.", completion = "You have gained the respect due to a true <class>. You are a leader. All that remains to be answered is where you are going." }
WordHunterWoW_QuestEN[90108] = { title = "Infinite Research: Artifact Collector", description = "As we study this timeline and your effect upon it, a question has been raised--what would be different if you had a different artifact?\n\nSeek out a new artifact and let us see whether the first choice you made was good, or great.", objectives = "Acquire a new artifact weapon.", completion = "You have quite the collection now, <name>. All that remains to be seen is whether you prefer one artifact over the other." }
WordHunterWoW_QuestEN[90109] = { title = "Infinite Research: Clear the Skies", description = "Manipulating time is not without its risks or its rewards.\n\nThe strain on this timeline has produced numerous residual time motes through the Broken Isles. It would be irresponsible not to clean them up.\n\nHowever, there is opportunity here. If you were to gather these motes, then their latent infinite power would be bestowed upon you instead.\n\nWe can clean up the timeline and enhance our research at the same time.", objectives = "Collect 50 residual time motes while flying.", progress = "This timeline is pockmarked with time motes. Gather as many as you can.", completion = "Good. Nothing dramatic occured when you gathered the residual time motes. If you start to feel anything strange, do let us know though." }
WordHunterWoW_QuestEN[90110] = { title = "Infinite Research: Gather Timewarped Samples", description = "The fraying of this timeline has had some interesting effects on plants and stone. We would like to study them.\n\nGather samples of timewarped herbs and ores from around the Broken Isles and being them back for analysis.", objectives = "Gather timewarped herbs and ores.", progress = "How fares the research?", completion = "Moratari will be elated to see so many test samples. Thank you for your diligence." }
WordHunterWoW_QuestEN[90111] = { title = "Infinite Research: Combat Studies, Demonology", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a demonology study, so focus on fighting demonic opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", objectives = "Kill 75 demons.", progress = "We need more fight data to complete our study, and time is running short.", completion = "Well done, <name>. Moratari will be overjoyed to see these new data points." }
WordHunterWoW_QuestEN[90112] = { title = "Infinite Research: Combat Studies, Elite", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be an elite study, so focus on fighting elite opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", objectives = "Kill 25 elite enemies.", progress = "We need more fight data to complete our study, and time is running short.", completion = "Well done, <name>. Moratari will be overjoyed to see these new data points." }
WordHunterWoW_QuestEN[90113] = { title = "Infinite Research: Self Improvement, Basic", description = "By improving yourself we can compare your power to that of your artifact. Only then will we be able to determine if it is the artifact, or its wielder, that is most important.\n\nGo forth and grow stronger, more focused, more experienced--then return to me so we may record your improvements.\n\nThe road to self improvement is a long one, so pace yourself.", objectives = "Complete various activities on the Broken Isles.", progress = "Remember to pace yourself, the journey is just as important as the destination.", completion = "Impressive. I can sense your power. This is a most critical addition to our research." }
WordHunterWoW_QuestEN[90114] = { title = "Infinite Research: Self Improvement, Advanced", description = "By improving yourself we can compare your power to that of your artifact. Only then will we be able to determine if it is the artifact, or its wielder, that is most important.\n\nGo forth and grow stronger, more focused, more experienced--then return to me so we may record your improvements.\n\nThe road to self improvement is a long one, so pace yourself.", objectives = "Complete various activities in Heroic World Tier.", completion = "Impressive. I can sense your power. This is a most critical addition to our research." }
WordHunterWoW_QuestEN[90115] = { title = "Infinite Research: Combat Studies, Groverunner", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a study of your attunement to the forest, so focus on fighting opponents using the power of nature.\n\nAnd remember, this is for the greater good.", objectives = "Kill 100 enemies while Call of the Forest is your active artifact ability.", completion = "Impressive. I can sense your power. This is a most critical addition to our research." }
WordHunterWoW_QuestEN[90119] = { title = "test", description = "", objectives = "" }
WordHunterWoW_QuestEN[90122] = { title = "Eliminate Xy'vox the Twisted", description = "<Use the Xy'vox Refuge Dampener to reveal and eliminate Xy'vox the Twisted.>", objectives = "Eliminate Xy'vox the Twisted.", progress = "Eliminate Xy'vox the Twisted.", completion = "Excellent work, I will issue a reward for eliminating this warrant target." }
WordHunterWoW_QuestEN[90123] = { title = "Eliminate Hollowbane", description = "<Use the Hollowbane Portal Key to reveal and eliminate Hollowbane.>", objectives = "Eliminate Hollowbane.", progress = "Eliminate Hollowbane.", completion = "Excellent work, I will issue a reward for eliminating this warrant target." }
WordHunterWoW_QuestEN[90124] = { title = "Eliminate Shatterpulse", description = "<Use the Shatterpulse Cell Key to reveal and eliminate Shatterpulse.>", objectives = "Eliminate Shatterpulse.", progress = "Eliminate Shatterpulse.", completion = "Excellent work, I will issue a reward for eliminating this warrant target." }
WordHunterWoW_QuestEN[90125] = { title = "Eliminate Purple Peat", description = "<Use the Purple Peat Cell Key to reveal and eliminate Purple Peat.>", objectives = "Eliminate Purple Peat.", progress = "Eliminate Purple Peat.", completion = "Excellent work, I will issue a reward for eliminating this warrant target." }
WordHunterWoW_QuestEN[90126] = { title = "Eliminate Grubber", description = "<Use the Grubber Lure to reveal and eliminate Grubber.>", objectives = "Eliminate Grubber.", progress = "Eliminate Grubber.", completion = "Excellent work, I will issue a reward for eliminating this warrant target." }
WordHunterWoW_QuestEN[90127] = { title = "Eliminate Arcana-Monger So'zer", description = "<Use the Arcane Lure to reveal and eliminate Arcana-Monger So'zer.>", objectives = "Eliminate Arcana-Monger So'zer.", progress = "Eliminate Arcana-Monger So'zer.", completion = "Excellent work, I will issue a reward for eliminating this warrant target." }
WordHunterWoW_QuestEN[90128] = { title = "Miscreant Baras!", description = "", objectives = "" }
WordHunterWoW_QuestEN[90467] = { title = "Tales of the Sky", description = "Wait a minute... You're no rutaani at all! Are you one of those \"outsiders\" that Saku and Orkon keep talking about?\n\nOh! I just had a great idea. Did you know that the Goddess used to have a pet? Rumor has it that when the Goddess disappeared, Aln'sharan was SO sad that he flew up into the highest roots of Harandar, never to be seen again. But every so often, he goes looking for food... And his scales fall as skyglass!\n\nI wanna gather some. It's my dream to see Aln'sharan firsthand! Will you help me?", objectives = "Collect 6 Stray Skyshards in the Cascades of Harandar.", progress = "Aln'sharan is a folk tale that we tell haranir children to explain the shards of glass that occasionally rain upon Harandar.\n\nMost grow out of searching for sky serpents. But Kuri's heart has always been filled with whimsy.", completion = "Goddess preserve. Kuri has always had her mind wrapped up in the roots." }
WordHunterWoW_QuestEN[90468] = { title = "Ugh, Chores!", description = "Okay, so I may have a DIFFERENT thing that I'm supposed to be doing in the Cascades, too. It's my turn to gather saptor fronds for stew. It's such a pain. Not only are saptor fronds horribly bitter, but the saptors are barely even fun to hunt! They don't even make your blood flow that fast before they die.\n\nBut hey! You probably don't get to fight saptors as often as I do. Maybe while you're looking for skyglass, you could gather some up for me? You know... while you're in the area.", objectives = "Collect 8 Intact Saptor Fronds from the saptors of the Harandar Cascades.", progress = "Oh, Kuri...", completion = "Kuri is as imaginative as she is fierce, but she also has a bad habit of neglecting her chores. I appreciate your contribution to our community, though I shall have to give Kuri a scolding once she returns." }
WordHunterWoW_QuestEN[90469] = { title = "Carry On, Wayward Kuri", description = "Oh, that Kuri. She holds tightly to our ancient traditions and tales... perhaps too tightly.\n\nThere is a difference between holding reverence for our ancient ways and chasing them into dangerous caves. I fear she might bite off more than she can chew in her search for Aln'sharan.\n\nWon't you go after her? She seems to trust you, now that she sees you as her co-conspirator in this quest. Please bring her home safely.", objectives = "Find Kuri in Dreth'amar Cavern.", completion = "O-Okay... so maybe I'm a bit afraid of the dark. But that doesn't mean I'm not going in there!\n\nYou'll be there with me too, right? There are probably tons of skyshards to be found inside!" }
WordHunterWoW_QuestEN[90470] = { title = "Skyglass Scavenging", description = "The adults find all sorts of stuff in the caves around here that we use back at the village. A lot of the critters that live in the caves like to gather skyglass, in particular. I guess they think it's shiny.\n\nThat's good for us, though! It means we can go and get a bunch of skyglass. Go in there and make sure the coast is clear, and then I'll come in and gather up as much as I can carry!\n\nAt this rate, we'll be able to summon Aln'sharan in no time.", objectives = "Gather as much Skyglass as Kuri can carry from Dreth'amar Cavern in Harandar.", progress = "Come onnn! We've gotta hurry before mom gets TOO worried.", completion = "Yes! Yes, yes, yes! This is soooo much!\n\nAln'sharan will notice for sure. He probably wants all of his skyglass back!" }
WordHunterWoW_QuestEN[90474] = { title = "The Legend of Aln'sharan", description = "This is it! We have all the skyglass we can carry.\n\nThe legends say that Aln'sharan cries crystal tears to mourn the missing Goddess. Maybe if we give the crystals back to him, he won't be so sad? Maybe then he'll appear for us!\n\nMeet me back at the village. I think I know the perfect place to make our offering.", objectives = "Return to Kuri in Har'kuai.", progress = "Come on! We don't wanna miss our chance! Also all of this skyglass is heavy. Can't you carry some?!", completion = "You know... I thought I would be sad if this didn't work, but I actually feel okay!\n\nI still believe. There's so much magic in the world. And even if Aln'sharan isn't exactly what I think he is... his story still exists for a reason. And that's important to me, I think." }
WordHunterWoW_QuestEN[90481] = { title = "I Have a Permit", description = "These Witherbark youths are telling us we can't stay here.\n\nBut I've been talking to one of their elders for months to be sure we'd have permission to set up camp and explore. I even have copies of all the letters!\n\nCan you find Elder Ren'zen in Witherbark Village and show him his letter of approval?", objectives = "Find Elder Ren'zen in Witherbark Village.", progress = "Elder Ren'zen seemed so pleasant in his letters. Why all the hostility now?", completion = "He confirmed what he'd sent was a letter of approval? Good! I'm glad that's cleared up.\n\nMaybe now we can get a more pleasant introduction to Zul'Aman." }
WordHunterWoW_QuestEN[90482] = { title = "Cuisine Connection", description = "Dis \"seeker\" has been askin' a lot of questions about de foods we eat.\n\nIt sounds like these tortollans like to eat poisonous foods. De Witherbark do as well. There are many foods we eat that could kill us if not treated properly.\n\nGo collect zapgut eel stomachs and blisterskin kelp. I'd like to test dis turtle's tongue.", objectives = "Collect 6 Zapgut Eel Stomachs and 60 Blisterskin Kelp.", progress = "We ingest some poisons to make ourselves resistant to potential threats.\n\nSome just taste good or provide a good thrill.", completion = "Excellent. Now to prepare it." }
WordHunterWoW_QuestEN[90483] = { title = "A Witherbark Story", description = "The Witherbark say they have a lot of stories to tell, but I've heard two and BOTH involved a sparring match!\n\nPlease, can you ask the Witherbark here for stories? My old bones can't take another reenactment!", objectives = "\"Reenact\" 5 Witherbark stories in Camp Stonewash.", progress = "What's wrong with a gentle story about falling asleep at an inopportune time?\n\nTortollan folklore is full of those. Do trolls not sleep?", completion = "I see. They keep clear records of all these battles at least. Their storytelling is quite strenuous!" }
WordHunterWoW_QuestEN[90484] = { title = "Sightseeing Stegadon", description = "Wow, your armor is sooooo cool!\n\n<Trishe stares, slack-jawed.>\n\nOh, have you seen my friend Steggy? She was here with me, but then there were all these pretty bugs and things, and she ran off after them, and I was too slow to follow her.\n\n<Trishe pouts.>\n\nI'm s'posed to watch Steggy. I'm response-able! And now you're response-able for finding her, okay?", objectives = "Find Steggy and defeat Hidegorger the Everburning in Zul'Aman.", progress = "Have you seen how big the trolls are? Steggy is going to be bigger than the trolls, but she's still little like me.\n\nSteggy needs to eat so she can get bigger. Please find her so I can feed her!", completion = "Steggy is back! You really are response-able." }
WordHunterWoW_QuestEN[90485] = { title = "Afterthought Artifacts", description = "This location is ideal for finding artifacts. Searching through the rubble at the bottom of that lake could reveal many treasures.\n\nIf you have a moment, you're welcome to take a look around yourself. Bring me anything you find and we'll see if it's valuable.", objectives = "Find artifacts in the lake near Camp Stonewash in Zul'Aman.", progress = "Found anything exciting yet?", completion = "My my, what an interesting find!\n\nThere's a lot to be learned from an old pot: how the ancient Amani might have prepared food, the kinds of food they ate, and what they valued most in a meal.\n\nI'll work on analyzing this. You can place those other items to the side. They're far younger than this beauty." }
WordHunterWoW_QuestEN[90486] = { title = "Dangerous Delicacies", description = "A Witherbark troll could survive eatin' each of these ingredients raw, but dey would need aid.\n\nTogether, de ingredients would be deadly. We're going to cook dem into one dish.\n\nDon't worry. I'll show you how to take out enough poison so it tastes good AND has paralytic effects.", objectives = "Cook Blistereel Boar in Camp Stonewash.", progress = "What do you think this is going to taste like? Amaxi says it's absolutely arresting and could kill a stegodon!", completion = "I suppose now we try it. Right, <name>?" }
WordHunterWoW_QuestEN[90493] = { title = "The Heart of Tranquillien", description = "We can't let the Twilight's Blade get away with this. There are innocent citizens all over town who had nothing to do with this cult. You heard the governor: anyone who doesn't join will be executed.\n\nI won't stand for that.\n\nGo--aid any civilians you can find. Get them out of harm's way. If they're being attacked, take their attacker down. Tranquillien will not fall under my watch.", objectives = "Rescue 8 innocent Tranquillien Citizens.", completion = "You're safe, and so are the weary citizens of Tranquillien. Thank the Light." }
WordHunterWoW_QuestEN[90494] = { title = "The Missing Magister", description = "Umbric went to chase down Antenorian when the fighting broke out, but nobody has seen him since. \n\nI trust him to hold his own, but between Kasiea's death and Antenorian's betrayal, I worry he may be so set on revenge that he won't see an attack if one happens. Can you find him for me?\n\nI'll stay here and make sure these civilians remain safe.", objectives = "Find Magister Umbric.", progress = "I will not allow them to get away with this.", completion = "A map of Eversong? With multiple villages marked by the Twilight's Blade!" }
WordHunterWoW_QuestEN[90509] = { title = "The Traitors of Tranquillien", description = "Some of the town's most respected citizens, traitors?\n\nHow long has the Twilight's Blade been here? How many scouts have gone missing? Crimes gone unreported? Innocents recruited by those they thought they could trust?\n\nThey must be stopped. Cut down the traitors. Show them that Tranquillien is no home for cultists.", objectives = "Slay Ranger Lethvalin, Matron Narsilla, and Guard Captain Leonic.", progress = "We cannot allow these traitors to escape!", completion = "We'll need to do more to reverse the damage done here, but this was a good first step. Thank you." }
WordHunterWoW_QuestEN[90517] = { title = "My Part of the Deal", description = "The threat of the Shadowguard to Eco-Dome: Primus is over. My Reshii Ribbon is no longer needed to protect this asset. Take it. Use it wisely. Protect the greatest investment of all--our existence.\n\nStay focused! The Harbinger has already driven off one member of your team. Once you get enough Reshii Ribbons, you still need to fight Dimensius. Find allies who will stand with us, in addition to artifacts.", objectives = "Take Ve'nari's Reshii Ribbon.", progress = "The Reshii Ribbons are a means to get you and your allies to Dimensius. You will need at least two more if this plan is going to work.", completion = "You have my ribbon. Go--track down the rest. Have Locus-Walker contact the other members of the Ravel. Ask the Harbinger if she knows any ancient horrors that have acquired one. Remember rule twelve--it's who you know." }
WordHunterWoW_QuestEN[90533] = { title = "Go Get Orweyna!", description = "Hey! Champ!\n\nLook, I swear I'm glad to see ya. I'm just in a little bit of a diplomatic situation here.\n\nCan you go get Orweyna and bring her back here? See if she'll talk this beast into letting me go?\n\nI'm not an elekk plushie, for cryin' out loud.", objectives = "Go get Orweyna in the Den and find a way to free Gazlowe.", progress = "Never try to take something from a beast like this without offering something better. \n\nI would hate to lose another friend that way.", completion = "I'm pleased that Monte came this way to visit. But I can see that he is as out of his depth here as I was in Undermine." }
WordHunterWoW_QuestEN[90534] = { title = "The Home of the Haranir", description = "I am eager to show Monte my home, but I know it is very different from what he is used to.\n\nCome with us as he meets my people.", objectives = "Accompany Orweyna and Gazlowe around the Cradle and the Den.", completion = "Can't say I've ever seen a place like this before. But I like it. I can see how the haranir were drawn here. How Orweyna grew up here and learned all she learned.\n\nBah, look at me getting sentimental. What's next?" }
WordHunterWoW_QuestEN[90535] = { title = "Leave Your Mark", description = "One thing that is very important to the haranir is our past. Some may remove their ability to hear the Goddess, but we are all connected to who came before us.\n\nYou and Gazlowe are a part of our history now. You have earned the right to leave your mark here in the Den, for as long as the Den remains.\n\nGo, touch the wall with your painted hand, and know that you touch the same stone as generations before you.", objectives = "Paint your mark on the wall of the Den.", progress = "We are continually making ourselves new, even as we hold to what came before. I should remember this more often.", completion = "There. Now you are part of Harandar." }
WordHunterWoW_QuestEN[90536] = { title = "The Tale of Wey'nan's Ward", description = "", objectives = "" }
WordHunterWoW_QuestEN[90537] = { title = "Late Bloomers", description = "It is good to see you again, {name}. Orweyna told me that you might be able to help me with something.\n\nA group of rutaani were due to arrive here earlier today, but they're late. They're coming up from Blooming Terrace with my mentor, Ru'gar, and I am worried they've had trouble on the road.\n\nWill you scout along the road from here down to the Terrace? I'll come up from there and we can meet on the way if we find nothing.", objectives = "Look for the missing company of rutaani and haranir.", progress = "Quietly now. The enemy is close.", completion = "Welcome to Fungal Cleft, <name>. The local fungarians here are more volatile than those at Har'mara.\n\nThey have no concept of balance and strive to spread their spores far and wide, overcrowding the nearby rutaani of Blooming Terrace and threatening to spill out into the rest of Harandar.\n\nThe captured rutaani must be within the settlement." }
WordHunterWoW_QuestEN[90538] = { title = "Prey Contract: Zealous Crusader", description = "A ZEALOUS CRUSADER has been spotted in Eversong!\n\nDifficulty: Hard\n\nAffixes: Grounded!\n\nUnable to use mounts while inside your active Prey Area.", objectives = "" }
WordHunterWoW_QuestEN[90540] = { title = "Rutaani Rescue", description = "Over the hill north of here is a fungarian village, Fungal Cleft. I believe the missing rutaani have been taken there.\n\nThe fate that awaits them is a brutal one if we do not get them back quickly. Usually, fungarians favor hosts that are already dead for their reproductive purposes. The ones here are strangely vicious, however. I have seen some mushroom-covered animals and rutaani who are still moving around! It is unnatural.\n\nGo to Fungal Cleft and see if you can rescue the missing travelers.", objectives = "Rescue 5 Captured Rutaani.", completion = "Good work, <name>. I saw the freed rutaani rushing toward Har'mara.\n\nThese fungarians were in pursuit, but I got the jump on them." }
WordHunterWoW_QuestEN[90544] = { title = "Thief at Bark", description = "<Luma stands in front of you, ears perked, thankful for your help.\n\nShe lets out a short bark, tail wagging once before trotting a few steps forward, then pausing.\n\nGlancing back, Luma waits expectantly. Her body language pleads, \"Come on, follow me!\">", objectives = "Follow Luma.", progress = "<Luma appears to be waiting for your approval.>", completion = "<Luma nudges a small reward into your hand, as if in appreciation for your help.\n\nPerhaps there is no reason to be concerned over the amount of stolen items in the treasure pile after all.>" }
WordHunterWoW_QuestEN[90545] = { title = "A Reel Problem", description = "An essential component of the Oasis ecosystem is the aquatic life within our small lake. \n\nIt appears that artificial organisms known as Hyrobites are in the lake. Originally introduced to remove toxins in the water, their continued presence threatens the equilibrium of the water.\n\nPlease remove these mechanical fish immediately!", objectives = "Catch 7 Hydrobites around the Oasis.", progress = "Did you catch those fish?", completion = "Fine work. I am most pleased to not have to handle those nasty fish myself." }
WordHunterWoW_QuestEN[90546] = { title = "Missing Paladins", description = "Some of our brothers and sisters in the Light were responding to a request for help by the Magisters at the Sanctum of the Moon. Apparently the Twilight's Blade has been seen lurking in the area.\n\nWe expected to hear back from them awhile ago, but we've heard nothing.\n\nGiven the strength of the party that went, Salandria and I wanted some additional backup before we looked into the issue. Care to lend a hand?", objectives = "Meet Taelia at the Sanctum of the Moon.", completion = "Well, the cultists don't seem to be hiding now. But I don't see any of our missing paladins." }
WordHunterWoW_QuestEN[90547] = { title = "Missing Paladins", description = "Some of our brothers and sisters in the Light--including my friend Dawnheart--were responding to a request for help by the Magisters at the Sanctum of the Moon. Apparently the Twilight's Blade has been seen lurking in the area.\n\nWe expected to hear back from them awhile ago, but we've heard nothing.\n\nGiven the strength of the party that went, Taelia and I wanted some additional backup before we looked into the issue. Care to lend a hand?", objectives = "Meet Salandria at the Sanctum of the Moon.", completion = "The cultists are boldly showing themselves, but I don't see Dawnheart and the others." }
WordHunterWoW_QuestEN[90548] = { title = "Twilight Missive", description = "We need to figure out what the Twilight's Blade is trying to do here. We also need to get rid of these cultists so the Magisters can get back to their work building runestones.\n\nTake out as many cultists as you can. See if any of them are carrying information we can use.", objectives = "Collect 6 missives.", progress = "What'd you find?", completion = "Good job out there. We'll need to find more if we're going to find our missing friends." }
WordHunterWoW_QuestEN[90549] = { title = "Signs of the Struggle", description = "The Twilight's Blade are acting boldly in their takeover here. None of these Magisters have any information for us.\n\nWe'll hold this end of the bridge and protect any Magisters who escape. You get in there and look for signs of the missing paladins. Were they taken? Did they put up a fight, or were they ambushed? Are they still armed?\n\nI have a bad feeling we are running out of time.", objectives = "Look for signs of the lost paladins.", completion = "Well, we know more. They were here at one point but they've been taken, unarmed. Now we need to find out where to." }
WordHunterWoW_QuestEN[90550] = { title = "A Somber Sun", description = "<The corpse of this Blood Knight has been horribly mangled and tainted by Void magic. He put up a fight, but was unable to survive.\n\nSalandria will want to know of this.>", objectives = "Report the corpse to Salandria.", completion = "Those bastards... They'll pay for Sombersun's death!" }
WordHunterWoW_QuestEN[90551] = { title = "Captured Information", description = "We need to find out where the paladins were taken. Easiest way to do that is ask... under a bit of duress.\n\nFind an isolated target, beat them down, and then drag them to the hollow on the other side of the Sanctum. Taelia and I will get the civilians to safety and meet you there.", objectives = "Capture and bring an isolated cultist to the Hollow Grove.", progress = "Did you capture a cultist?", completion = "Good. Now we can force some answers." }
WordHunterWoW_QuestEN[90552] = { title = "Interrogation", description = "We need to know where Dawnheart and the others were taken. This one doesn't seem to want to talk... but we can fix that.", objectives = "Interrogate the captive cultist.", completion = "The Ruins of Deatholme. They better be alive when we get there!" }
WordHunterWoW_QuestEN[90553] = { title = "Executing the Blades", description = "Those monsters will pay for what they have done!\n\nTake out any Twilight's Blade cultists you see. We'll scour them from Eversong for good!", objectives = "Kill 15 cultists.", progress = "Show them no mercy!", completion = "We have wiped Eversong clean of their filth." }
WordHunterWoW_QuestEN[90554] = { title = "Leave Ashes in Your Wake", description = "We need to make it clear to these cultists that they aren't welcome.\n\nTear down their banners, and destroy their books and supplies. Do whatever you can to wreck their camp!", objectives = "Wreck the Twilight's Blade camp in Deatholme.", progress = "Have you destroyed the camp?", completion = "Good work. Even if they come crawling back, they won't find much." }
WordHunterWoW_QuestEN[90555] = { title = "Blessing of Freedom", description = "Our friends are being held in this area. I have no idea what state we'll find them in, but I pray they are at least alive.\n\nHelp me find and free our missing paladins in the Ruins of Deatholme.", objectives = "Free paladins in the Ruins of Deatholme.", progress = "Have we found everyone yet?", completion = "All things considered, this was a good result. I wish... well. We couldn't save everyone, but we did save most of them. I guess that's as much as anyone can ask for in a situation like this." }
WordHunterWoW_QuestEN[90556] = { title = "Cutting off the Head", description = "We'll crush their leader! For justice and the Light!", objectives = "Slay Overseer Mognak.", progress = "May their ilk never come around here again!", completion = "We'll mourn the lost and celebrate those who survived. Thank you, <name>." }
WordHunterWoW_QuestEN[90557] = { title = "Whose Key is This?", description = "", objectives = "Hey pal, we found a weird key lying around. No idea who it belongs to, it ain't for the Incontinental. You want it?" }
WordHunterWoW_QuestEN[90568] = { title = "Unlikely Friends", description = "This old Witherbark pot you found is quite interesting.\n\nI've made a series of notes on its construction and use, but now it's time we speak to Elder Ren'zen. The pot should be returned to him. And he can fill in the gaps in the pot's story!\n\nLet's speak with him in the village.", objectives = "Speak with Elder Ren'zen in Witherbark Village.", completion = "Seeker Crikkash says he wanted to wait for you to arrive before showing me what he's found." }
WordHunterWoW_QuestEN[90569] = { title = "Back in the Bag", description = "What a mess this is. The sack you found was supposed to be filled with seeds. They're part of an important cultivation project that Ru'gar was working on.\n\nIt appears the fungarians made off with the seeds when they captured the rutaani.\n\nWhile you're looking for the rutaani, see if you can recover the seeds that were stolen.", objectives = "Collect 6 Stolen Seeds.", progress = "I can't bear to think of what the fungarians will do to the seeds that Ru'gar has been carefully cultivating. He had been working with the rutaani on plants that were more hardy and produced greater yield. \n\nHis work should not be lost.", completion = "You found so many! Thank you.\n\nThese seeds were very important to Ru'gar. I don't know much about gardening, but maybe I can give it a try." }
WordHunterWoW_QuestEN[90570] = { title = "To the Ruins of Deatholme", description = "Thanks to our \"friend\" here, we know the missing paladins were taken to Deatholme. We have to find them before it's too late! \n\nSalandria and I will meet you there.", objectives = "Meet Taelia and Salandria at Deatholme.", completion = "Good--you made it. Now let's save those paladins." }
WordHunterWoW_QuestEN[90571] = { title = "The Lay of the Beast", description = "Your friend's scheme to blow up the Nexus-Point was adorable. You all looked so determined, I didn't have the heart to tell you how simple the solution really is.\n\nThe Mantle of Predation will allow you to enter the Nexus-Points and weaken the storm. Alas, it's claiming the Mantle that will truly test you.\n\nBorrow my pet--see through his eyes. I'll show you who you'll steal the Mantle from.", objectives = "Use Decimus's pet to scout the Voidspire.", progress = "Go on. Ciphus won't mind.", completion = "There you have it--simply steal the Mantle from Terminas. I'd recommend acting quickly. Who knows when Terminas will return to the Obscurion Citadel.\n\nA shame about Ciphus. I was planning to devour him myself once I'd fattened him up." }
WordHunterWoW_QuestEN[90573] = { title = "Fortify the Runestones: Magisters", description = "We placed a number of runestones throughout Eversong Woods, each one charged with protective arcane magic intended to ward off the Lightbloom.\n\nWhile highly effective, the runestones require an immense amount of power to function. They must be regularly fed with latent arcana lest they weaken.\n\nAs Magisters, it is our duty to maintain the runestones--especially when the eyes of this Haven are upon us. Recharge their arcane power and defend them from those who would threaten us.", objectives = "Collect Latent Arcana from Saltheril's Soiree weekly quests and Misplaced Tomes, then use it to charge and defend a Runestone in Eversong Woods.", progress = "We must ensure the runestones are charged and defended.", completion = "Your strength is matched only by your acuity, my dear. I will ensure everyone knows how marvelously you have performed today." }
WordHunterWoW_QuestEN[90574] = { title = "Fortify the Runestones: Blood Knights", description = "The Magisters placed a number of runestones throughout Eversong Woods, each one charged with protective arcane magic intended to ward off the Lightbloom.\n\nNaturally, the runestones require an immense amount of power to function. They can be fed with latent arcana, but that power draws enemies seeking to claim it.\n\nAs Blood Knights, it is our duty to defend the runestones--especially when the eyes of this Haven are upon us. Recharge their arcane power and defend them from those who would threaten us.", objectives = "Collect Latent Arcana from Saltheril's Soiree weekly quests and Coalesced Light, then use it to charge and defend a Runestone in Eversong Woods.", progress = "Maintaining the safety of Eversong is of utmost importance.", completion = "Your deeds honor us, <name>. You have fought well this day." }
WordHunterWoW_QuestEN[90575] = { title = "Fortify the Runestones: Farstriders", description = "The Magisters placed a handful of runestones across Eversong, each one charged with arcane magic that wards off the Lightbloom.\n\nAs you might guess, the runestones require a huge amount of power to function. The Magisters feed them with latent arcana, but that kind of power draws a lot of attention. Bad attention.\n\nAs Farstriders, it's our duty to defend Eversong from those kinds of threats--especially when the Haven is looking at us. Go recharge the runestones and fight off whatever tries to stop you.", objectives = "Collect Latent Arcana from Saltheril's Soiree weekly quests and Ranger's Caches, then use it to charge and defend a Runestone in Eversong Woods.", progress = "We need to keep those runestones safe.", completion = "Nice work. You know how to see a mission through smoothly. I have a few ranger recruits who could learn a thing or two from you." }
WordHunterWoW_QuestEN[90576] = { title = "Fortify the Runestones: Shades of the Row", description = "Have you seen the runestones out in Eversong? Huge rocks full of arcane magic that ward off the Lightbloom.\n\nI'm not the magic type, but I know an opportunity when I see one. Those runestones need a lot of power to work. If we help keep them charged, there are a lot of people who would owe us favors--and favors are even better than gold.\n\nHere's the plan: I help you get some latent arcana, you drop it into the runestones, beat up whatever tries to stop you, then we bask in the accolades. Deal?", objectives = "Collect Latent Arcana from Saltheril's Soiree weekly quests and Dead Drops, then use it to charge and defend a Runestone in Eversong Woods.", progress = "Those runestones aren't going to charge themselves.", completion = "Ha! I shouldn't be surprised you pulled that off so well, but here we are. We've already got people looking at us like we're miracle workers.\n\nAll thanks to you, <name>." }
WordHunterWoW_QuestEN[90601] = { title = "Gathering Glowshrooms", description = "Ru'gar used to tell me about how he'd sneak into the nearby cave to harvest glowshrooms. They seemed to be integral to the development of the tla'tak seeds he was cultivating. Will you collect some of the mushrooms within?\n\nOh, and Ru'gar mentioned that the mushrooms have strange properties when harvested. I'm not sure what he meant by that, but maybe stay on your toes.", objectives = "Collect 6 Glowshrooms.", progress = "Ru'gar mentioned that the glowshrooms helped create a more robust harvest when they were mixed into the dirt he'd planted crops in. How he even figured that out, I'll never know.\n\nI would like to carry on Ru'gar's work. Since we're already here, we might as well gather what we can.", completion = "Ah, you return! And with so many glowshrooms. Excellent. I hope you didn't have anything strange happen.\n\nThank you for collecting all of these. It will take me some time to reproduce Ru'gar's methods, but I have hope now that we can continue his work." }
WordHunterWoW_QuestEN[90602] = { title = "Gomphusta", description = "I would ask one last thing of you. I've heard quite a few of the fungarians mention their leader, Gomphusta. It seems he's behind the uptick in their violence and the reason they're stealing the seeds.\n\nWhile you're in the cave, find him and take him out. Without Gomphusta pulling the strings, the other fungarians will be thrown into chaos and won't be able to organize ambushes as well.", objectives = "Kill Gomphusta.", progress = "The fungarians aren't always this violent and aggressive. Gomphusta must be the force driving them. He seems to be the one infecting living creatures with spores.\n\nWith him gone, the fungarians may return to a more balanced state.", completion = "What is this? Ru'gar's notes on his cultivation efforts!\n\nThis is fantastic. I can try to reproduce his work now.\n\nGood work taking out Gomphusta, also. May this throw the fungarians into disarray and keep travelers on the roads safer." }
WordHunterWoW_QuestEN[90615] = { title = "Be Grudge You", description = "You look... different! Ever be to Grudge Pit?\n\nGrudge Pit is great place! Full of fighting and cheering and fungarians. Also decaying!\n\nBoletus is always look for strong creatures to be kill in Grudge Pit. Or for making others be kill.\n\nAre strong creature? Should go to Pit!", objectives = "Speak with Boletus at the Grudge Pit.", completion = "You look like could put up strong fight before start decay.\n\nWould be very interesting!" }
WordHunterWoW_QuestEN[90616] = { title = "You Strong?", description = "You look strong.\n\nShould test yourself in our arena.\n\nSee how you compare to strong fungarians.", objectives = "Kill enemies in the Grudge Pit.", progress = "Many fungarians watch the fighting.\n\nAlways so exciting!", completion = "We, uh... you are so strong.\n\nHow, er...? You very different.\n\nTeach fungarians, to be different like you?" }
WordHunterWoW_QuestEN[90617] = { title = "A Few Fun Guys", description = "You are very strong, {name}.\n\nWill teach fungarians to fight?\n\nMuch we could learn from you.\n\nMany fungarians watch battle.\n\nAsk if they want to be strong in Pit.", objectives = "Recruit 3 Fungarians.", completion = "You found ones to teach?\n\nFirst step is to fight, see what can do!" }
WordHunterWoW_QuestEN[90619] = { title = "What Doesn't Kill Them", description = "Have team, now are ready to fight.\n\nTake your team to empty area. Practice fight, and see what can do.", objectives = "Spar with your teammates.", progress = "We fighting you?\n\nYou are strong.\n\nFight together is good practice for be strong.", completion = "Eyes are open, <name>! We can be strong, too.\n\nWe will be strong, like you!\n\nWhen hurt, fungarians grow stronger. You hurt lot, we grow stronger lot.\n\nMust go tell Boletus we ready!" }
WordHunterWoW_QuestEN[90620] = { title = "To the Ring", description = "TeamName? Not bad. I like!\n\nYou and the TeamName head on down, and we say words.\n\nYou fight Spore Storm. If beat, fight Cap Clash.\n\nIf beat, fight Fungus Force.\n\nAlways-winners are Glow Guard. You won't beat.\n\nNo run out! Run out is big, big lose.", objectives = "Go fight with your team.", completion = "Was sure Brakko was strong enough. Was train with strong <name>!\n\nBut Brakko is scared of sporegliders. Will eat cap!\n\nBrakko so sad to fail <name>.\n\nZiny and Tuktuk too. All run out.\n\nWe run out, and Fungal Fellosh were lose.\n\nBut how can not run out, when sporegliders attack?" }
WordHunterWoW_QuestEN[90621] = { title = "Tiny Heroes' Journeys", description = "You taught them. Why did they run out?\n\nAll fungarians were excited to see if a {race} could teach fungarians for be strong.\n\nYou try one more time, okay?\n\nFirst do what need to get them ready.", objectives = "Help each member of the team overcome their challenges.", completion = "Done teaching, now? Let's see what Fungal Fellowship can do." }
WordHunterWoW_QuestEN[90622] = { title = "Not-Yet Defeated Champions", description = "{name}, the PHTeamname look stronger now! More ready. Hope they won't run again.\n\nNext fight is against Glow Guard. Glow Guard always never lose.\n\nHope your training makes fight better, before TEAMNAME lose.\n\nWill be fun for watch!", objectives = "Enter the Grudge Pit and defeat the Glow Guard.", progress = "The Grudge Pit is always looking for new champions, <name>. Until now, we've just been finding the old ones again.", completion = "Wow, shocked! Fungal Fellowship beat Glow Guard!\n\nI knew <name> strong. But did not know if training could be enough.\n\nNot one fungarian was bet on Fungal Fellowship. We did not think Glow Guard could be defeat. \n\nNow every fungarian know <name> is best teacher of strong!" }
