WordHunterWoW_QuestEN[90659] = { title = "Something Borrowed", description = "Now that you have your infinite bronze, we just need to select the right artifact for you, shape the bronze into a suitable simulacrum of the weapon, and then reach through a temporal knot and swap them.\n\nNo one will be the wiser.\n\nAll we have to do is remember to reclaim the simulacrum in this timeline and everything will work itself out.\n\nLet's start by selecting your specialization, that'll determine which artifact we'll be borrowing.", objectives = "Select your artifact weapon.", progress = "Every artifacts needs a mighty hero to wield it.", completion = "Intriguing. This artifact's potential has been deepened, perhaps by the fraying of this timeline. It can harness more power than any incarnation of it that I have yet encountered.\n\nLet me record that data point for Moratari.\n\nOh, important reminder--don't forget to recover the bronze simulacrum later or things might get... funky.\n\nAnd lastly, maybe don't mention to people how you got that. It could ruin the experiment." }
WordHunterWoW_QuestEN[90660] = { title = "A Golden Circumstance", description = "", objectives = "I wish you the best of luck in all your adventures, <name>." }
WordHunterWoW_QuestEN[90661] = { title = "Dastardly Duos", description = "", objectives = "" }
WordHunterWoW_QuestEN[90663] = { title = "Stealing What is Ours", description = "Ve'nari has called in a lot of favors to get the Oasis reclamation effort off the ground. Plenty of Tazavesh merchants have donated to the cause, though some have seen fit to help themselves instead.\n\nA large shipment of stasis-sealed items was stolen from the docks by an untrustworthy importer. I could use someone of your skill to recover the shipment.", objectives = "Speak with Xy'dax and recover the Missing Imports.", progress = "Have you recovered my missing items?", completion = "I wasn't expecting quite so much! Perhaps this is not all my imports? \n\nStill, it's good to see these items. I have a little something for your troubles." }
WordHunterWoW_QuestEN[90665] = { title = "Carved Crests", description = "", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has set aside a fund to encourage such initiative." }
WordHunterWoW_QuestEN[90666] = { title = "A Bundle of Crystals", description = "", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has set aside a fund to encourage such initiative." }
WordHunterWoW_QuestEN[90667] = { title = "Enchanted Runed Ethereal Crest", description = "", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has set aside a fund to encourage such initiative." }
WordHunterWoW_QuestEN[90669] = { title = "Gold is Gold", description = "Hey! You there.\n\n<Sarvi beckons you closer and lowers her voice.>\n\nYou looking for work? A Magister gave me five gold to find an adventuring type to do some sort of job for him. He said if the person gets it done, I get five more. That'll feed me for months.\n\nYou fit the bill. If you want to try to get paid too, he has a study over by the harbor. Real fancy place--you can't miss it. The guy's name is Aradis.", objectives = "Speak to Magister Aradis in his study near the Silvermoon Harbor.", completion = "Ah, so the ruffian was successful.\n\nYou do certainly look capable. Let us speak, shall we?" }
WordHunterWoW_QuestEN[90690] = { title = "Charge of the Vanguard", description = "Turalyon reports the Vanguard of the Light is prepared to march on Xal'atath's stronghold.\n\nWould that I could join you for the charge. I will keep my retainer of forces here to maintain the defense of the Sunwell and Silvermoon while you take the fight to our enemy. \n\nMuster in the Voidstorm, take the fight to the Voidspire, and bring an end to this great enemy. Good hunting.", objectives = "" }
WordHunterWoW_QuestEN[90701] = { title = "Cowardly Cheery Bombs", description = "Goblins love bombs, I get that. But does EVERYTHING have to blow up?\n\nDo me a favor: In the next Dastardly Duos match you enter, find a cheery bomb inside one of the wooden tree and planter props.\n\nAfter you find the bomb, but before it  \"blows up\"... smack it for me. Don't worry, they're cowards.", objectives = "Find a Cheery Bomb, hidden inside a Dastardly prop. Smack it before it blows up.", progress = "Those cheery bombs are asking for it, <name>. Find one in a Dastardly Duos match and smack it!", completion = "Way to go, <name>. You have to show those bombs who's boss, you know?" }
WordHunterWoW_QuestEN[90705] = { title = "Lorewalking", description = "Are you curious about your world's history? Would you like to learn more?\n\nLi Li Stormstout has started her Lorewalking apprenticeship. With all her travels, she has gathered many stories of important events and figures across Azeroth and beyond and is eager to share them!\n\nPay her a visit in your capital city!", objectives = "Find Lorewalker Cho in Dornogal, Stormwind, or Orgrimmar.", completion = "Oh? Lali is sending vistors my way, now? \n\n<Lorewalker Cho laughs a deep, belly laugh.> \n\nOf course she is! \n\nAh, but she is correct. The only thing I love more than gathering stories is telling them! Sit down, let me share a tale with you." }
WordHunterWoW_QuestEN[90718] = { title = "Request of the Arcantina", description = "Ah, {name}!\n\nI hear you have a standing invitation to Archmage Khadgar's... Arcantina?\n\nCan you go there for me and bring this missive to the Archmage? I need to source reagents for the sheer volume of telemancy spells I have been asked to conjure.\n\nMagister's Terrace has been an excellent source up until recent events but really I need the Kirin Tor to loan me some of their harder to find ingredients.", objectives = "" }
WordHunterWoW_QuestEN[90719] = { title = "Borrowing Corruption", description = "Adventurer, I have made an amazing discovery. \n\nAnalyzing the memories from the time I have discovered that I might be able to recreate the corruption effects that have been wielded in the past. Albeit in a much more controlled way. \n\nI will need you gather some black blood residue from defeating the bosses of the Corrupted or Lost areas of the map and a few more of the displaced corrupted mementos.", objectives = "Find Black Blood Residue and Displaced Corrupted Mementos from the bosses of the Corrupted and Lost areas of the Horrific Visions.", progress = "Were you successful?", completion = "Yes, by combining this residue with the displaced corrupted mementos I can... yeah just like so... and then with a bit of my bronze magic... there. Done.\n\nNow that I have a working knowledge I can also make more if you bring me additional displaced corrupted mementos. I will see if I can refine the process anymore. Check back with me later." }
WordHunterWoW_QuestEN[90724] = { title = "The Broken Sky", description = "All those people. Our army. Our heroes. Our leaders.\n\nGone.\n\nWe are exposed here. Umbric's tether saved us, but we need to ensure we survive this. Report to Lor'themar and tell him what transpired in the Voidspire. I will get Umbric to safety and learn what I can here.", objectives = "Report to Lor'themar in Silvermoon City.All those people. Our army. Our heroes. Our leaders.\n\nGone.\n\nWe are exposed here. Umbric's tether saved us, but we need to ensure we survive this. Report to Lor'themar and tell him what transpired in the Voidspire. I will get Umbric to safety and learn what I can here.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[90729] = { title = "Win-Win Situation", description = "Not everything you recovered yesterday was mine, but let's be honest--we're going to keep it anyway!\n\nXy'daz has been ripping people off for years. It's his turn to take a loss!\n\nNow, this can work in both our favors. You sell off half of the leftover goods for me, and I'll let you keep the rest!", objectives = "Sell 6 Shadowtrade Overstock.", progress = "Did you sell the items?", completion = "You did so well! I may have to employ you more often!" }
WordHunterWoW_QuestEN[90731] = { title = "Enhancing Corruption", description = "Welcome back adventurer. I have made a new discovery but I need to test it out. \n\nHidden in the Lost areas of the Horrific Visions I believe is a rare black blood coagulate. This might be the key to increasing the power of the corruption effects... in a safe way. \n\nIf you can go into these areas and find this item and also bring me back more displaced corrupted mementos I should be able to increase the potency of the corruption effects.", objectives = "Find Black Blood Coagulate and Displaced Corrupted Mementos from the bosses of the Lost areas of the Horrific Visions.", progress = "Were you successful?", completion = "Ok, this is promising... the coagulate catalyzes slower so the increased corruption is more contained... yes, this allows a higher yield of corrupted material without any negative side effects.\n\nAlas, I cannot keep it stable for long. These effects will not last. I am sorry adventurer but we should take advantage of the effects while we can. \n\nAgain, if you bring me additional displaced corrupted mementos I can make you more of these greater corruptions." }
WordHunterWoW_QuestEN[90733] = { title = "The Listener", description = "Now that you've learned about our legends, you've earned the notice of one of our elders. He wants to meet you.\n\nHis name is Aksem, and he knows things that the rest of us have never learned. History that remains hidden, even in the paintings.\n\nGo and introduce yourself. He's expecting you.", objectives = "Speak to Aksem in the Den.", completion = "Yes, I wanted to speak with you. \n\nThere are many truths that are hidden, even to the oldest living haranir. Continue to learn and they may be revealed.\n\nShow respect to our history, and I will eventually tell you more." }
WordHunterWoW_QuestEN[90734] = { title = "In the Name of the Goddess", description = "The high priest Aksem has asked for you again. He said you are not the only one on a quest for knowledge about the deep history of Harandar.\n\nGo to him. I believe he already has another guest who is also interested in learning this hidden history.", objectives = "Return to Aksem in the Den." }
WordHunterWoW_QuestEN[90735] = { title = "The Stolen Staff", description = "This time, I do not have a story for you. \n\nInstead, Aksem has asked that you meet with him to help recover the next of the relics. Go to speak with him, and he will tell you more of what you must do.", objectives = "Speak to Aksem in the Den.This time, I do not have a story for you. \n\nInstead, Aksem has asked that you meet with him to help recover the next of the relics. Go to speak with him, and he will tell you more of what you must do.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[90736] = { title = "That's Not Yours", description = "The rutaani in the Blossoming Terrace are crafty. They've trained their petalwings to search and grab anything shiny that rolls down from the Den.\n\nAnd, I suspect, sometimes they grab things that haven't naturally fallen.\n\nSo we want to get those things back. That's where you come in.\n\nGo into the terrace, and don't hesitate to use force to send a message. That's a language we all understand.", objectives = "Retrieve 8 Stolen Belongings from the Blossoming Terrace." }
WordHunterWoW_QuestEN[90737] = { title = "Nested Clues", description = "You're looking for a staff called the Root of the World. It's a powerful twist of woven roots, back from before the haranir traveled deep into the mountain.\n\nIt's irreplaceable, as Aksem knows. So if a rutaani petalwing stole it, that's embarrassing. The only way for everyone to save face is to get it back.\n\nSearch the nests of the bigger birds. They've been trained to look for more valuable items.", objectives = "Uncover clues about where the stolen rootstaff could be." }
WordHunterWoW_QuestEN[90738] = { title = "To the Blossoming Terrace", description = "When the haranir first arrived in Harandar, they brought with them a staff formed of the roots of a great tree. That tree has since gone away, but the roots remain.\n\nIt has been our duty to protect that staff and pass it on through the generations, but now it has been stolen.\n\nYour task is to find it and return it to Zur'Ashar Kassameh.\n\nGo into the mists below the Den and seek out the Shul'ka. They will guide you on your search.", objectives = "Meet Shul'ka Seila outside the Blossoming Terrace.When the haranir first arrived in Harandar, they brought with them a staff formed of the roots of a great tree. That tree has since gone away, but the roots remain.\n\nIt has been our duty to protect that staff and pass it on through the generations, but now it has been stolen.\n\nYour task is to find it and return it to Zur'Ashar Kassameh.\n\nGo into the mists below the Den and seek out the Shul'ka. They will guide you on your search.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[90739] = { title = "The Root of Things", description = "Looks like you didn't find any sign of the rootstaff among all the thiever's nests. That's a good thing, honestly.\n\nBut there's more to this test than just recovering stolen goods. Yes, it's a test. You're seeking secret knowledge. That means something here doesn't add up, and the real answer is waiting to be found.\n\nSo, come find me when you're ready to get that answer.", objectives = "Follow Shul'ka Seila and recover the missing staff." }
WordHunterWoW_QuestEN[90740] = { title = "A Legend to Know", description = "I am entrusted with many secrets, and the benefit of that is not having to explain myself often.\n\nYou have recovered the Root of the World, as I asked. Now, take it to Zur'ashar Kassemeh, and learn more about it.\n\nThere will be more for you, later.", objectives = "Return to Zur'ashar Kassameh.I am entrusted with many secrets, and the benefit of that is not having to explain myself often.\n\nYou have recovered the Root of the World, as I asked. Now, take it to Zur'ashar Kassemeh, and learn more about it.\n\nThere will be more for you, later.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[90741] = { title = "Once More Into the Rift", description = "Aksem has asked for you again. He says he's ready for you to undergo the final ritual for the knowledge he wants to teach you.\n\nI admit, I'm envious, but I do not envy the trials you'll need to undergo in order to prepare for this knowledge.\n\nGo speak to Aksem, and do as he says. Orweyna will be joining you.", objectives = "" }
WordHunterWoW_QuestEN[90742] = { title = "Shrouded by Aln'hara", description = "As you know well by now, the creatures in the rift are infused with the essence of Aln'hara. What we need is that essence mixed with water.\n\nAksem wants us to collect water here and then infuse the essence of Aln'hara into it. I can only imagine what it might be used for.", objectives = "" }
WordHunterWoW_QuestEN[90743] = { title = "Ritual Reinforcement", description = "You know the dangers of the Rift of Aln, but this is the best place to prepare for the kind of ritual Aksem wants to perform.\n\nGo about the rift and place offerings to prepare yourself.", objectives = "" }
WordHunterWoW_QuestEN[90744] = { title = "The Dreamrift: Malformed Mystery", description = "We have prepared ourselves as best we can for the next stage. Now, we must venture into the deepest part of the Rift of Aln.\n\nInto the Dreamrift.\n\nIt's a place so dangerous that even the Shul'ka hesitate to go, but we must. Aksem needs us to collect the most powerful infusion of Aln there is.\n\nAre you ready?", objectives = "" }
WordHunterWoW_QuestEN[90745] = { title = "The Empty Cradle", description = "You have ventured far, fought deep, and learned many things about our history to be here.\n\nNow it's time to know the truth. Prepare yourself.", objectives = "" }
WordHunterWoW_QuestEN[90746] = { title = "The Elves Assemble", description = "The time for preparations have passed. Xal'atath's forces are upon us.\n\nJoin us, champion, as we must rebuff this assault and then press our attack on the Darkwell.", objectives = "" }
WordHunterWoW_QuestEN[90747] = { title = "The Wrong Bluecephalus", description = "We may have gotten off on the wrong foot, but there's something you should know.\n\nThat old slateback you used to haul all those imports? I thought it was just another worn-out nag, but it turns out it was the real treasure all along.\n\nA rare bluecephalus, worth a fortune!\n\nYou might want to figure out where it went, and why Ba'eth isn't exactly rushing to share the profits!", objectives = "Speak with Ba'eth and others.", progress = "Are you ready to help?", completion = "Good. This will be a profitable venture... for me." }
WordHunterWoW_QuestEN[90748] = { title = "Quel'Danas", description = "Champion, the time has come to see an end to the Darkwell.\n\nI do not know what awaits us beyond the gates of Quel'Danas, but we cannot tarry any longer. The Void continues to pour into the Darkwell, transforming it. \n\nArator is at the head of our combined armies. He has asked you and your strongest allies join him at his side. \n\nIt is time to end this and take back our well.", objectives = "" }
WordHunterWoW_QuestEN[90749] = { title = "Our Mutual Enemy", description = "<Liadrin lowers her voice, speaking only to you.>\n\nWe have two choices. We can either continue to talk to the Amani or fight our way inside.\n\nI would still prefer to negotiate passage with Zul'jarra, but if our diplomacy goes awry, be ready.\n\nFor now, follow my lead.", objectives = "Follow Lady Liadrin into Zul'Aman.", completion = "I must say I am... surprised that Zul'jarra allowed us passage. It has been many years since I or anyone from Eversong has stepped foot on this side of the border.\n\nStay sharp. This is a volatile situation. We may have to do more to engender their trust.\n\nBut don't turn your back on the Amani." }
WordHunterWoW_QuestEN[90751] = { title = "Lumber Processing", description = "", objectives = "" }
WordHunterWoW_QuestEN[90754] = { title = "Skyriding", description = "This land is more vast than I remember. However, a good scholar is always prepared.\n\nTo cover more ground, you will need a winged mount and the skill to ride it swiftly.\n\nI recall Lord Andestrasz helping us with this in the past, near the Timeless Isle in Pandaria. Let's send you back to that moment in time, so you can learn from him.\n\nDon't wander too far in distant lands, you're still needed back here. Return via the portal when you have finished your instructions.", objectives = "Take Moratari's portal to Lord Andestrasz.", progress = "All things come with practice.", completion = "Let us get started. We will focus on the basics.\n\nDo not worry, the fancy maneuvers will come later." }
WordHunterWoW_QuestEN[90755] = { title = "Time Flies", description = "That should suffice for now. Remember the basics and you will improve in time.\n\nSpeaking of time, you had best be on your way. The portal there will take you back to Moratari.", objectives = "Return to Moratari.", completion = "Excellent. This should expedite our research." }
WordHunterWoW_QuestEN[90759] = { title = "The Cult Within", description = "<A missive written on shimmering vellum unfurls before you.>\n\n{name},\n\nRumors suggest that Xal'atath's cult, the Twilight's Blade, has been recruiting in Alliance cities. Meet me in Stormwind to investigate these rumors. If the cult is there, then we must stamp it out at once.\n\nMagister Umbric", objectives = "Meet Magister Umbric in Stormwind.", completion = "Thank you for coming, <name>. The Twilight's Blade cannot be allowed to roam our cities." }
WordHunterWoW_QuestEN[90760] = { title = "Avoiding Blame", description = "Apocalyptic threats have taken many forms in Azeroth's history, but today we face Xal'atath and her Twilight's Blade.\n\nI fear that people are falling into hopelessness as the Radiant Song cries a warning. The Twilight's Blade could use that despair to draw them into their ranks.\n\nMy mages have identified this district as housing a peculiar amount of void energy. Investigate and stop any cultists you may find.", objectives = "Disperse 6 Suspicious Citizens in Stormwind.", progress = "I understand the comfort the void can provide. But surrendering to it completely is not the peace many are led to believe.", completion = "There are Twilight's Blade in the city. If they are here, they are certainly recruiting elsewhere.\n\nWe have more work to do." }
WordHunterWoW_QuestEN[90761] = { title = "Avoiding Blame", description = "The cult of twilight has long been dedicated to ending Azeroth. That they ally with Xal'atath is no surprise.\n\nIf the Twilight's Blade are indoctrinating citizens, we must stop them. We cannot permit the weak to fall to the Void's dark designs.\n\nThe Cleft of Shadow is home to many practitioners of unsavory magic. Identify and end any cultists you may find there.", objectives = "Disperse 6 Suspicious Citizens in Orgrimmar.", progress = "<Rommath sneers at you.>\n\nThe calm and comfort the Void offers is a lie. You would do well to abandon it.", completion = "The Radiant Song casts a long, dark shadow on Azeroth. The Twilight's Blade are taking advantage of it.\n\nWe have work to do." }
WordHunterWoW_QuestEN[90762] = { title = "The Twilight Highlands", description = "I've spoken with Grand Magister Rommath. Despite our differences, it seems we are aligned in purpose.\n\nWe have both found evidence that Twilight's Blade cultists are convening in the Twilight Highlands. It's a place long scarred by the cult's misdeeds. And it's a suitable staging ground for an attack.\n\nMeet us there so we may continue our investigation.", objectives = "Meet Grand Magister Rommath in the Twilight Highlands.", completion = "Well. It seems we are to be working together to investigate the Twilight's Blade.\n\nI do hope you're prepared." }
WordHunterWoW_QuestEN[90763] = { title = "The Twilight Highlands", description = "I've received word from Magister Umbric. He has found similar evidence that the Twilight's Blade are recruiting in Stormwind.\n\nThe Void poses an existential threat to all of Azeroth. We must stop the cult at its source.\n\nWe've agreed to meet in the cult's homeland, the Twilight Highlands. Find me there so we may continue our investigation.", objectives = "Meet Grand Magister Rommath in the Twilight Highlands.", completion = "Good, you've arrived. \n\nKeep an eye on our allies. We may be working with them to stop the Twilight's Blade, but the Void is insidious. \n\nThey cannot be fully trusted." }
WordHunterWoW_QuestEN[90764] = { title = "The Cult Within", description = "<A missive written on fine parchment unfurls before you.>\n\n{name},\n\nI have heard unsettling rumors that Xal'atath's cult, the Twilight's Blade, is recruiting within Horde cities. Meet me in Orgrimmar so we may root out this evil. We cannot suffer a single cultist within our walls.\n\nGrand Magister Rommath", objectives = "Meet Grand Magister Rommath in Orgrimmar.", completion = "Good, you're here. We cannot let the Twilight's Blade gain ground in the city." }
WordHunterWoW_QuestEN[90765] = { title = "Midnight Dress", description = "Cult activity in the area has risen significantly. While we are gathering troops, you secure a cultist disguise and infiltrate their nearby training grounds.\n\nFind out anything you can about the Twilight's Blade and their goals. I will keep this area secure.", objectives = "Find a Twilight's Blade disguise and infiltrate the Twilight's Blade.", progress = "You look lost, fledgling. Isn't there somewhere you should be?", completion = "You hardly seem prepared to serve Xal'atath. We shall fix that." }
WordHunterWoW_QuestEN[90766] = { title = "Xal'atath's Proven Faithful", description = "It takes more than blistering desperation for the apocalypse to be part of the Cult of Twilight.\n\nWe are Xal'atath's Twilight's Blade. Our purpose is greater than it has ever been before. And thus, we must become her strongest allies.\n\nGo and train with my associates in the field. Educate yourself on our rituals and rhetoric. Only then will I allow you to go through the initiation ceremony.", objectives = "Train to become a Twilight's Blade cultist.", completion = "Excellent. You have the bearing of a true acolyte of the Twilight's Blade." }
WordHunterWoW_QuestEN[90767] = { title = "More Doom", description = "Having completed your training, you have earned full membership with the Twilight's Blade.\n\n<Harrowtongue pauses a moment, appearing self-satisfied.>\n\nAs a member of the cult, you will now join your fellow acolytes in an initiation ceremony. They are in the basement of this building receiving instructions from our great leader, Mor'duun.\n\nAllow his words to fill you with zeal for the cause. The end is near!", objectives = "Sabotage the ritual.", progress = "Have you discovered more about the cult's plans?", completion = "I suppose aligning with yet another being hellbent on ending the world is only fitting for the Cult of Twilight." }
WordHunterWoW_QuestEN[90768] = { title = "Cult It Out", description = "Mor'duun and his Twilight's Blade cultists are directly supporting the Harbinger's dark designs for our world.\n\nAnd that is all we need to know. Kill as many as you can, then meet us back at our base of operations.\n\nThe cult and its leaders must be eliminated.", objectives = "Kill Gehl Harrowtongue and 12 Twilight's Blade cultists.", completion = "Their nefarious alliance with Xal'atath is clear. Good work. Now we take them down." }
WordHunterWoW_QuestEN[90769] = { title = "A Blue for You", description = "Why you want such a strange beast? \n\nI save many better items just for you. What about some soap?\n\nBut, I not deny {name} heart's desire.", objectives = "Receive your reward.", completion = "May the spirits protect you mon, and your new blue friend!" }
WordHunterWoW_QuestEN[90770] = { title = "The Grift", description = "Dey say you want the blue beast. Was a great bargain I stumbled upon. Da bazaar full of opportunities. \n\nMany more bargains to find in spots where treasures lie waiting. \n\nYou know where to look?\n\nGo to dis special place and find treasures, I give the blue beast to you.", objectives = "Enter Untethered Space and recover the items Griftah requires.", progress = "Did you find da treasures?", completion = "Good work, mon. Griftah be smiling today." }
WordHunterWoW_QuestEN[90772] = { title = "The Flames Rise Higher", description = "De coal... it's white-hot now. And I feel like there is somethin' inside it?\n\nBrek said dis was de last trial. But Jan'alai is not here.\n\nWhat do we do now?\n\n<Zul'jarra looks at Brek and scowls.>\n\nTalk to Brek and see if he's got anything to say we can understand.", objectives = "Complete the ritual of Jan'alai.", progress = "If I cannot commune with Jan'alai, de path of de hash'ey stops at dis temple.", completion = "We did it, hash'ura.\n\nJan'alai is reborn! And we have her blessin'.\n\n<Zul'jarra closes her eyes and briefly enjoys the feeling of the flame against her face.>" }
WordHunterWoW_QuestEN[90773] = { title = "Meat My Business", description = "Since I am helping you, I'm sure you won't mind returning the favor.\n\nI have a constant need for fresh, untainted meat, which is quite hard to come by. The Oasis is off limits, but the wildlife roaming these sands?\n\nI've got a list of what I need. Bring me those items, and I'll tell you what you need to know.", objectives = "Collect 12 Dustback Flank, 5 Siltwing Tail, and 5 Swoopwing Eggs.", progress = "You've collect all the meat?", completion = "Now as I promised.\n\nI sold the blue slateback to an outsider like yourself. Not some great hero, but more of an awkward sort.\n\nCome back tomorrow. He usually stops by here for a meal. And he doesn't merely smell it, he eats!" }
WordHunterWoW_QuestEN[90776] = { title = "Ancient Curiosity: Combat", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important. The Explorers' League would be interested in this.>", objectives = "Use and equip a Combat Curio to Brann Bronzebeard." }
WordHunterWoW_QuestEN[90777] = { title = "Feeding the Flame", description = "Champion, the Sunwell holds for now, but the Vanguard has begun to deploy the bulk of its forces to Voidstorm.\n\nLady Liadrin has requested your assistance at the Sunwell.", objectives = "" }
WordHunterWoW_QuestEN[90778] = { title = "Ancient Curiosity: Utility", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important. The Explorers' League would be interested in this.>", objectives = "Use and equip a Utility Curio to Brann Bronzebeard." }
WordHunterWoW_QuestEN[90779] = { title = "Cracked Keystone", description = "Fragmentary images of heroic deeds flash though your mind as you touch the stone, but they fade as fast as they arrive.\n\nPerhaps performing a suitably impressive task will stabilize the stone's magic once more?", objectives = "Complete any dungeon on Mythic 2 or higher difficulty." }
WordHunterWoW_QuestEN[90781] = { title = "Sparks of War: K'aresh", description = "There's rumors about conflict rising in K'aresh - go off and find out more!", objectives = "Collect 100 Sparks of War in K'aresh, while in War Mode.", progress = "Go off and finish what you started.", completion = "I'm astounded at your quick return, well done." }
WordHunterWoW_QuestEN[90782] = { title = "The Nethersent", description = "<The draenei first tries to speak to you in his native tongue, adapting after you fail to respond.>\n\nMen of Void take us to here. Come from sky. Fighting, killing. Want to go back. Help brothers and sisters.\n\nShow you.", objectives = "Free the draenei and meet with him at the base of Masters' Perch.", completion = "<The woman seems wary of you, but nonetheless bows at your approach.>\n\nFriend? Hope of us." }
WordHunterWoW_QuestEN[90818] = { title = "Murder Row: Loose Lips", description = "It is not unexpected to sense some fel magic here. There are still warlocks in the city and old fel siphoning chambers. But the evidence I've found so far is more than could be explained by just that. It feels... different. Chaotic.\n\nThis practice has to be widespread, which means someone must be talking about it.\n\nI've been rooting around too long to go unnoticed, but perhaps you could covertly listen in on some idle banter around the city. If you learn anything useful, report back to me.", objectives = "Listen in on 3 conversations near the Royal Exchange.", progress = "People let many things slip when they assume they're unheard.\n\nNever assume you're unheard.", completion = "<Belath's expression sours more than usual.>\n\nFear drives people to desperate measures, but fel magic isn't a weapon to be wielded lightly.\n\nThe power comes at a cost they do not understand--nor are they trained to withstand those dangers." }
WordHunterWoW_QuestEN[90819] = { title = "Murder Row: Acting the Part", description = "Based on what we discovered, I believe the fel is coming from Murder Row. Someone there is breaking down Legion relics and infusing the magic into mana wyrms for covert siphoning--and people are buying it up in droves.\n\nWe need to figure out who that someone is.\n\nTake this wyrm core with you into the Row and look for more of them. The promise of coin should get you in front of the right person.", objectives = "Take the Cracked Wyrm Core, then investigate Murder Row to discover the source of the smuggled fel wyrms.", progress = "The denizens of Murder Row are tight-lipped, but any information we manage to uncover will be invaluable.", completion = "They mentioned someone named Zaen?\n\nHe's a well-known thug in the Row. Smuggling fel through the Silvermoon Harbor sounds exactly like his style. He doesn't want anyone watching him.\n\nGood work pocketing that shipping manifest." }
WordHunterWoW_QuestEN[90821] = { title = "Murder Row: Harbored Secrets", description = "That manifest is stamped by the Silvermoon Harbor. It looks like Zaen has his smugglers working there to push his fel relic shipments through inspections.\n\nIf we cut off their supply line at the harbor, we can halt the fel operation until we track down Zaen and end it for good. No sense going after the middlemen until then.\n\nSubterfuge got us this far, so let's keep at it. Head to the harbor and tell them you're picking up Zaen's shipment. We'll work from there.", objectives = "Talk to the dockmaster at the Silvermoon Harbor to collect Zaen's fel relic shipment.", progress = "Zaen is the mastermind here, or at least he seems to be. We'll need to deal with him to truly end this scheme.\n\nTaking out their fel supply line at the harbor will stop the situation from getting any worse while we find him.", completion = "The \"Illicit Rain?\" Zaen's base of operations, perhaps.\n\nThat receipt mentions Suramar. The fel relics must be getting pilfered from the Broken Isles, then routed into Silvermoon through a trade line no one would suspect.\n\nClever." }
WordHunterWoW_QuestEN[90822] = { title = "Murder Row: One Fel Swoop", description = "We have all the puzzle pieces. Zaen smuggles fel relics from the Broken Isles by stacking the Silvermoon Harbor with his own smugglers. The relics are processed in Murder Row, then fel magic is infused into mana wyrms for sale and siphoning.\n\nSuch a convoluted operation might be impressive, if the goals weren't so reckless. Zaen is preying on people's fear. He doesn't care who he helps or hurts as long as he rakes in the gold.\n\nLet us end it. We'll find the Illicit Rain in Murder Row and clear it out.", objectives = "Dismantle the fel smuggling operation inside Murder Row.", progress = "Something seems to have happened in Murder Row since we left. A crowd is forming.\n\nProceed with caution. I'm with you.", completion = "With no one left to run it, this fel operation should be done with... for now, at least.\n\nIt was a pleasure working with you, <name>." }
WordHunterWoW_QuestEN[90823] = { title = "Akil'zon's Insight", description = "Now that I be catching my breath, I be reminded of why I thought there'd be nothing but silence at the top.\n\nShe be here. Akil'zon be here. But also, she had been gone when we needed her most.\n\nWhat could she be wanting to tell us?", objectives = "" }
WordHunterWoW_QuestEN[90824] = { title = "My Brother's Alive!", description = "En'liahn saved me from the Rift of Aln. He's my older brother. I know it was stupid to go there, but it wasn't my fault!\n\nWe all thought En'liahn was dead, but I saw him earlier at the wetland. When he saw me, he ran away.\n\n<Chua looks sad.>\n\nNo one here believes me and now I can't go. Will you help me find him again?", objectives = "Find En'liahn at the Ahl'ua Wetland.", completion = "Chua sent you? He's not out here again is he?\n\nMind lending me a hand?" }
WordHunterWoW_QuestEN[90826] = { title = "The Healing Waters of Ahl'ua", description = "I'd hoped Chua hadn't seen me. Better he thinks I died. Instead, I'm self-exiling.\n\nI was trapped in the Rift of Aln while saving him. Being in there for so long corrupted my connection to the goddess--if I don't sever it soon, it'll drive me mad, or worse.\n\nThe Shul'ka who saved me has agreed to mentor me through the process. He told me to come here and gather some things for a ritual to sever the connection.\n\nI must collect the nearby healing waters. Will you help me fill this jug?", objectives = "Collect 6 Healing Waters of Ahl'ua.", progress = "I appreciate your help, <name>.", completion = "Thank you, <name>.\n\n\n\nI hope the water is as powerful as my mentor says it is. The strong poison of these creatures suggests I'm going to need it to survive the ritual." }
WordHunterWoW_QuestEN[90827] = { title = "Only the Poisonous Parts", description = "My Shul'ka mentor instructed me to collect the toxic glands from the creatures here. He said they were crucial to the Ritual of Severing in order to break my connection with the goddess.\n\n<En'liahn shakes his head in pain.>\n\nI'm not looking forward to whatever this ritual is, but her disjointed song in my head is getting stronger and making it hard to focus.", objectives = "Collect 8 Phytogenic Poison Parts.", progress = "Be careful handling that poison. These creatures are some of the deadliest in all of Harandar.", completion = "This should be more than enough.\n\nI'll be careful with them. I wouldn't want to poison myself prematurely." }
WordHunterWoW_QuestEN[90829] = { title = "Meeting My Mentor", description = "I'm in your debt, {name}. I didn't think I'd get any help. My mentor only provides guidance. He says that is the way of the Shul'ka.\n\nThanks to you, I have everything I need for the ritual. Will you continue on with me? I'm heading for the cliffside overlooking the Rift of Aln to the northeast.", objectives = "Rejoin En'liahn on the cliffside above the Rift of Aln.", completion = "I'm glad you came. Amarakk is my Shul'ka mentor. He says your help is not strictly forbidden.\n\nI can use all I can get." }
WordHunterWoW_QuestEN[90830] = { title = "The Path Will Reveal Itself", description = "The next step is to locate the ritual site. It's different for each potential Shul'ka.\n\nAmarakk says that I must open myself to the power of the rift--that some part of myself tied to this place will guide the way.\n\nAll I can tell you is it hurts.\n\nAre you still with me?", objectives = "Travel with En'liahn to discover the ritual site within the Rift of Aln.", progress = "I see you made it.", completion = "Now it is time to see if young En'liahn will survive the ritual or be consumed by the rift." }
WordHunterWoW_QuestEN[90831] = { title = "Doing Is Becoming", description = "If En'liahn is to succeed as a Shul'ka, he must learn to disrupt the manifestations in the rift. Sometimes that means closing small tears as they open. Most of the time, we simply slay the manifestations where we find them so they do not become so numerous as to threaten the rest of Harandar.\n\nIt is a never-ending responsibility each of us bears. It is why we are Shul'ka.\n\nThis, of course, assumes that he survives the ritual, or even survives to find the ritual site.", objectives = "Disrupt the manifestations within the Rift of Aln.", progress = "I see you, <name>.", completion = "You have done well for one who is not Shul'ka.\n\nUnfortunately, the Rift of Aln never rests. I think you'll be back." }
WordHunterWoW_QuestEN[90832] = { title = "As Her Voice Goes Silent", description = "En'liahn is about to drink the mixture of the poison and healing waters to begin the ritual. He will be unconscious and fighting for his life.\n\nThe manifestations of the rift can sense this, and they are gathering.\n\n{name}, you must place the wards and use their power to defend him while he severs his final connection to the goddess before her song drives him to madness.", objectives = "Protect En'liahn while he endures the Ritual of Severing.", progress = "Whatever happens next, you've proven you can be trusted.", completion = "It is done. There is but one thing left to do once En'liahn has recovered.\n\nBut first, we should leave the rift immediately. This is no place to linger." }
WordHunterWoW_QuestEN[90833] = { title = "The Final Rite", description = "Foolish. En'liahn is still weak from the ritual and not prepared.\n\nHe has run off to confront Morta'ka the Sundered Echo. This is the final rite of all who would become Shul'ka, but it is usually only attempted after years of preparation.\n\nEn'liahn will not survive, and in dying will only make Morta'ka more powerful. Will you save him, {name}?", objectives = "Help En'liahn to slay the manifestation known as Morta'ka the Sundered Echo inside the Shadow Cleft.", completion = "I know it was stupid and I should be dead. I feel confused about surviving the ritual but no longer being able to hear the goddess. I'm sorry, <name>. I shouldn't have done that.\n\nAt least it's over. Now to apologize to Amarakk. He's probably done with me." }
WordHunterWoW_QuestEN[90834] = { title = "From This Point Forward", description = "I don't know how to feel about losing my connection with Aln'hara. There's no more pain... I'm not going mad, but there's a hole inside. Does that make sense?\n\nWill you rejoin us back up on the cliff?", objectives = "Return to En'liahn and Amarakk on the cliff overlooking the Rift of Aln.", completion = "I owe you a great debt, <name>. At least now I can protect my people as I learn the ways of the Shul'ka.\n\nMy only regret is being separated from Chua." }
WordHunterWoW_QuestEN[90835] = { title = "Murder Row: Rumors Abound", description = "I would advise exploring the city with caution. Not all is what it seems in Silvermoon.\n\nThe Illidari are performing an investigation which need not be spoken of openly. But you appear formidable... Perhaps you can aid us.\n\nMy commander, Belath Dawnblade, is heading the investigation. The last I heard, he was surveying the upper terraces of the Bazaar.\n\nSeek him out, if you would make use of yourself.", objectives = "Find Belath Dawnblade in the terraces above the Bazaar.", completion = "Your arrival is timely.\n\nI will be brief: I believe there is a widespread resurgence of fel magic use happening in Silvermoon, and it must be stopped." }
WordHunterWoW_QuestEN[90837] = { title = "Murder Row: Traces of Fel", description = "I have been sensing powerful fel magic throughout Silvermoon, but this is the first origin point I could locate. The rest were too faint, or perhaps deliberately hidden. Fortunately, this means we now have a specific area to comb through more closely.\n\nWe need to gather more evidence. Go around this area and see if you can find more hidden sources of fel. I will grant you a temporary portion of my sight so that even the slightest hint of fel magic will be obvious to you.", objectives = "Discover 5 sources of fel magic near the Royal Exchange.", progress = "Were you able to locate anything?", completion = "Hm... Legion scraps, fel dust, and evidence that both might be getting moved around the city covertly. A sanctioned fel trade would not be resorting to such measures.\n\nThen there are the mana wyrm cores we both found. Siphoned dry, but fel still clings to them." }
WordHunterWoW_QuestEN[90838] = { title = "Oaths and Heirlooms", description = "You, stranger... do you know of the Shadowguard that left K'aresh in ruins?\n\nMy sister was lost in the conflict, her heart forcibly turned to the Void, but I swore oaths to my family... to cherish them no matter their transgressions.\n\nMy sister, Veraan, is surely lost, but if I were to recover her necklace, at least then my oaths would be upheld in spirit.\n\nI am a simple tinkerer. I've tuned this device to track the Shadowguard, but I cannot face them alone.\n\nWould you help me?", objectives = "Meet Kifaan outside of the Ethereum Overcroft.", completion = "Keep yourself out of sight. I would rather not risk a bleak fate." }
WordHunterWoW_QuestEN[90840] = { title = "What's Your Specialty?", description = "The Dragon Isles is a dangerous and uncharted place. We'll need to get you prepared.\n\nYou're strong enough now that you should choose a combat specialization.\n\nThis will unlock a new array of abilities for you to face the dangers within the Dragon Isles.\n\nGo ahead and choose your combat specialization.", objectives = "Choose your combat specialization.", progress = "Having trouble? You can find your combat specialization beside your spellbook.", completion = "Excellent choice! I'm looking forward to what you do next.\n\nTake this riding mount. It'll help you get around here faster." }
WordHunterWoW_QuestEN[90842] = { title = "Home Is Where the Hearth Is", description = "Before you head off, you'll want to get yourself a Hearthstone. \n\nThis little stone will return you to the inn where you last bound it to.\n\nIt's not much of an \"inn\", but the explorers have a tent set up. \n\nTest out that new mount of yours and ride over to Sil'nori Crestshade. He'll get you sorted out with a Hearthstone.", objectives = "Ride your mount, then speak with Sil'nori Crestshade to get a Hearthstone bound to the Wild Coast.", progress = "Sil'nori Crestshade nearby can get you set up with a Hearthstone.", completion = "If you ever find yourself lost, use your Hearthstone to get yourself back to where you should be." }
WordHunterWoW_QuestEN[90843] = { title = "Aiding the Dragon Isles", description = "It's time for us to part ways. I have pressing business further within the Dragon Isles in a place called the Azure Span.\n\nNaleidea Rivergleam of the Dragonscale Expedition could use your help.\n\nSafe travels, {name}. I look forward to our next meeting!", objectives = "Meet  Naleidea Rivergleam to begin your adventure in the Dragon Isles.", completion = "How are you? We could use more hands to help us explore the Dragon Isles!" }
WordHunterWoW_QuestEN[90844] = { title = "Fits of Lucidity", description = "While I've been lurking, I've been listening.\n\nThese Shadowguard appear to have a minor rebellion on their hands. Some of the ethereals are acting erratically. They're being rounded up and questioned.\n\nWhat's going on here?\n\nDispatch some of these Shadowguard and intercept their intel. I'll decode anything you bring back to me.", objectives = "Slay ethereals in the Ethereum Overcroft and collect 8 Interrogated Data.", progress = "I thought the Void coursing through these ethereals was all-consuming.\n\nAnd yet, there seem to be some able to resist its infinite darkness.", completion = "Something has sparked a rebellious fire in some of the Shadowguard.\n\nLet us see what more we can find." }
WordHunterWoW_QuestEN[90845] = { title = "Distant Memories", description = "I swore an oath to honor my family... difficult when my sister was converted to the Shadowguard. She may not be here, but tracking the Shadowguard has led me to this place. \n\nI'm looking for a necklace that belonged to my sister Veraan. It's odd... I've noticed many K'areshi heirlooms discarded around here. It seems the Shadowguard wish to destroy any reminders of our home world.\n\nIf you bring some of these trinkets and baubles to me, we can see if there are any I recognize.", objectives = "Collect 8 K'areshi Keepsakes found at the Ethereum Overcroft.", progress = "These keepsakes are some of the last remnants of our home world.\n\nThe memories they contain are powerful. The Shadowguard is right to fear them.", completion = "I do recognize some of these items! They belonged to close friends and family.\n\nIf my sister's necklace is to be found, it will be here." }
WordHunterWoW_QuestEN[90847] = { title = "Truth From Power", description = "Thanks to your intel, we have learned that the rebels are being interrogated by Questioner Xen'daan.\n\nIt is said that after being questioned, the rebel ethereals are being taken somewhere to be \"dealt with.\"\n\nThe head questioner is sure to know more. If we can find where they've taken the rebels, there may still be hope for them.", objectives = "Slay Questioner Xen'daan at the Ethereum Overcroft to discover the rebels' whereabouts.", progress = "At the risk of getting my hopes up... do you think Veraan could be among them?\n\nCould I face her now? After the atrocities she's committed in the name of the Void?", completion = "<name>! This necklace belongs to Veraan! Veraan IS Sombersong!" }
WordHunterWoW_QuestEN[90848] = { title = "She Started the Fire", description = "Veraan is sure to be amongst the rebels taken to Shadowguard Point.\n\nHer fiery spirit fills me with great pride!\n\nI came here expecting to say a farewell of sorts. I did not come here expecting to find my sister.\n\nPerhaps it's not too late, {name}!", objectives = "Meet Kifaan at Shadowguard Point.", completion = "Veraan's essence may have been twisted by the Shadowguard, but the rebellion gives me hope.\n\nCan the dissidents be snatched from the Void's grip entirely?" }
WordHunterWoW_QuestEN[90849] = { title = "Light Show", description = "", objectives = "" }
WordHunterWoW_QuestEN[90851] = { title = "Eating Their Own", description = "The Shadowguard seem to have no qualms caging and torturing their own kind.\n\nThe last thing I want is more violence amongst the people of K'aresh, but better them than us.\n\nDisrupt their operation by subduing some of the Shadowguard.", objectives = "Slay 12 Shadowguard Engineers and Infusers at Shadowguard Point.", completion = "Violence is rarely an occasion for celebration, but I am glad we have at least slowed the deeds occurring here." }
WordHunterWoW_QuestEN[90852] = { title = "Techno-Magnetic Pulse", description = "The betrayers are being held in stasis chambers.\n\nI've seen these cages before. Their design is efficient but fragile. They will fail with the slightest energy variation.\n\nFind crackling energy vessels strewn about and heave them at the stasis chambers. With true aim, you will disable them and free the betrayers.", objectives = "Throw Crackling Energy Vessels at arcane prisons to free the Caged Betrayers.", completion = "Thank you, <name>. You helped me see my sister again. For that, I can never repay you.\n\nVeraan is changed. Angry. Tormented by despair. Let us tread delicately." }
WordHunterWoW_QuestEN[90858] = { title = "Repress the Oppressors", description = "We were brought here to face the wrath of Soulbinder D'zaar. She commands the Shadowguard here. She leverages the power of the Voidstorm to convert souls to energy that she consumes.\n\nShe and her loyalists are traitors to our kind!\n\n<Veraan grimaces in pain as the Void courses through her.>\n\nThey must be stopped... their devices dismantled... their will ended...\n\n{name}... destroy them all!", objectives = "Disrupt the operation by slaying ethereals, destroying Fragile Energy Piping, and detonating Volatile Energy Reservoirs.", progress = "<Veraan trembles with rage.>\n\nThese kinslayers were willing to sacrifice their own. And in service of what? Xal'atath's will?", completion = "I can feel Kifaan's hesitation every time our gaze meets. He is afraid of me..." }
WordHunterWoW_QuestEN[90860] = { title = "Shedding the Yoke", description = "Rebels like us are brought to Soulbinder D'zaar. She suffers no betrayers.\n\nOur fate was to be sacrificed--our souls converted to energy. D'zaar works the conduit with arcane mastery to absorb these souls!\n\nWe don't have much time. I can feel the Void pressing from within. If we are to leave this life violently, D'zaar and her conduit are coming with us!", objectives = "Slay Soulbinder D'zaar at Shadowguard Point.", progress = "The pressure is building... it's almost time...\n\nAnd besides, do I even deserve to live? What will they say of me, a member of the Shadowguard, when all is said and done?\n\nDo you think Kifaan could ever forgive me?", completion = "The Shadowguard got what they deserved.\n\nBut I am not blameless, <name>. Even now, shadows linger inside me.\n\nFor the safety of everyone, I should go." }
WordHunterWoW_QuestEN[90861] = { title = "Those Left Behind", description = "In the wake of Xal'atath's destruction, what remains of our forces are gathering at the Darkwell to determine what we can do about the remnants of the Void.\n\nWe cannot abide the presence of so much dark energy. Some of our greatest casters and most knowledgeable scholars believe they might have a solution, but we could use your aid.\n\nPlease, join Arator at the Darkwell at your earliest convenience.", objectives = "" }
WordHunterWoW_QuestEN[90862] = { title = "In Times of Need", description = "The last of the other elven leaders have returned with powers from their homeland that will help us in cleansing the Darkwell. \n\nWhile the Voidstorm no longer barrages the Darkwell, it still needs healing. \n\nPlease meet with the other leaders and let them know we are ready for them.", objectives = "" }
WordHunterWoW_QuestEN[90866] = { title = "Universal Language", description = "To go home, water of life. Need.\n\n<Tul'amar attempts to discern if you understand what she's talking about with a look. After a pause, she opts to stab her own fingertip with the end of her staff and then displays a bead of her blood to you.>\n\nThis. Of here. Is of fight. Of fight is Void. Void is power. With power, go home.\n\n<She shows her fangs with an exaggerated snarl before pantomiming a claw swipe.>\n\nWater of life. Of beast. Much. Yes?", objectives = "Collect blood from the beasts north of the Night Trench.", progress = "You. Not die? Good.", completion = "Blood! Is blood. Yes?\n\n<She looks to one of her kin, who assures her that she's got the right word this time.>\n\nGood. Now see." }
WordHunterWoW_QuestEN[90867] = { title = "From Darkness, Light", description = "We will not let the Sunwell be corrupted again. This Darkwell must change, but it must change to something that we are no longer bound to with such dependency. We do not need this well to be the bait for so many other world-corrupting forces.\n\nNo, today we heal the Darkwell, and make it something new. Let me know when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[90869] = { title = "It's All in the Image", description = "So, the higher-ups in the marketing department say you need a good partner to soften your aesthetic of... you know, \"murder everyone around me for gold.\"\n\nWe've got two focus group approved goblins over there ready to go, so go take your pick. Sassy will handle the paperwork.\n\nOh, don't give me that look. You only gotta forever-love each other in front of the public. Once the cameras are off, no one cares. It'll be great for your reputation!", objectives = "Speak to Sassy Hardwrench to select a \"marketing partner.\"", progress = "C'mon, this ain't rocket surgery. Pick whoever you wanna pose on some magazine covers with.", completion = "There we go! Nice and artificial, just like all the best marketing should be.\n\nAnd I just finished the paperwork for your other big image upgrade. I think you're really going like this!" }
WordHunterWoW_QuestEN[90870] = { title = "Gathering the Grub", description = "Ah, ye're here! Brewfest is here and we've got a small problem. We can't have a proper feast without the food, but some pesky hozen thought it'd be fun to steal our bags of grub. I'm sure they're just lookin' to fill their own bellies, but it's messin' up our plans!\n\nSo here's what I need ye to do: hunt down those hozen and take back the bags they've snatched. There's a good chance ye'll find a few bags just sittin' on the ground too. When ye return, just add the recovered bags to that wagon back there.", objectives = "Collect Bags of Brewfest Ingredients and deposit them at the wagon.", progress = "The feast won't come together without those ingredients!", completion = "Ah, ye've done it! The cooks will be pleased." }
WordHunterWoW_QuestEN[90871] = { title = "The Silversun Compact", description = "Champion. \n\nAfter much discussion, negotiation, and even some screaming and three duels, the Sunreavers and the Silver Covenant have decided on a course of action to define both of our futures.\n\nGiven your aid in getting us to this day, we would like you here to act as a witness as we formalize and sign our peace accords. Will you do us the honor of igniting the Flames of Remembrance?", objectives = "" }
WordHunterWoW_QuestEN[90872] = { title = "Drenched In It", description = "<Tul'amar looks away from the blood-soaked and mortified Juras, and toward the portal as it flickers to life. She reads it with her powers of the arcane.>\n\nGood. Blood is vio... violent? Violent is power. Need more. Now, brothers and sisters.\n\n<She gestures to the blood in your possession, and then to her people. Many of them return wary looks your way.>\n\nYou can. I say. \n\nThen, go out. See of me.", objectives = "Mark 8 Offworld Refugees with Predator Blood to empower the portal in Exiles' Hovel.", progress = "Done?", completion = "Good. Now, more. Brothers and sisters, help.\n\nAnd men of Void, kill." }
WordHunterWoW_QuestEN[90873] = { title = "These Violent Delights", description = "Brothers and sisters. Here. Help.\n\n<Tul'amar connects her thumb and index finger on both hands to make a chain. Then, she breaks the link with a sharp gesture.>\n\nHow? Show.\n\n<She then produces a glimmering relic and holds it over her gauntlet. She spends a portion of her arcane energy into it. Its newly activated magic forces the straps holding her glove in place loose.>\n\nUse.", objectives = "Use the Relic of Liberation to free 10 Master's Prospects and 3 Unwilling Summons.", completion = "<Tul'amar tilts her head at the freed draenei hiding behind her.>\n\nI see. Good. You good." }
WordHunterWoW_QuestEN[90874] = { title = "Their Violent Ends", description = "Go home. How?\n\n<She offers a dramatic flourish with her fingertips, producing some arcane sparks. Then, she makes an X with her index fingers.>\n\nOf me? No. Of they.\n\n<Tul'amar gestures to a group of voidwalkers up ahead. She then draws her thumb across her neck.>\n\nKill. And.\n\n<She reaches into a pouch on her hip and retrieves a cracked stone of domanaar make. It looks like a spell reagent of some kind.>\n\nAs this. Need.", objectives = "Collect 8 Abductor's Marks from the voidwalkers of Masters' Perch.", progress = "<Tul'amar holds still, even as you approach.>", completion = "<She counts out the portal runes in your possession and nods in approval.>\n\nYes. Good." }
WordHunterWoW_QuestEN[90875] = { title = "Across Worlds", description = "Man of Void. Have key. Need. Key to home.\n\n<Tul'amar gestures down the way to the northwest. She grimaces back at her injured kin.>\n\nGo back, we. Wait. Hope. For you.", objectives = "Kill Snaerius and recover his Lodestar of the Great Dark.", progress = "<Tul'amar smiles sadly at her people.>", completion = "Stay. I must. Men of Void, cannot find brothers and sisters. Finish, must. Only I.\n\nYou, good. Friend. But. Trust, can't. Trust, only when brothers and sisters safe.\n\n<She then holds her staff forward, offering it to Juras. Though he seems reluctant to take it, Tul'amar does not waver.>" }
WordHunterWoW_QuestEN[90876] = { title = "Reluctant Hand", description = "Champion, I felt it was important to have you here for this moment so that neither I nor my wayward former peer get off topic with his many failings.\n\nI also want a witness in case he turns to evil. \n\nWould you be so kind as to unpack a few items so that I do not have to touch them?", objectives = "" }
WordHunterWoW_QuestEN[90879] = { title = "Brewmaster's Kitchen", description = "Now that ye've gathered the materials, we can get to cookin'! We'll need plenty o' food for the whole crowd.\n\nWe've got a short but sweet menu: Barley Soup, Pretzels, and of course a good ol' brew!\n\nAre ye ready to learn the ropes?", objectives = "Follow the steps to cook Brewfest food and a delicious Brew.", progress = "Get cookin'!", completion = "Ah, I can smell the pretzels from here. Ye've cooked up a spread that'll keep even the pickiest dwarves satisfied!" }
WordHunterWoW_QuestEN[90880] = { title = "Serving with Style", description = "Ye've done well in the kitchen, now it's time to learn how to serve! Brewfest isn't just about food--it's about makin' sure everyone has a good time.\n\nYe'll be takin' orders, deliverin' dishes, and pourin' drinks with a smile.\n\nGet out there and show 'em how it's done. Brewfest won't run without good service!", objectives = "Take the customer's order and serve the food to them.", progress = "Remember to serve with a smile!", completion = "I'd say ye've earned yerself a nice break and a brew after all of yer hard work. But don't get too relaxed! There's still plenty to do to keep Brewfest runnin'!" }
WordHunterWoW_QuestEN[90882] = { title = "Gnoll Way", description = "Handle those gnolls while we figure out our next move.", objectives = "Slay 10 gnolls within Hammerfall.", progress = "Handle those gnolls while we figure out our next move.", completion = "Excellent job. However, we cannot rest.\n\nWe have word of more chaos in the highlands." }
WordHunterWoW_QuestEN[90883] = { title = "To Go'shek Farm", description = "Find Farmer Bruvk outside of Go'Shek Farm.", objectives = "Travel to Go'shek Farm", progress = "Find Farmer Bruvk outside of Go'Shek Farm.", completion = "I never thought I'd get this much help! Please, you have to stop them!" }
WordHunterWoW_QuestEN[90885] = { title = "My Beautiful Pumpkins", description = "The kobolds and ogres appeared out of nowhere and kicked us out of the farm!\n\nI thought this was some Alliance plot until you all showed up. Maybe the Alliance is here to help us after all.\n\nYou have to help me get my precious pumpkins back. I've spent the entire harvest cultivating them!\n\nYou lead the way. I'll grab the pumpkins when you find them.", objectives = "Recover 4 Prized Pumpkins.", progress = "Return to Thrall with Farmer Bruvk and his pumpkins", completion = "That's... quite a lot of pumpkins.\n\nI think our farmer friend should take them back to Hammerfall. Horde reinforcements should be there by now." }
WordHunterWoW_QuestEN[90886] = { title = "Best Laid Plans of Kobolds and Ogres", description = "The kobolds and ogres here seem to be carrying some sort of plan for their attack.\n\nI don't think they're particularly well written, so I'll need several of them to figure out what the ogres are planning.", objectives = "Collect 7 Poorly Written Plans.", progress = "Did you recover the plans? They should be on most of the foes within the farm.", completion = "Just as I thought.\n\nI can barely read any of this." }
WordHunterWoW_QuestEN[90887] = { title = "Farmer's Nemesis", description = "Farmer Bruvk mentioned an ogre named Runk was leading the group here.\n\nThese creatures won't leave this place as long as that ogre is commanding them.", objectives = "Slay Runk.", progress = "We'll stay here and guard the remaining farmers while you handle Runk.", completion = "This should help disperse the creatures. Without a leader they'll flee when Alliance and Horde reinforcements show up." }
WordHunterWoW_QuestEN[90888] = { title = "Saving Stromgarde Keep", description = "The plans you found indicate the ogres are trying to get food to supply a massive attack on Stromgarde Keep!\n\nOr they're trying to use the crops to keep guarding an object named a storm. The translation was loose. \n\nIt's safe to assume our problem is the former. Let's go!", objectives = "Travel to Stromgarde Keep.", completion = "This looks bad, but it's nothing we can't handle." }
WordHunterWoW_QuestEN[90889] = { title = "Tale of the Echoes of Sai'alyo", description = "", objectives = "" }
WordHunterWoW_QuestEN[90890] = { title = "[PH] Go Home", description = "", objectives = "" }
WordHunterWoW_QuestEN[90892] = { title = "Clearing the Skies: A Fel of a Time", description = "<The skies are full of residual time energy and demons pouring in from other timelines.\n\nI should help Eternus by cleaning up the skies. The extra bronze energy would be nice too.>", objectives = "Collect bronze by flying through 10 Lost Legion demons and 25 Motes of Bronze.", completion = "<The skies are a little clearer now. The infinites might be interested in trading with this extra bronze I've collected.>" }
WordHunterWoW_QuestEN[90893] = { title = "Repelling the Siege", description = "We must do everything possible to stop this siege on Stromgarde. \n\nMake your way into the battle and weaken the ogre forces.\n\nStromgarde should be able to rally if they can gain the upper hand.", objectives = "Repel the Ogre Siege outside of Stromgarde keep.", completion = "The siege is at an end. We've got their leader cornered." }
WordHunterWoW_QuestEN[90895] = { title = "Catapult Bombardment", description = "These catapults are relentless. They must be destroyed.\n\nPlace these rune stones at their base. It'll unleash arcane magic to turn the catapults to dust.\n\nI'll take out a few as well as I make my way across the battlefield.", objectives = "Apply Jaina's Runes to 4 Catapults.", completion = "With the catapults gone the soldiers of Stromgarde should be able to gain the upperhand." }
WordHunterWoW_QuestEN[90896] = { title = "One Last Ogre", description = "The head of the siege is still cowering within the former Horde encampment. \n\nHe managed to hide from Jaina's spell behind several of his cohorts.\n\nYou can have the honors to confront of him. Jaina and I will stay here to ensure any remnants of the siege do not return.\n\nEnd this.", objectives = "Slay Ro'grok", progress = "Defeat Ro'grok and end this siege.", completion = "The siege is over. Arathi Highlands will hopefully return to a somewhat peaceful state now." }
WordHunterWoW_QuestEN[90897] = { title = "Back to Stromgarde", description = "I think we can count ourselves lucky there was no bigger threat here beyond a group of overambitious ogres. \n\nThe same can't be said of other threats that are looming throughout Azeroth.\n\nCome. Let's return to Stromgarde to discuss matters further.", objectives = "Meet Jaina Proudmoore within Stromgarde Keep.", completion = "It's good to see the people here in high spirits." }
WordHunterWoW_QuestEN[90898] = { title = "Back to Hammerfall", description = "We're not always so lucky that a plan such as this is ended so swiftly and without a surprise portal or two.\n\nThat being said, more dangers lurk throughout Azeroth. I know you can be of help to some.\n\nLet us return to Hammerfall to see how they're recovering.", objectives = "Return to Hammerfall.", completion = "Hammerfall will recover in time and become stronger than it was before." }
WordHunterWoW_QuestEN[90901] = { title = "As A Matter of Artifact", description = "There's more to artifacts than meets the eye, {name}.\n\nSimply using an artifact allows its legend to grow, and as that legend grows, so too does its power.\n\nIn order to unlock the full potential of that power, however, you'll need to focus infinite power into the artifact's traits. As more traits are empowered the artifact's true potential will be unlocked, and its legend will be undeniable.\n\nLet's get started.", objectives = "Unlock artifacts traits using Infinite Power gained from looting Epoch Mementos from any enemy.", progress = "Unlocking the full potential of your artifact will be key to understanding their impact on this timeline.", completion = "As you gather infinite power do not forget to focus it into your artifact.\n\nThe more power you invest, the swifter you will gather more infinite power and grow your artifact's legend--and your own." }
WordHunterWoW_QuestEN[90907] = { title = "The First to Know", description = "Notes speaking of fear, of uncertainty--of some mysterious truth? This is not good, {name}. By all accounts, it sounds as if a cult has managed to infiltrate Tranquillien. \n\nIf that journal entry was true, Kasiea was attempting to leave it. \n\nWe must tell Antenorian. He'll want to secure the town and make sure his people are safe.", objectives = "Inform Lord Antenorian, governor of Tranquillien, of your investigation results.", progress = "I hope our fair town is treating you well. If you have any concerns at all, bring them to me.", completion = "It is heartening that you trust me with these serious concerns." }
WordHunterWoW_QuestEN[90910] = { title = "Overwhelming Darkness", description = "A dreadful presence calls from the den just to the southeast of here. Many of the dazed ren'dorei you see in camp were overwhelmed by its raw power on a scouting mission.\n\nLet us go together and see if whatever dwells within can be put to use. We cannot afford to spurn power in the fight against Xal'atath.\n\nBefore that: we have little need of Kalgorg. The Voidstorm has made my voidwalker unruly and disobedient. Assist me in sacrificing it. We will need all of the Void energy we can muster.", objectives = "Sacrifice Kalgorg and then meet Lucia Nightbreaker in the Den of Predaxes.", progress = "Disobedient little...", completion = "Kalgorg descended here, but I won't confront it unprepared.\n\nThat disobedient little monster. It thinks it can simply walk away after two decades?" }
WordHunterWoW_QuestEN[90911] = { title = "Your Next Adventure", description = "", objectives = "Choose your next adventure." }
WordHunterWoW_QuestEN[90914] = { title = "A Born Killer", description = "Ah, {name}. I have so enjoyed our time together. I hunger for more. \n\nI wish you knew more of me than my predilection for the taste of mortal suffering. One of my greatest joys is in crafting Void power into various objects and structures. It is my passion--my art.\n\nHere, I would like to show you. First, we will need power. You already know how to get it, of course: kill, kill, kill.", objectives = "Collect 15 Void Essence from monsters around Voidstorm.", progress = "What an odd feeling. I feel almost... drawn to you. It must be your mesmerizing presence.", completion = "My, what delightfully gruesome success. \n\nI am interested to work together with you. You should know more of our people, and see more of my abilities." }
WordHunterWoW_QuestEN[90915] = { title = "Artifice of Aggression", description = "While we domanaar are best known for leading armies and savoring battles, there is more to us. \n\nMany, like myself, enjoy using our mastery over the Void to shape it into the buildings and objects you see around you. \n\nHow do you think Xal'atath learned to create that great tower of hers? She's a quick study. \n\nCome now, and I will show you my work.", objectives = "Craft a blade with Decimus.", progress = "How excellent to spend some time together. You mortals are so very interesting... you most of all.", completion = "Consider this blade my gift to you. We shall work together to make you into a true weapon of destruction." }
WordHunterWoW_QuestEN[90916] = { title = "Seek to Destroy", description = "It's no easy thing, intertwining Light and Void together. The result is unstable, so we must continue to temper it. \n\nWe shall quench this blade in the blood of our enemies. \n\nSome domanaar attempt to reclaim and re-power Nexus-Point Xenas. That won't be good for your people. I'll assume you want to stop it. \n\nWhat is it you mortals say? Two birds, one stone?", objectives = "Meet Decimus at Nexus-Point Xenas.", completion = "These Nexus-Points used to be fonts of power for us domanaar to enjoy, long before Xal'atath overthrew us. \n\nSomeday, they shall be so again." }
WordHunterWoW_QuestEN[90917] = { title = "Harvester of Savagery", description = "The blade hungers! The blood of our enemies will help stabilize and hone our nascent weapon. \n\nYou'll need to drench the blade inside some corpses. So, you'll need to make corpses. \n\n<Decimus's smile grows broader.> \n\nYou're good at that, right?", objectives = "Use the Nascent Blade on corpses in Nexus-Point Xenas.", progress = "The monsters native to this land are fierce and violent. Their bloodlust drew the Void here, so naturally... we feel quite at home here.", completion = "Very good. \n\nI understand you mortals fret over things like ecological balance and culling of species. \n\nFear not: the monsters here are as endless as they are brutal." }
WordHunterWoW_QuestEN[90918] = { title = "The Unforgiven", description = "Since even before our little misadventure, Nexus-Point Xenas has always been the weakest link. The beasts here are stubborn and powerful, always pushing deeper and deeper in. \n\nSome domanaar seek to reclaim the Nexus-Point. They are known to me: weaklings, fighting for scraps. Let's ensure they fail.", objectives = "Slay Noxian, Averus, and Tenebre around Nexus-Point Xenas.", completion = "Ah, how quaint, to catch up with old enemies. \n\nWe domanaar once had intricate structures of power. Each domanaar fights for their own sake alone, but it is often advantageous to align oneself with others. Temporarily, of course. \n\nThe most powerful among us were the High Lords. When Xal'atath arrived... she made an example of them all. The spectacle was so moving, it drew not only fear but something closer to loyalty from us domanaar. \n\nSome, though not all." }
WordHunterWoW_QuestEN[90919] = { title = "The Fiend That Failed", description = "The blade squirms. It is ready for its next transformation.\n\nThere is only the leader, Vortensiun, left. \n\nHe is known to me. Once, we formed a pact together to defeat a rival. When the time came for him to betray me, he did so clumsily. \n\nI let him live, so I could savor the taste of his regret. \n\nI wonder how well that pain has marinated by now? Let's find out. When the blade is tempered in his essence, it shall grow new power.", objectives = "Slay Vortensiun in Nexus-Point Xenas.", completion = "Pay no mind to Vortensiun's comment about food. \n\nWe are becoming good friends, are we not?" }
WordHunterWoW_QuestEN[90920] = { title = "Warmth for the Soul", description = "Enjoying the view? \n\nThe blade is stronger now, but it is not yet complete. A weapon worthy of you deserves nothing less than perfection. \n\nBut let us relax for a moment. I understand you mortals enjoy a... casual exchange of conversation to get to know each other better.\n\nI am familiar with the concept, but am curious to see it in action. Indulge me?", objectives = "Enjoy a pleasant conversation with Decimus.", completion = "Fascinating, how freely you give up delicate information about yourself.\n\nI choose to believe you would not lie to me, of course. We are friends now, you and I. Such a mortal concept intrigues me." }
WordHunterWoW_QuestEN[90922] = { title = "The Fallen Wake", description = "<The shade flickers. You can barely make out its whisper.>\n\nYou... left me... to die...\n\n<Its arm reaches toward you, then dissipates. Somehow, the presence is a familiar one. You feel that you know this spirit. \n\nYou see more flickers in the distance. What are these shades?>", objectives = "Dispel spirits in the Gnawing Reach.", progress = "Such a strange and terrible place. Fear not--if you wish to converse more to settle your nerves... I am here for you.", completion = "I'm terribly sorry you had to go through that. The words of these spirits have upset you, correct?\n\n<Decimus peers at you.>" }
WordHunterWoW_QuestEN[90923] = { title = "Shepherd of Fear", description = "Our journey continues... one final battlefield. There are vicious beasts aplenty here. Their Void shall fuel the blade even more.\n\nAnd the blade's newfound power shall draw their Void into itself by mere proximity!\n\nThough, this place is different. You may find things you don't expect.\n\nKeep an eye out.", objectives = "Slay monsters and gather Void Essence in the Gnawing Reach.", progress = "Don't get distracted, now. This will all be worth it when you have a mighty weapon to hold.", completion = "At long last..." }
WordHunterWoW_QuestEN[90924] = { title = "The Wicked End", description = "The time has come. The final step. \n\n<Decimus pauses, savoring something.>\n\nLet us create the greatest weapon your kind has ever seen.", objectives = "Complete the forging of the blade.", completion = "The blade, as promised. See? I never meant to keep it for myself. I will even shape it into whichever form suits you best.\n\nThe taste of your suffering was all I desired." }
WordHunterWoW_QuestEN[90938] = { title = "A Skip Through the Void", description = "Fleshling, do you know about Untethered Space? I am sure you know someone who has encountered it. \n \nPreviously we assumed that only beings of energy such as those from K'aresh could Phase Dive. Since the Harbinger's return, she has created a means for solid creatures to become energy using Reshii Wraps.\n \nMy name is Hashim, and I have some Reshii Wraps in my possession. We are in desperate need of adventurers powerful enough to brave the lucrative depths of Untethered Space.", objectives = "Meet Hashim at Overlook Zo'Shuul.", completion = "I can provide you with everything you need to explore Untethered Space." }
WordHunterWoW_QuestEN[90943] = { title = "Stormarion Assault", description = "", objectives = "" }
WordHunterWoW_QuestEN[90957] = { title = "Initiation Day", description = "{name}, today is when you find your proper place among the haranir.\n\nRoot Tender Dalnir will guide you. His path is one of tradition and humility, so don't expect excitement. By the end of the day, you will make your mark in the Den of Remembrance. The story you begin now will build on those that came before, like the roots themselves, growing the foundations of Harandar.\n\nDalnir was clearing invasive drifters from the roots. Before you go to him, aid Dalnir by removing some of the pests yourself.", objectives = "Elder Hagar is asking you to kill 6 Invasive drifters from around the roots of Teldrassil, and then meet with Root Tender Dalnir.", completion = "The time has come to take your place among our people, and give up childish adventures. Follow my guidance and Aln'hara bless this day.\n\nRemember, our traditions show us the way." }
WordHunterWoW_QuestEN[90958] = { title = "Roots Above All", description = "Some say the great trees grow, and Harandar will remain even if we do not tend them. Our traditions say, it does not matter. We remain here to protect, tend and serve. We do this with dedication and humility.\n\nKeeping the environment around the roots clean and free of pests reflects upon this duty. Return to me once you are done. You will represent our ways well, {name}.", objectives = "Root Tender Dalnir wants you to pull weeds, remove mud skippers and invasive fungi from the area.", progress = "Have you performed the tasks that I have asked for?", completion = "Is that an outsider's gear? You were aiding Orweyna with these--distractions, instead of your duties. How will you maintain our traditions if you can not follow my guidance through the ceremony?\n\nI will speak to Elder Hagar. Remember the importance of this day and your duty." }
WordHunterWoW_QuestEN[90959] = { title = "Traditional Duties", description = "Dalnir has a point about the ceremony, but we should not focus too narrowly. I still hold the values of our people, but sometimes we must look beyond.\n\nDo not worry. You should be focusing on the ceremony. I will search for the outsiders later.\n\nI am sure you could join me once the initiation ceremony is done.", objectives = "An inner voice is telling you to search for the outsider in Har'mara.", completion = "The outsider told us of your actions. \n\nYou must understand, <name>, though it was courageous, it was dangerous, even for you.\n\nI know Dalnir is furious, but Hagar understands your desire to help." }
WordHunterWoW_QuestEN[90960] = { title = "My Story, My Legacy", description = "{name}, the final part of the ceremony is ahead of you, though you've put it at risk with your digressions.\n\nThe first mural will show you a vision of your true self, the one that resonates from within you.\n\nThe second mural will show you a vision of where you are needed.\n\nThe third mural, tradition tells us, breaks the barrier between us and the Goddess herself.\n\nThe ceremony will conclude with you painting your story in the Den.", objectives = "Elder Hagar asked you to commune with the three murals, and then paint your own story.", progress = "Take your time, <name>. The ceremony is not about how fast you do it, but about what you learn from it.", completion = "In all my years of initiations, this has to be a first. It seems that the Goddess herself has noticed you.\n\nI am sensing a mysterious and bountiful journey ahead of you." }
WordHunterWoW_QuestEN[90961] = { title = "Stranger in a New Land", description = "{name}, I see you now for who you are. You are dedicated not just to our people, but to the world.\n\nThe goddess has acknowledged you as well, and I can not recall such an event--not even Orweyna's ceremony was so eventful.\n\nThis is where your story begins. It is time for you to take the first steps of your journey.", objectives = "With the conclusion of the ceremony, it is now time to start your journey.", completion = "So you are <name>? \n\nI never thought a <race> would show up in the city. With that, Your actions precede you. \n\nI have arranged some basic gear for you. It is the least I can do for saving one of us." }
WordHunterWoW_QuestEN[90962] = { title = "Stormarion Assault", description = "", objectives = "" }
WordHunterWoW_QuestEN[90963] = { title = "Caves of the Cleft", description = "Good work freeing the captured rutaani. With the seeds you recovered, I can try to carry on Ru'gar's work.\n\nI did some scouting and gathering while you were keeping the fungarians distracted, and could use your help with another task. Meet me at the cave northeast of here.", objectives = "Meet Ney'leia near the northeastern cave in Fungal Cleft.", completion = "This seems to be a safe location from which to plan our next moves, and one of the plants Ru'gar mentioned to me grows in this area as well." }
WordHunterWoW_QuestEN[90968] = { title = "Titanic Rumblings", description = "Rumors are abuzz of titan forces being sighted around Khaz Algar. Brann has asked Dagran Thaurissan II for assistance in looking into these rumors.", objectives = "Seek out Dagran Thaurissan II at the Delver's Headquarters in Dornogal.", completion = "If these rumors are true, we must investigate." }
WordHunterWoW_QuestEN[90969] = { title = "Titan Consoles", description = "Adventurer, the rumors are true. I've seen the titan forces and they are nae friendly. We must try tae discover why they are emergin' now and try and stop 'em from doin' too much damage.\n\nConfront and stop these renegade constructs. To help ye, I've procured some Titan Consoles. I was able to set them up in the affected areas. I can use them to communicate with ye in the field. I am thinkin' we can use them to counter these titan forces as well.", objectives = "Seek out one of Dagran's Titan Consoles in an Overcharged Delve.", completion = "<name>, these consoles are bein' overloaded by the titan's presence. If we can defeat them and secure titan discs, I think we can use 'em to empower the console to grant ye boons within the space. The boons can aid you in pushing back these rogue titan constructs." }
WordHunterWoW_QuestEN[90970] = { title = "Titan Disc-Count", description = "We need tae secure more titan discs. Venture deeper into this area, seek out the Titan Constructs, and defeat them. Ye should find disc shards. This console can reassemble them and access their data. \n\nMake sure tae search for any treasure rooms as well. The constructs appear to be assistin' the local denizens. Some of those locals might've secured additional titan discs with their other treasures.", objectives = "Secure Titan Disc Shards and dispatch Titan Constructs within the delve.", progress = "Adventurer? Is that you?", completion = "Did ye find the shards? While ye were away, I remembered I'd found some on my visit to that location. Ye should find them in a pouch I hid next to the console." }
WordHunterWoW_QuestEN[90971] = { title = "Overcharged Console", description = "With the shards ye found, we can use the console tae restore the titan discs and use them to access powerful boons. \n\nUse the console's disc repair feature to create a titan disc, then use that disc to select a starting node in the overcharge console's interface.", objectives = "Restore a Titan Disc and then spend it to unlock one of the starting nodes in the Overcharged Console Tech Tree.", progress = "Did it work?", completion = "My remote console shows that there was a change. The overcharged console is funnelin' excess energy to a new node. This should grant ye that node's power when venturin' intae other areas where the titan constructs have emerged.\n\nWe'll use the titan force's own energy against 'em!" }
WordHunterWoW_QuestEN[90972] = { title = "A Common Cause", description = "{name}! I heard you were here on K'aresh. Good. I need help.\n \nMy apprentice Leona has been researching novel means of harnessing the power of the Void. She's approached a Demon Hunter named Adarus to see if the Illidari's methods could offer any insights.\n \nTo be honest, I'm not sure I trust Adarus. He's not... studious. Unlike Leona.\n \nLeona was just going to observe him as he sought to master the Void. But she's disappeared. Please find her. Talk with Adarus--he knows something.", objectives = "Speak to Adarus.", progress = "Have you spoken to Adarus yet, <name>? It's clear that the Illidari's apotheosis has stripped them of their manners.", completion = "Adarus sent you? \n\nHis lack of faith in my abilities and desire to delegate speak volumes." }
WordHunterWoW_QuestEN[90993] = { title = "Take the Darkwell!", description = "We have our army but what lies behind these walls are the most powerful, most vile, and most empowered foes Xal'atath has in her arsenal. \n\nGather your strongest allies, {name}, and meet us within. It is time to end this and take back our well.", objectives = "" }
WordHunterWoW_QuestEN[90995] = { title = "The Future of The Fel Hammer", description = "Oh wait! Of course, right when I send you off I remember the most important thing!\n\nThe you-of-this-timeline made a critical choice for the future of all demon hunters. The follower they chose to be their personal champion created two diverging timelines for the fate of the Illidari.\n\nYou will need to choose which of these diverging timelines to explore. What rings true to you?", objectives = "Choose your personal champion.", progress = "Have you made a choice?", completion = "Very well, we will study this version of the timeline. Let us see what the Illidari hold in their future--err, past." }
WordHunterWoW_QuestEN[91000] = { title = "A Humble Servant", description = "{name}, residents of Hammerfall have been focused on daily life, defense, and survival over the past months. \n\nThey have not had sufficient time, or frankly numbers, to address all the harms that were done.\n\nThere is much we can do to help them get back on their feet.\n\nI know this is humble work, but it makes a very real difference to the orcs who live here.", objectives = "Aid the people of Hammerfall in their recovery.", progress = "There is much to do, <name>.", completion = "Good work, <name>. Things are starting to look better." }
WordHunterWoW_QuestEN[91001] = { title = "Clear de Way", description = "With dey magic and dey line broken, de Twilight's Blade is losin' ground.\n\nWe must take advantage of dey turned backs.\n\nI will lead de charge through de ravine to de Conquerer's Sanctum beyond. Mor'duun is there, keepin' his coward-body safe from our spears and axes.\n\nHe won't be safe much longer.", objectives = "Regroup with Zul'jarra, Zul'jan, and Lady Liadrin at the foot of Conquerer's Sanctum in Broken Throne.", progress = "We must act--now!", completion = "Mor'duun may laugh now, holed up in de Sanctum.\n\nBut we will get de last laugh." }
WordHunterWoW_QuestEN[91009] = { title = "Durable Information Storage Container", description = "Adventurer, can you hear me? I've discovered a smaller titan device, the Durable Information Storage Container, which can fit on yer belt. I've deduced they'll be able tae play smaller titan discs, granting ye boons ye can use anywhere. \n\nEach of these devices need a jump start. If ye kick up enough dust in these delves it should generate a spark that the device will detect and collect. It should be enough tae power it for yer lifetime.", objectives = "Complete a Delve to charge the device.", progress = "The overcharging is key.", completion = "Attach the device. Yes! The device is powered on. \n\nOkay... If I just start the initialization sequence... and it's up. There are already two discs inside. And the menu will list areas where other miniature titan discs can be found. I'm thinkin' I can improve the device, but I need time. Find me later and see." }
WordHunterWoW_QuestEN[91022] = { title = "Endeavor Reward", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[91023] = { title = "Endeavor Reward", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[91024] = { title = "Endeavor Reward", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[91026] = { title = "Gathering an Upgrade", description = "Hello? Hello? You're back! Perfect!\n\nI was studying the titan console and gathering a bunch of new information from the overcharged areas including the faulty directives that were found. This might be the key to this unexpected behavior, but I'll need more time tae know for sure.\n\nReturn to the delves and we can check the results of the faulty directives, I can use the information to create an upgrade for yer belt!", objectives = "Complete any Delve.", progress = "Were ye successful?", completion = "Here, yes... With that information I can make some final tweaks. And adding this directive...\n\nAh! That should do it. If you insert this into yer durable information storage container, it should update the effectiveness of the device's, um... effects." }
WordHunterWoW_QuestEN[91030] = { title = "New Titan Directives", description = "My calculations need a lot more data. I've got another upgrade card nearly finished, but I'm not sure if it will integrate properly.\n\nBut if ye go back into the delve spaces and defeat more of the enemies, I can see how they react. Based on their reactions, I can put the final touches on this upgrade for yer belt.", objectives = "Complete any Delve.", progress = "I can't wait to see the data!", completion = "Hmm, as I suspected. Yes... I need to adjust this here... done.\n\nThe good news is that this upgrade will nae make yer belt explode! I thought there was a small chance, but no longer. Yer data proved that I set the power too high. So... good thing I had ye do tha' extra check, right?" }
WordHunterWoW_QuestEN[91031] = { title = "Pushing it to the Limit", description = "I realized after ye left last time that I might have worried ye a wee bit with the whole exploding belt upgrade possibility. I'm sorry. I get a bit excited sometimes.\n\nI do think I can get even more power out o' the belt. At least a bit more. Safely of course! In yer data, I've seen that you've encountered many enemies as ye entered many delves. That's the key, return one more time for this last upgrade for yer belt.", objectives = "Complete any Delve.", progress = "I cannae wait to see if I was correct!", completion = "The data from that last excursion provided what I needed for another upgrade. But this is the last upgrade we can do for the belt, unless we want a major meltdown. Of course a meltdown would tell us a lot about the design...\n\nMa always said, \"Dagran! If yer gonna destroy ancient, irreplaceable artifacts, destroy yer own.\" So this is the last upgrade.\n\nHere is the last upgrade card. Thank ye for yer help. I hope we get a chance to experiment more in the future!" }
WordHunterWoW_QuestEN[91033] = { title = "Monitoring 'Construct'ing", description = "Welcome back, adventurer. I have a simple request for ye. I need ye tae continue monitorin' these titan constructs. \n\nWe have seen them moving around Azeroth in different locations, but I've not yet figured out their end goal or what instructions they might have. Perhaps if ye can gather more information, an insight will present itself.", objectives = "Complete an Overcharged Delve.", completion = "Their behavior seems mostly unchanged. This is very frustrating. Also if yer data is correct, it looks like they might be calmin' down. \n\nWe will have tae see if this observation is true. And here is some additional gear that we have collected. I hope it has served ye well over the course of our scientific endeavors!" }
WordHunterWoW_QuestEN[91035] = { title = "Construct De-Escalation", description = "Yer previous results showed a reduction in the overcharge present in the constructs. We must see if that was a one-off or if the reduction is escalatin'...\n\nHead back into these overcharged areas and test out the charge on the constructs, then report back.", objectives = "Defeat 5 constructs and complete an Overcharged Delve.", completion = "Wow! Tha' drop off is huge. If this holds steady, these constructs could be gone soon! \n\nWe still don't know what prompted them to come out! What if we never know? I hope that they return.\n\nOh, no! I don't want them tae mess things up. I just hate tae leave this unsolved. \n\nAt least we will be more prepared if we do see them again. Thank ye for yer help, <name>. I've checked the numbers and yer belt should still work, even if the constructs do retreat. \n\nAnd one last box of supplies for yer help." }
WordHunterWoW_QuestEN[91038] = { title = "Hellhunters Wanted", description = "<A scorch-marked missive has been nailed to this wall.>\n\nHELL COMES FOR YOU!\n\nNow that we have your attention, please be warned that shards of brimstone have entered this world. They are warm to the touch and should not, under any circumstances, be stabbed into your head, the head of anyone else, or any other vital organ of you or anyone near you.\n\nPlease bring any shards you find IMMEDIATELY to us in Dornogal.\n\nAnd if you see any tiny little minions carrying a bag of treasures, KILL THEM ON SIGHT.", objectives = "Bring the missive to Baranar in Dornogal.", completion = "We appreciate your interest in aiding us.\n\nShards of our timeline have made their way into your world. It is a place more grim and dark than your own, where some villains became heroes and some heroes never had the chance.\n\nHelp us locate these hellish fragments out of time and return them to their rightful place, and we will provide you with armors tempered by the fires of our world.\n\nAnd should you find any Treasure Goblins that lurk in your world, we implore you to slay the abominations." }
WordHunterWoW_QuestEN[91039] = { title = "Faerin's Request", description = "{name},\n\nGeya'rah and Danath have arrived in Dornogal. They both seem upset about rising tensions in the Arathi Highlands. It sounds serious.\n\nCan you come to Dornogal? I believe your presence can help the situation.\n\nFaerin", objectives = "Speak to Faerin Lothar in Dornogal.", completion = "<name>! Thank you for coming." }
WordHunterWoW_QuestEN[91040] = { title = "Vexatious Vilebranch", description = "", objectives = "" }
WordHunterWoW_QuestEN[91041] = { title = "A Gently Shaken Gift", description = "", objectives = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special <race> <class>." }
WordHunterWoW_QuestEN[91042] = { title = "A Winter Veil Gift", description = "", objectives = "A small tag on this present reads:\n\nHappy holidays, <name>!" }
WordHunterWoW_QuestEN[91044] = { title = "Hunger of the Void", description = "I did all I could to prevent this outcome. If you hadn't pushed him through the portal the unrestrained void energy would've collapsed the cave around us.\n\nHe was strong. In a way, I think that worked against him.\n\nMeet me back in Shan'dorah. I need to report to Umbric and let him know what happened here.", objectives = "Reconvene with Magister Umbric and Leona back in Shan'dorah.", progress = "I could feel the void energies roiling from here, <class>. What exactly happened?", completion = "I sincerely hope that Adarus is well, and that he doesn't blame us. The ren'dorei have enough enemies as it is.\n\nI am excited that Leona has made a breakthrough. Though she never would have succeeded without your help." }
WordHunterWoW_QuestEN[91052] = { title = "Worldsoul: Overcharged Delves", description = "Something has caused hostile titan constructs to activate and enter various caverns and spaces around Khaz Algar. Venture to these locations and investigate and eliminate the threat they pose.", objectives = "Complete an Overcharged War Within Delve at any difficulty.", completion = "It is unnerving to not know what has forced these hostile titan units to surface. But due to your efforts their threat is at an end." }
WordHunterWoW_QuestEN[91061] = { title = "Infinite Chaos", description = "You may think this ironic, but our time is running short, {name}. Great forces threaten more than one world's future.\n\nNozdormu won't like it, but I must hasten our study with experimentation. I have isolated a fractured timeline for you to explore. But be warned--this realm is devoid of all hope. It is the only way I can truly prepare us for what is to come.\n\nI have established a research console by the fel monument behind you. Use it to enter this forbidden future so that we may learn the unknowable.", objectives = "Explore the Heroic World Tier.", progress = "Have you seen the dark times that could have been?", completion = "You are braver than I thought, <name>.\n\nPlease continue to experiment. I will not let us enter dangerous futures unprepared." }
WordHunterWoW_QuestEN[91062] = { title = "Broken Bridges", description = "I make one last request of you before you return with Liadrin to Silvermoon, hash'ura.\n\nFind Zul'jan. None have seen him since returnin' to Amani'Zar.\n\nOn de way back here, I confronted him about takin' our soldiers to Broken Throne against my orders.\n\nPeople died dat shouldn't have. I asked him what he don't understand about dat.\n\nHe didn't argue. He was blank. His body was there, but his mind?\n\nSometimes he seeks peace in de sound of ocean waves.\n\nYou might find him on de Skybridge.", objectives = "Seek out Zul'jan upon the Skybridge.", completion = "Glad I found you. Zul'jarra let me know you would be searching this area for Zul'jan, but this land is still so unfamiliar to me.\n\nIf you have found him and are finished enjoying the party, we should return to Silvermoon." }
WordHunterWoW_QuestEN[91063] = { title = "The Blooming Lattice", description = "You're that stranger I've been hearing about, aren't you? I'm Su'meera, apprentice painter to Ja'kul. You heard of him? No? Maybe his work hasn't made it to your lands. That makes sense, I guess.\n\nAnyhow, I heard you like helping people out. Well, a few important things went missing when Ja'kul was attacked and killed. I want them back.\n\nWill you meet me near Blooming Lattice?", objectives = "Meet Su'meera near Blooming Lattice.", completion = "Thanks for coming. I wasn't sure you would. Up the hill that way is Blooming Lattice--a settlement of rutaani who are quite vicious.\n\nTheir leaders killed Ja'kul, and took his things. I want them back!" }
WordHunterWoW_QuestEN[91065] = { title = "Purloining Petals", description = "A couple of days ago, a group of rutaani attacked and killed my mentor, Ja'kul. When they did, their stupid birds stole a few things from him. Those petals-for-brains will make off with anything shiny that isn't thorned down.\n\nWill you recover Ja'kul's things for me? I'm a painter, not a fighter. I wouldn't last very long in there on my own.", objectives = "Recover stolen objects from Blooming Terrace.", progress = "Those birds would steal your head if it wasn't attached to your shoulders. Especially if you were wearing a shiny hat or helm. Right off your shoulders!\n\n<She pauses for a moment as if picturing this, then turns slightly green and shudders.>", completion = "You did it! I knew they had these, those rotten weed-for-brains scavengers!\n\nI know it's silly to be upset about things like a favorite spoon, but they took Ja'kul's life. I won't let them take anything else from him.\n\nYou're the best, <name>." }
WordHunterWoW_QuestEN[91066] = { title = "Brewmaster's Kitchen", description = "Good, you've brought the supplies. Now, we begin the feast. We'll need plenty of food to keep up our strength.\n\nThe menu's simple, but worthy: Barley Stew, Stone-baked Pretzels, and a strong brew to fuel the Horde!\n\nAre you prepared to learn?", objectives = "Follow the steps to cook Brewfest food and a delicious Brew.", progress = "Start the fire and get to work!", completion = "Hah! I can smell those pretzels from here. You've cooked up a feast fit to silence even the grumbling of dwarves!" }
WordHunterWoW_QuestEN[91067] = { title = "Gathering the Grub", description = "Ah, you're here. Brewfest has begun-but we've got a problem. Can't have a proper feast without food, and some thieving hozen thought it'd be clever to snatch our grub.\n\nHere's what you'll do: track down those hozen and take back what's ours. You might find a few bags just lying around too-grab those. Once you've got the goods, toss them in the wagon behind me.", objectives = "Collect Bags of Brewfest Ingredients and deposit them at the wagon.", progress = "The feast won't come together without those ingredients!", completion = "You've done it! The cooks will be pleased." }
WordHunterWoW_QuestEN[91068] = { title = "Serving with Style", description = "You've proven your strength at cooking, now it's time to prove it on the floor! Brewfest isn't just about feastin-it's about bringing the revelry to every corner of the camp.\n\nYou'll be taking orders, hauling plates, and pouring ale like a true warrior of celebration.\n\nNow get out there and show them what real service looks like! Brewfest don't run on empty mugs!", objectives = "Take the customer's order and serve the food to them.", progress = "Remember to serve with a smile!", completion = "I'd say you've earned yourself a break and a strong brew after all that work. But don't go getting soft on me! Brewfest isn't over, and there's still plenty of work to be done." }
WordHunterWoW_QuestEN[91069] = { title = "Vengeance for Tolbani", description = "Me and Tolbani had loaded de skiff with medicine, steel, and food to bring upriver to de forward camp.\n\nIt was meant to be a quiet run: no trouble, and no eyes on us.\n\nBut in de shallows, de murlocs came swarmin' out of de reeds all foam and teeth. Dey hit us hard--too fast to fight back proper. We tipped and lost de cargo. I barely made it to shore.\n\nTolbani didn't. I dragged his dart-riddled body here.\n\nDe murlocs must pay for what dey have done.", objectives = "Kill 12 murlocs in Atal'Abasi.", progress = "Bleed de mindless beasts. Make dem suffer for killin' Tolbani.", completion = "Do you hear dat?\n\nIt's quiet.\n\nDat is de sound of vengeance." }
WordHunterWoW_QuestEN[91070] = { title = "Reclaim the Goods", description = "While I was limping back from de river, I spotted a few of de murlocs dragging our food bags through de mud. They weren't working together either--kept snapping at each other, trying to snatch de best pieces for themselves.\n\nI saw one of them stash a whole satchel behind a fallen tree. Another buried something under a pile of rocks. Greedy little monsters think they can steal from us and get away with it.", objectives = "Find 6 stolen Food Provisions in Atal'Abasi.", progress = "Yes, <class>?", completion = "Good. That's all of it." }
WordHunterWoW_QuestEN[91071] = { title = "The Menace of Atal'Abasi", description = "Our boat didn't ground on its own.\n\nWe were fightin' de murlocs, and then suddenly we were in de air.\n\nDats when I saw him--one dat wasn't like de rest. Bigger. Stronger. When he attacked, de other murlocs scattered.\n\nHe picked up our boat like it weighed nothin' and hurled it on de rocks. I've never seen a murloc do somethin' like that.\n\nWe're gonna keep losin' people and supplies if dat muscle-bound murloc is watchin' de river.", objectives = "Find and slay Mrruk the Musclefin in Atal'Abasi.", completion = "I saw de small ones run away in terror. Well done, <class>." }
WordHunterWoW_QuestEN[91084] = { title = "Looming Shadows", description = "Though we've triumphed over Ruia and the Lightbloom for now, more remains to be done. The elders will want to convene regarding the Hara'ti's new place in the world, now that we have stepped out from the shadows of our past.\n\nOur reticence and fear will not vanish overnight. But this is an important first step.\n\nWe will be fine, {name}. Let Orweyna and I deal with the elders. When the time comes, the Hara'ti shall be at your side. For now, though, I'd imagine you have more pressing matters to attend to.", objectives = "Return to Regent Lord Lor'themar Theron in the Sanctum of Light in Silvermoon City.", completion = "When Halduron burst into a war council shouting about hidden worlds and ancient warriors, I thought he had gone mad. But now that I've seen the haranir with my own eyes...\n\nWe are lucky to have them as potential allies. And lucky to have you, I'd say, in brokering that relationship.\n\nThere is more for us to do. But I've no doubt that the Hara'ti will prove vital allies to Silvermoon in the days to come." }
WordHunterWoW_QuestEN[91085] = { title = "Petal Bristles", description = "Ja'kul was out hunting petalwings when the rutaani came upon him and killed him. We use their feathers for some of our paintbrushes. They are especially useful in helping the young sprouts learn how to be more precise and delicate. \n\nWhile you're up there, will you bring me back some of their plumes?", objectives = "Collect 8 Petalwing Plumes.", progress = "Have you gathered the petalwing plumes I asked for? They're essential for the lessons of the younger haranir.", completion = "Thank you for bringing me these feathers! I will use one of them to paint a special memorial for Ja'kul. The rest will go to the children. \n\nI suppose it will fall to me now to teach them." }
WordHunterWoW_QuestEN[91086] = { title = "Nipping the Buds", description = "The rutaani of Blooming Lattice were behind the attack on Ja'kul. They're led by a Prime Bloomwarden who's even more vicious. I hate them and they're all terrible!\n\nHow about you go prune the overgrowth and make the rest of us safer?", objectives = "Kill rutaani and the Prime Bloomwarden in Blooming Lattice.", completion = "Is it done? Thanks. It won't bring Ja'kul back, but now they won't be hurting anyone else." }
WordHunterWoW_QuestEN[91087] = { title = "Reports Returned", description = "I will go to Silvermoon but... I will return here to advise Zul'jarra.\n\nI feel I let my past and my prejudices get in the way of my judgement regarding the Amani. You could say that being a hash'ura is a befitting atonement but... I feel drawn to stay, perhaps to help Zul'jarra in guiding her people back to the loa.\n\nI will go to Silvermoon with you to bear the report--and Lor'themar's reaction.\n\nIf we go now, we may return to... party.\n\n<A small smile cracks Liadrin's usually stoic face.>", objectives = "Report to Lor'themar Theron in Silvermoon City.", completion = "<Lor'themar raises an eyebrow and frowns slightly. You can tell he is fighting back exasperation and anger.>\n\nThis is a... very unexpected turn of events. Yet still more will unfold in front of us, I'm sure." }
WordHunterWoW_QuestEN[91088] = { title = "Behind the Falls", description = "The scroll you brought back was left behind for me by my mentor, Ja'kul. I didn't even have a chance to read it before it was stolen away! \n\nJa'kul left directions in the scroll to a cave that's behind a waterfall in Blooming Lattice. I'm not sure what we'll find there, but I would really appreciate if you came along while I check it out. Will you meet me there?", objectives = "Meet Su'meera in the cave behind the waterfall in Blooming Lattice.", completion = "This is incredible! I can't believe there's a whole cave back here. And Ja'kul left behind a vision stone for me." }
WordHunterWoW_QuestEN[91089] = { title = "Defeating Ky'veza", description = "So she's here to collect a bounty, eh?\n\nDid nae one tell her it's rude to try and kill a Champion of Azeroth? Or a Bronzebeard, for that matter?", objectives = "Increase your item level to challenge Ky'veza in her tier 8 delve on K'aresh.", completion = "Whew! Good riddance.\n\nI cannae stand all tha skulking around and teleportin' about tha place.\n\nMight be time for a wee bit of vacation after all this excitement." }
WordHunterWoW_QuestEN[91090] = { title = "Pesky Pests", description = "Nearby creatures are suffering an infection of Light, and are being drawn to the Sunbath. Our guests find it disturbing. That is a problem, when one is trying to enjoy a tranquil escape from the world.\n\nI confess, having one run into your leg while you are swimming can be unnerving.\n\nPlease, dissuade the invading sungrubs from joining us, and take to the sky to chase off those persistent butterflies.", objectives = "Kill 10 Sungrubs and fly to chase away 10 Persistent Butterflies.", progress = "Are the insects giving you trouble?", completion = "That wasn't so bad, was it? \n\nVal does get a bit dramatic, but you performed wonderfully." }
WordHunterWoW_QuestEN[91093] = { title = "More Than Just a Phase", description = "Untethered Space represents an ongoing danger to our people on K'aresh. It is infested with banished souls, broken technology, and monsters of all kinds.\n\nAid the K'aresh Trust and defeat our foes in Untethered Space. You may use the Phase Conduits to navigate between the remnants of K'aresh while phase diving.", objectives = "Complete activities while phase diving in Untethered Space on K'aresh.", progress = "I dream of a day when we K'areshi can roam these lands freely and without fear.", completion = "Your assistance is most appreciated, <race>. The Trust was wise in appointing you to aid our efforts." }
WordHunterWoW_QuestEN[91095] = { title = "Prey: Magister Sunbreaker (Normal)", description = "Once a noble Magister of Silvermoon, sworn to protect Quel'Thalas at any cost, he has broken away from the order and now seeks vengeance on his own terms.\n\nI see something of myself in him.\n\nKill it for me.", objectives = "Hunt down Magister Sunbreaker and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91096] = { title = "Prey: Magistrix Emberlash (Normal)", description = "Alas, you can only catch so many innocent bystanders in your fireballs before you find yourself ostracized from polite society. Emberlash was always more interested in flame than friends...\n\nShe has burned one too many mutual acquaintances. \n\nIf she will not control her power, we will gladly take it for our own.", objectives = "Hunt down Magistrix Emberlash and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91097] = { title = "Prey: Senior Tinker Ozwold (Normal)", description = "Rumor has it that Ozwold single-handedly raised insurance premiums in Gnomeregan before their little exodus. Be that as it may, he's consistently taken to perfecting his gadgetry regardless of the cost to others.\n\nHis ambition is admirable, but his methods are irredeemable. \n\nGo and see that his inventing days come to an end.", objectives = "Hunt down Senior Tinker Ozwold and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91098] = { title = "Prey: L-N-0R the Recycler (Normal)", description = "Do you know why they call her the Recycler, {name}? I don't. And given her history of \"disappearing\" shop assistants, I'm not really inclined to ask her.\n\nThat being said, watch your step. I understand that she likes to incorporate her victims into her gadgetry. We wouldn't want you becoming a pocket watch or some such thing.", objectives = "Hunt down L-N-0R the Recycler and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91099] = { title = "Prey: Mordril Shadowfell (Normal)", description = "The Void is a perfidious thing, like water. The wise keep it at a respectful distance, never dancing too close to the edge. The foolish dive in, and in so doing, drown.\n\nMordril is a danger to himself and everyone around him, so lost is he in his own obsession.\n\nSee to it that he no longer poses a threat to this realm.", objectives = "Hunt down Mordril Shadowfell and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91100] = { title = "Prey: Deliah Gloomsong (Normal)", description = "In a previous life, Deliah Gloomsong was a prodigious student--truly a marvel of ambition, talent, and unrelenting curiosity. \n\nIt was the latter that got the best of her.\n\nPut an end to her murderous spree.", objectives = "Hunt down Deliah Gloomsong and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91101] = { title = "Prey: Phaseblade Talasha (Normal)", description = "Ethereals... they make my skin crawl. Esoteric. Unknowable. I don't trust anything I can't look in the eyes while it grovels before me.\n\nMy scouts report that a particularly dangerous ethereal is active in a nearby region. We would do well to nip this in the bud while we still can.", objectives = "Hunt down Phaseblade Talasha and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91102] = { title = "Prey: Nexus-Edge Hadim (Normal)", description = "Our activities are drawing unwanted attention. I have heard whispers that a powerful ethereal assassin is on my... on our trail. It would be very difficult indeed to defend our city as twin piles of bloody ribbons.\n\nGo out there and show this \"assassin\" the true art of the kill.", objectives = "Hunt down Nexus-Edge Hadim and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91103] = { title = "Prey: Jo'zolo the Breaker (Normal)", description = "Jo'zolo the Breaker is a troll who abides by his name. Long has he been the bane of our scouts, but no more! \n\nKill him. Feed his anguish to the defenses of our beloved city.", objectives = "Hunt down Jo'zolo the Breaker and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91104] = { title = "Prey: Zadu, Fist of Nalorakk (Normal)", description = "Our neighbors produce some of the most skilled hunters in all of Azeroth. It is a shame they are so difficult to reason with. \n \nThere is one named Zadu. Her anguish would make for a most excellent trophy...", objectives = "Hunt down Zadu, Fist of Nalorakk, and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91105] = { title = "Prey: The Talon of Jan'alai (Normal)", description = "There is a powerful troll shaman who calls himself the Talon of Jan'alai. Long has he confounded our city's Farstriders, sowing confusion and death in his wake.\n\nSee to it that he joins the spirits he so ardently venerates.", objectives = "Hunt down The Talon of Jan'alai and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91106] = { title = "Prey: The Wing of Akil'zon (Normal)", description = "Do you smell that? There is death on the air. This can only mean one thing. The Wing of Akil'zon is near. Go out and slay her.\n\nOh, and be careful. She's responsible for more than one lost Farstrider patrol.", objectives = "Hunt down The Wing of Akil'zon and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91107] = { title = "Prey: Ranger Swiftglade (Normal)", description = "It is a difficult thing, to hunt one of our own. Ranger Swiftglade is beyond redemption. His bloodlust could not be sated against our foes, and he has since turned his martial prowess upon his own people.\n\nEnd his sadistic killing spree and put his anguish to better use.", objectives = "Hunt down Ranger Swiftglade and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91108] = { title = "Prey: Lieutenant Blazewing (Normal)", description = "I do not know what to make of Lieutenant Blazewing. Her entire patrol disappeared during a reconnaissance mission into Zul'Aman. She was the sole survivor, but she returned with a fiery bloodlust and a complete disregard for the lives of others. \n\nWhether this is possession or sedition I am unsure, but she must be dealt with.", objectives = "Hunt down Lieutenant Blazewing and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91109] = { title = "Prey: Petyoll the Razorleaf (Normal)", description = "Reports are coming in of shredded Farstriders adorned with petals and berries--entire patrols found strung up by razor-vines. There are more gruesome details, but they chafe even my... refined sensibilities. \n\nHunt whatever manner of creature is embarking on this horrific killing spree, and see to it that its anguish is added to our crystals.", objectives = "Hunt down Petyoll the Razorleaf and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91110] = { title = "Prey: Lamyne of the Undercroft (Normal)", description = "Do you garden, {name}? I've been known to dabble. It seems the plants in our realm are becoming somewhat overbearing these days, sprouting legs and arms and running around murdering our brave soldiers. \n\nLet's give them a bit of a pruning, shall we?", objectives = "Hunt down Lamyne of the Undercroft and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91111] = { title = "Prey: High Vindicator Vureem (Normal)", description = "High Vindicator Vureem is a victim of his own unyielding faith in the Light and the superiority it gives him. His crusade continues unabated and unresolved. He exists in a constant state of fury at the imperfectness of the world and those within it.\n\nIn the absence of total purity, Vureem sees only violence and the shadows of his own dogma. \n\nWhat say we put his worldview to the test?", objectives = "Hunt down High Vindicator Vureem and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91112] = { title = "Prey: Crusader Luxia Maxwell (Normal)", description = "We are not sure if Luxia Maxwell is a deserter or has simply decided to embark on her own personal crusade. Regardless, reports are coming in of her attacking both friend and foe alike, yelling aphorisms of purity and duty.\n\nShe has become a liability to the defense of Silvermoon. \n\nGo and harvest her anguish.", objectives = "Hunt down Crusader Luxia Maxwell and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91113] = { title = "Prey: Praetor Singularis (Normal)", description = "The domanaar...\n\n<Astalor shudders.>\n\nI do not profess to know much about them, other than their proclivity for subterfuge, guile, and the absolute destruction of anything that stands before them. Praetor Singularis is no exception. They have been confounding our forces at every turn.\n\nGo and put an end to their games.", objectives = "Hunt down Praetor Singularis and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91114] = { title = "Prey: Consul Nebulor (Normal)", description = "I have heard that there is one under Xal'atath's command who takes particular delight in dominating their foes. Whispers of a domanaar that taunts its victims with whispers and riddles before annihilating their mortal coil with void magic.\n  \nConsul Nebulor is their name.\n\nGo and show them the limits of their power.", objectives = "Hunt down Consul Nebulor and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91115] = { title = "Prey: Executor Kaenius (Normal)", description = "The domanaar have a reputation for guile and cunning, but there are brutes among them: those who seek to dominate their victims through sheer power and force of will.\n\nExecutor Kaenius is one such domanaar.\n\nThey stalk the battlefield, singling out our strongest soldiers and viciously cutting them down.\n\nPut an end to their rampage.", objectives = "Hunt down Executor Kaenius and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91116] = { title = "Prey: Imperator Enigmalia (Normal)", description = "Imperator Enigmalia is personally responsible for the deaths of at least a dozen Farstriders. I say \"at least\" because this particular domanaar makes it somewhat difficult to identify the bodies, so utterly destroyed are they.\n\nGo and avenge our fallen soldiers.", objectives = "Hunt down Imperator Enigmalia and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91117] = { title = "Prey: Knight-Errant Bloodshatter (Normal)", description = "Death knights are unstable killing machines at the best of times. Knight-Errant Bloodshatter has forsaken any oath or promise that would ostensibly bind one of his kind to the bottom rungs of civilized society, and has gone completely rogue.\n \nHe is starting to become a liability. \n\nRecoup his anguish so that we can make the best of such an unfortunate situation.", objectives = "Hunt down Knight-Errant Bloodshatter and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91118] = { title = "Prey: Vylenna the Defector (Normal)", description = "Vylenna the Defector lives up to her name. After a recent engagement on the field of battle, she became so preoccupied with profaning the dead that she completely abandoned the duties ascribed to her.\n\nThen her dereliction turned violent.\n\nA veritable font of anguish if you ask me...", objectives = "Hunt down Vylenna the Defector and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91119] = { title = "Prey: Lost Theldrin (Normal)", description = "Those of us who succumbed to our base desire for mana were slowly weeded out of civil society, if they survived at all. Theldrin is one such example, only it is a testament to his cunning and will to live that he has made it as long as he has.\n\nHe accepts no aid, choosing instead to stalk careless students and idle Magisters. His sole obsession is the mana that others possess...\n\nSee to it that he never harms another elf again.", objectives = "Hunt down Lost Theldrin and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91120] = { title = "Prey: Neydra the Starving (Normal)", description = "Poor Neydra... I knew her, in a previous life. She was full of vitality. Full of ambition. Unfortunately, she let that ambition get the best of her. She grew too enamored with the raw power of the arcane. She became resentful of all other things. Of all other people...\n\nAnd now she is a murderous creature who beheads rats and attacks innocents in a desperate attempt to garner enough arcane energy to slake her unquenchable thirst.\n\nIt's funny, the paths life takes us...", objectives = "Hunt down Neydra the Starving and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91121] = { title = "Prey: Thornspeaker Edgath (Normal)", description = "This one presents a prickly problem indeed. Thornspeaker Edgath has made a name for himself by using his druidic powers not to preserve Azeroth, but to twist its strength both against his enemies and innocent bystanders alike. He has no regard for anything that is not a beast or growing in the ground.\n\nIt is time we clip this thorn.", objectives = "Hunt down Thornspeaker Edgath and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91122] = { title = "Prey: Thorn-Witch Liset (Normal)", description = "Thorn-Witch Liset is a curse upon civilization and a blight upon the land itself. She twists the very trees and beasts, communing with the dark, evil things that live on the very edges of the natural realm.\n\nI despise the natural realm.", objectives = "Hunt down Thorn-Witch Liset and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91123] = { title = "Prey: Grothoz, the Burning Shadow (Normal)", description = "The Twilight's Blade are an embarrassing band of mediocre cultists and uninspired conspirators. Grothoz is the brains of a particularly stupid cabal that has been active in a nearby region. \n\nAs his stupidity prevents him from using his whole brain, let us unlock his potential for him...", objectives = "Hunt down Grothoz, the Burning Shadow and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91124] = { title = "Prey: Dengzag, the Darkened Blaze (Normal)", description = "Do you know why the Twilight's Blade call Dengzag the \"Darkened Blaze?\" It is because they are stupid, small-minded, and utterly bereft of imagination. What a silly name indeed. \n\nI, however, am not small-minded. I have quite the prodigious mind, and it is currently intent on putting an end to Dengzag and whatever his tiny brain is up to. \n\nGet to it.", objectives = "Hunt down Dengzag, the Darkened Blaze and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91136] = { title = "Memories in Stone", description = "Ja'kul was killed before he could finish my training, but I would recognize his work anywhere! He must have painted this vision stone for me!\n\nThe rutaani will catch on pretty soon that we're up here, and I won't be able to defend myself. Will you keep watch while I journey into the memory he left me?", objectives = "Defend Su'meera while she vision walks.", completion = "Thank you so much, <name>. You gave me a way to say goodbye to my mentor. Now that I have seen what he wanted me to, I can continue my training.\n\nIt means so much that Ja'kul left this here for me. I miss him, but I will honor his memory." }
WordHunterWoW_QuestEN[91137] = { title = "Lost in Light", description = "It seems some of our more adventurous guests have not returned from their hike. Val said he saw a rutaani skulking about earlier, but I was certain he was just trying to add some drama to our day.\n\nThe Lightbloom infiltrated the Sanctum to the north and has been spilling residual issues our way.\n\nOur guests are here to escape the troubles of the world... This all could become a bit too real for them.\n\nIf you'll take care of that situation, I'll make sure Val keeps the guests distracted.", objectives = "Kill Liya Waterbloom and send the hikers home.", progress = "Did they make it back?", completion = "Tormenting our guests was a step too far.\n\nShe encroached on the sunbath and has paid the price for her actions.\n\nThank you, new friend of the Solaar family!" }
WordHunterWoW_QuestEN[91138] = { title = "I am the Creator and Destroyer", description = "Such a small thing, really. And devoid of any of the power T'uure once nurtured. But a relic of inestimable value nonetheless.\n\nDid you know, {class}, that to T'uure, the dark and the light were inseparable aspects of a greater truth?\n\nWhat creates, has the power to destroy in equal measure. Demonstrate this lesson and you will reach a new understanding of yourself, and of the great Naaru whose sacrifice was able to halt the annihilation of an entire planet.", objectives = "Demonstrate your mastery over life and death.", completion = "Ah yes. I can sense the change in you. The growth that comes with meting out death in one hand, while nuturing life in the other.\n\nPerhaps this small token will serve as a reminder of T'uure and his role in Dimensius' ultimate fate." }
WordHunterWoW_QuestEN[91140] = { title = "A Piece of the Past", description = "<This crystalline fragment has lost any luster it once had. Now finally extricated from Dimensius's dread form and in the hands of the devout, a brief glimmer revives in its depths.\n\nPerhaps someone in Tazavesh will know more.>", objectives = "Show the fragment to Om'en in Tazavesh.", progress = "What is this? Ah, I see now. You were right to come to me.", completion = "A fragment of the lost naaru T'uure? And lodged in the form of Dimensius?\n\nNow this is something I never thought I'd see." }
WordHunterWoW_QuestEN[91141] = { title = "My First Kill Quest [DNT]", description = "", objectives = "" }
WordHunterWoW_QuestEN[91142] = { title = "Tabard for the Trusted", description = "", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has set aside a fund to encourage such initiative." }
WordHunterWoW_QuestEN[91143] = { title = "Carved Crests", description = "", objectives = "Another task completed. The Trust thanks you for your efforts. The founder has set aside a fund to encourage such initiative." }
WordHunterWoW_QuestEN[91145] = { title = "The Conquered Heroes", description = "A domanaar was harrying our back lines. It was... different than the other void beasts--like it was playing rather than fighting. My partner, Callum, led a squad to hunt it down. They never came back.\n\nCallum's an Arathi through and through. He wouldn't fall here--I know it.\n\nCommander Lightblood refused to send a search party. He said there's a difference between personal and important. Well, the Vanguard can have their war, but I'm going after Cal. I know the route he took, but I can't search alone.", objectives = "Find Callum Ashvow's squad.", completion = "Imperia's beasts swarmed me. I lost track of them.\n\nI shouldn't have left you behind, but seeing that monster control Callum... I'm not losing him. Not while I still breathe." }
WordHunterWoW_QuestEN[91146] = { title = "Flickering Light", description = "I feel traces of Light here--dim, scattered across the plain, but unmistakable. It's Callum. I know his Light like I know my own.\n\nThat domanaar is a monster: using others like toys, smashing them together until they break. We'll find them, {name}, and then I will turn that void beast to ash.\n\n<Anais grips her spear.>\n\nOne thing at a time. Find the Light, and we find Callum.", objectives = "Find traces of Callum's Light.", completion = "She's hurting him, throwing him into fight after fight. We don't have time to search this whole blasted plain.\n\nI can't concentrate. The Void magic here is too chaotic and volatile." }
WordHunterWoW_QuestEN[91147] = { title = "Cut Her Strings", description = "Revik, Riandron, Danna... that domanaar made them kill each other. The creatures here are bound with the same shadowgrafts: the same twisted magic.\n\nIf this is how Imperia controls her victims, we have to find a way to remove it.\n\nRestrain the beasts and I'll attempt to break their bonds. If it's forged by the Void, the Light must be able to overcome it.", objectives = "Subdue creatures while Anais removes their Shadowgrafts.", completion = "Removing the Shadowgrafts kills them... What good is the Light if it can't save one man?" }
WordHunterWoW_QuestEN[91148] = { title = "Strung Along", description = "When the Light called, it called both of us. Why? So Callum could die on some void-scarred rock?\n\nI can't think here. All I can picture is Callum bleeding out. Come, we'll return to camp. With his belongings, I should be able to find him. \n\nThen... I don't know. If we can't break the shadowgrafts, we'll subdue him and drag him back to Silvermoon if we must. I'm not losing him.", objectives = "Help Knight Anais find and subdue Callum Ashvow.", completion = "I had him. One spear thrust and I could have ended it... but he's still Cal--even with that monster controlling him.\n\n<Anais clutches at ragged cut in her side. Blood and foul Void magic flow from the wound in equal measure.>\n\nLook what chasing after him again got me." }
WordHunterWoW_QuestEN[91149] = { title = "Bury Me Not", description = "I knew we'd never grow old together, but I thought we'd have more time.\n\n<Anais coughs, blood pooling beneath her. Flecks of the Void shimmer in the spreading crimson.>\n\nDon't worry. I'm not afraid. I promised myself I wouldn't go home without him... wouldn't spend a night in an empty bed. I'm just keeping that promise.\n\nDon't let her have him. Take his tinder box. You'll know what to do.", objectives = "Take Callum's Tinder Box and defeat Imperia.", progress = "My parents always said falling in love with a human would end in heartbreak.\n\n<She doesn't lift her head.>\n\nThere's never enough time, is there?", completion = "I felt it. When you--when he--thank you. Sorry. Getting hard to think.\n\n<She accepts the tinder box and holds it to her chest. Her eyes seem to focus on something you can't see.>\n\nCal...? I'm so tired. Let's go home.\n\n<Anais slumps over, her hand falling away from the wound at her side. She is at peace.>" }
WordHunterWoW_QuestEN[91173] = { title = "The Flame Burns Eternal", description = "These Sureki sure are a persistent bunch! We need to match their persistence with our blades.\n\nCan we count on your continued support in the battles ahead?", objectives = "Complete the Nightfall scenario.", progress = "Ready yourself soldier, the battle is still to come.", completion = "You've bought us a moment of peace.\n\nRest well, but always keep your blade sharp." }
WordHunterWoW_QuestEN[91193] = { title = "Special Assignment: Capstone 1 - Unlock", description = "", objectives = "" }
WordHunterWoW_QuestEN[91197] = { title = "Collecting Remains", description = "", objectives = "Collect 50 Void-Tainted Remains.", progress = "The domanaar need void-tainted remains to fuel their war effort. Scavenge the area or slay fellow adventurers across Slayer's Rise to obtain this resource.", completion = "Thank you for your contributions." }
WordHunterWoW_QuestEN[91203] = { title = "Special Assignment: Capstone 2 - Unlock", description = "", objectives = "" }
WordHunterWoW_QuestEN[91205] = { title = "Ultra Prime Deluxe Turbo-Boost: Powerhouse Challenges", description = "<Undermine has a problem. Here's what we need. An established group, or just a bunch a ya really, ready to help out our pals in Undermine. Help clear out the worst of the competition, and we'll make it worth your time.\n\nComplete the task, and collect a special reward from Consultant Wrexxle outside of the the Dornogal Treasury. Limited time offer. Some restrictions will apply.>", objectives = "Defeat any four bosses within The Liberation of Undermine raid on Looking For Raid difficulty or higher, or complete any four Mythic Dungeons.", progress = "Yous looks out for us, and we return the favor. Right?", completion = "Thanks, pal. Undermine is a mess right now. We'll take all the help we can get.\n\nAnd hey, a deal's a deal. Here's what we owe.\n\nWe call this the jackpot reward for first time help. Check back again for more work!" }
WordHunterWoW_QuestEN[91206] = { title = "Loa Disturbance", description = "Now dat we are tryin' to contact all de loa, my mind turns to Kulzi, de loa of medicine--and the madness that surrounds his shrine.\n\nHis loa speaker, Sij'ta, was a good friend. He healed many war parties of their injuries. But somethin' happened at Kulzi's shrine, and it is full of angry spirits.\n\nDey attack anybody dat tries to get through to dem, and de loa is silent.\n\nPerhaps you can finally reach out to de loa and find his speaker!", objectives = "Find Loa Speaker Sij'ta at the Shrine of Kulzi.", completion = "What do you mean, you don't have de medicine? I sent you for it ages ago!\n\nWe must help him... even if de loa won't!" }
WordHunterWoW_QuestEN[91207] = { title = "Prey: Apex Predator", description = "", objectives = "" }
WordHunterWoW_QuestEN[91210] = { title = "Prey: Magister Sunbreaker (Hard)", description = "Once a noble Magister of Silvermoon, sworn to protect Quel'Thalas at any cost, he has broken away from the order and now seeks vengeance on his own terms.\n\nI see something of myself in him.\n\nKill it for me.", objectives = "Hunt down Magister Sunbreaker and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91211] = { title = "Prey: Magister Sunbreaker (Nightmare)", description = "Once a noble Magister of Silvermoon, sworn to protect Quel'Thalas at any cost, he has broken away from the order and now seeks vengeance on his own terms.\n\nI see something of myself in him.\n\nKill it for me.", objectives = "Hunt down Magister Sunbreaker and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91212] = { title = "Prey: Magistrix Emberlash (Hard)", description = "Alas, you can only catch so many innocent bystanders in your fireballs before you find yourself ostracized from polite society. Emberlash was always more interested in flame than friends...\n\nShe has burned one too many mutual acquaintances. \n\nIf she will not control her power, we will gladly take it for our own.", objectives = "Hunt down Magistrix Emberlash and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91213] = { title = "Prey: Magistrix Emberlash (Nightmare)", description = "Alas, you can only catch so many innocent bystanders in your fireballs before you find yourself ostracized from polite society. Emberlash was always more interested in flame than friends...\n\nShe has burned one too many mutual acquaintances. \n\nIf she will not control her power, we will gladly take it for our own.", objectives = "Hunt down Magistrix Emberlash and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91214] = { title = "Prey: Senior Tinker Ozwold (Hard)", description = "Rumor has it that Ozwold single-handedly raised insurance premiums in Gnomeregan before their little exodus. Be that as it may, he's consistently taken to perfecting his gadgetry regardless of the cost to others.\n\nHis ambition is admirable, but his methods are irredeemable. \n\nGo and see that his inventing days come to an end.", objectives = "Hunt down Senior Tinker Ozwold and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91215] = { title = "Prey: Senior Tinker Ozwold (Nightmare)", description = "Rumor has it that Ozwold single-handedly raised insurance premiums in Gnomeregan before their little exodus. Be that as it may, he's consistently taken to perfecting his gadgetry regardless of the cost to others.\n\nHis ambition is admirable, but his methods are irredeemable. \n\nGo and see that his inventing days come to an end.", objectives = "Hunt down Senior Tinker Ozwold and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91216] = { title = "Prey: L-N-0R the Recycler (Hard)", description = "Do you know why they call her the Recycler, {name}? I don't. And given her history of \"disappearing\" shop assistants, I'm not really inclined to ask her.\n\nThat being said, watch your step. I understand that she likes to incorporate her victims into her gadgetry. We wouldn't want you becoming a pocket watch or some such thing.", objectives = "Hunt down L-N-0R the Recycler and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91217] = { title = "Prey: L-N-0R the Recycler (Nightmare)", description = "Do you know why they call her the Recycler, {name}? I don't. And given her history of \"disappearing\" shop assistants, I'm not really inclined to ask her.\n\nThat being said, watch your step. I understand that she likes to incorporate her victims into her gadgetry. We wouldn't want you becoming a pocket watch or some such thing.", objectives = "Hunt down L-N-0R the Recycler and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91218] = { title = "Prey: Mordril Shadowfell (Hard)", description = "The Void is a perfidious thing, like water. The wise keep it at a respectful distance, never dancing too close to the edge. The foolish dive in, and in so doing, drown.\n \nMordril is a danger to himself and everyone around him, so lost is he in his own obsession.\n\nSee to it that he no longer poses a threat to this realm.", objectives = "Hunt down Mordril Shadowfell and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91219] = { title = "Prey: Mordril Shadowfell (Nightmare)", description = "The Void is a perfidious thing, like water. The wise keep it at a respectful distance, never dancing too close to the edge. The foolish dive in, and in so doing, drown.\n \nMordril is a danger to himself and everyone around him, so lost is he in his own obsession.\n\nSee to it that he no longer poses a threat to this realm.", objectives = "Hunt down Mordril Shadowfell and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91220] = { title = "Prey: Deliah Gloomsong (Hard)", description = "In a previous life, Deliah Gloomsong was a prodigious student--truly a marvel of ambition, talent, and unrelenting curiosity. \n\nIt was the latter that got the best of her.\n\nPut an end to her murderous spree.", objectives = "Hunt down Deliah Gloomsong and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91221] = { title = "Prey: Deliah Gloomsong (Nightmare)", description = "In a previous life, Deliah Gloomsong was a prodigious student--truly a marvel of ambition, talent, and unrelenting curiosity. \n\nIt was the latter that got the best of her.\n\nPut an end to her murderous spree.", objectives = "Hunt down Deliah Gloomsong and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91222] = { title = "Prey: Phaseblade Talasha (Hard)", description = "Ethereals... they make my skin crawl. Esoteric. Unknowable. I don't trust anything I can't look in the eyes while it grovels before me.\n\nMy scouts report that a particularly dangerous ethereal is active in a nearby region. We would do well to nip this in the bud while we still can.", objectives = "Hunt down Phaseblade Talasha and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91223] = { title = "Prey: Phaseblade Talasha (Nightmare)", description = "Ethereals... they make my skin crawl. Esoteric. Unknowable. I don't trust anything I can't look in the eyes while it grovels before me.\n\nMy scouts report that a particularly dangerous ethereal is active in a nearby region. We would do well to nip this in the bud while we still can.", objectives = "Hunt down Phaseblade Talasha and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91224] = { title = "Prey: Nexus-Edge Hadim (Hard)", description = "Our activities are drawing unwanted attention. I have heard whispers that a powerful ethereal assassin is on my... on our trail. It would be very difficult indeed to defend our city as twin piles of bloody ribbons.\n\nGo out there and show this \"assassin\" the true art of the kill.", objectives = "Hunt down Nexus-Edge Hadim and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91225] = { title = "Prey: Nexus-Edge Hadim (Nightmare)", description = "Our activities are drawing unwanted attention. I have heard whispers that a powerful ethereal assassin is on my... on our trail. It would be very difficult indeed to defend our city as twin piles of bloody ribbons.\n\nGo out there and show this \"assassin\" the true art of the kill.", objectives = "Hunt down Nexus-Edge Hadim and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91226] = { title = "Prey: Jo'zolo the Breaker (Hard)", description = "Jo'zolo the Breaker is a troll who abides by his name. Long has he been the bane of our scouts, but no more! \n\nKill him. Feed his anguish to the defenses of our beloved city.", objectives = "Hunt down Jo'zolo the Breaker and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91227] = { title = "Prey: Jo'zolo the Breaker (Nightmare)", description = "Jo'zolo the Breaker is a troll who abides by his name. Long has he been the bane of our scouts, but no more! \n\nKill him. Feed his anguish to the defenses of our beloved city.", objectives = "Hunt down Jo'zolo the Breaker and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91228] = { title = "Prey: Zadu, Fist of Nalorakk (Hard)", description = "Our neighbors produce some of the most skilled hunters in all of Azeroth. It is a shame they are so difficult to reason with. \n \nThere is one named Zadu. Her anguish would make for a most excellent trophy...", objectives = "Hunt down Zadu, Fist of Nalorakk, and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91229] = { title = "Prey: Zadu, Fist of Nalorakk (Nightmare)", description = "Our neighbors produce some of the most skilled hunters in all of Azeroth. It is a shame they are so difficult to reason with.\n\nThere is one named Zadu. Her anguish would make for a most excellent trophy...", objectives = "Hunt down Zadu, Fist of Nalorakk, and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91230] = { title = "Prey: The Talon of Jan'alai (Hard)", description = "There is a powerful troll shaman who calls himself the Talon of Jan'alai. Long has he confounded our city's Farstriders, sowing confusion and death in his wake.\n\nSee to it that he joins the spirits he so ardently venerates.", objectives = "Hunt down The Talon of Jan'alai and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91231] = { title = "Prey: The Talon of Jan'alai (Nightmare)", description = "There is a powerful troll shaman who calls himself the Talon of Jan'alai. Long has he confounded our city's Farstriders, sowing confusion and death in his wake.\n\nSee to it that he joins the spirits he so ardently venerates.", objectives = "Hunt down The Talon of Jan'alai and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91232] = { title = "Prey: The Wing of Akil'zon (Hard)", description = "Do you smell that? There is death on the air. This can only mean one thing. The Wing of Akil'zon is near. Go out and slay her.\n\nOh, and be careful. She's responsible for more than one lost Farstrider patrol.", objectives = "Hunt down The Wing of Akil'zon and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91233] = { title = "Prey: The Wing of Akil'zon (Nightmare)", description = "Do you smell that? There is death on the air. This can only mean one thing. The Wing of Akil'zon is near. Go out and slay her.\n\nOh, and be careful. She's responsible for more than one lost Farstrider patrol.", objectives = "Hunt down The Wing of Akil'zon and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91234] = { title = "Prey: Ranger Swiftglade (Hard)", description = "It is a difficult thing, to hunt one of our own. Ranger Swiftglade is beyond redemption. His bloodlust could not be sated against our foes, and he has since turned his martial prowess upon his own people.\n\nEnd his sadistic killing spree and put his anguish to better use.", objectives = "Hunt down Ranger Swiftglade and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91235] = { title = "Prey: Ranger Swiftglade (Nightmare)", description = "It is a difficult thing, to hunt one of our own. Ranger Swiftglade is beyond redemption. His bloodlust could not be sated against our foes, and he has since turned his martial prowess upon his own people.\n\nEnd his sadistic killing spree and put his anguish to better use.", objectives = "Hunt down Ranger Swiftglade and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91236] = { title = "Prey: Lieutenant Blazewing (Hard)", description = "I do not know what to make of Lieutenant Blazewing. Her entire patrol disappeared during a reconnaissance mission into Zul'Aman. She was the sole survivor, but she returned with a fiery bloodlust and a complete disregard for the lives of others. \n\nWhether this is possession or sedition I am unsure, but she must be dealt with.", objectives = "Hunt down Lieutenant Blazewing and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91237] = { title = "Prey: Lieutenant Blazewing (Nightmare)", description = "I do not know what to make of Lieutenant Blazewing. Her entire patrol disappeared during a reconnaissance mission into Zul'Aman. She was the sole survivor, but she returned with a fiery bloodlust and a complete disregard for the lives of others. \n\nWhether this is possession or sedition I am unsure, but she must be dealt with.", objectives = "Hunt down Lieutenant Blazewing and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91238] = { title = "Prey: Petyoll the Razorleaf (Hard)", description = "Reports are coming in of shredded Farstriders adorned with petals and berries--entire patrols found strung up by razor-vines. There are more gruesome details, but they chafe even my... refined sensibilities. \n\nHunt whatever manner of creature is embarking on this horrific killing spree, and see to it that its anguish is added to our crystals.", objectives = "Hunt down Petyoll the Razorleaf and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91239] = { title = "Prey: Petyoll the Razorleaf (Nightmare)", description = "Reports are coming in of shredded Farstriders adorned with petals and berries--entire patrols found strung up by razor-vines. There are more gruesome details, but they chafe even my... refined sensibilities. \n\nHunt whatever manner of creature is embarking on this horrific killing spree, and see to it that its anguish is added to our crystals.", objectives = "Hunt down Petyoll the Razorleaf and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91240] = { title = "Prey: Lamyne of the Undercroft (Hard)", description = "Do you garden, {name}? I've been known to dabble. It seems the plants in our realm are becoming somewhat overbearing these days, sprouting legs and arms and running around murdering our brave soldiers. \n\nLet's give them a bit of a pruning, shall we?", objectives = "Hunt down Lamyne of the Undercroft and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91241] = { title = "Prey: Lamyne of the Undercroft (Nightmare)", description = "Do you garden, {name}? I've been known to dabble. It seems the plants in our realm are becoming somewhat overbearing these days, sprouting legs and arms and running around murdering our brave soldiers. \n\nLet's give them a bit of a pruning, shall we?", objectives = "Hunt down Lamyne of the Undercroft and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91242] = { title = "Prey: High Vindicator Vureem (Hard)", description = "High Vindicator Vureem is a victim of his own unyielding faith in the Light and the superiority it gives him. His crusade continues unabated and unresolved. He exists in a constant state of fury at the imperfectness of the world and those within it.\n\nIn the absence of total purity, Vureem sees only violence and the shadows of his own dogma. \n\nWhat say we put his worldview to the test?", objectives = "Hunt down High Vindicator Vureem and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91243] = { title = "Prey: Crusader Luxia Maxwell (Hard)", description = "We are not sure if Luxia Maxwell is a deserter or has simply decided to embark on her own personal crusade. Regardless, reports are coming in of her attacking both friend and foe alike, yelling aphorisms of purity and duty.\n\nShe has become a liability to the defense of Silvermoon. \n\nGo and harvest her anguish.", objectives = "Hunt down Crusader Luxia Maxwell and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91244] = { title = "Prey: Praetor Singularis (Hard)", description = "The domanaar...\n\n<Astalor shudders.>\n\nI do not profess to know much about them, other than their proclivity for subterfuge, guile, and the absolute destruction of anything that stands before them. Praetor Singularis is no exception. They have been confounding our forces at every turn.\n\nGo and put an end to their games.", objectives = "Hunt down Praetor Singularis and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91245] = { title = "Prey: Consul Nebulor (Hard)", description = "I have heard that there is one under Xal'atath's command who takes particular delight in dominating their foes. Whispers of a domanaar that taunts its victims with whispers and riddles before annihilating their mortal coil with void magic. \n \nConsul Nebulor is their name.\n\nGo and show them the limits of their power.", objectives = "Hunt down Consul Nebulor and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91246] = { title = "Prey: Executor Kaenius (Hard)", description = "The domanaar have a reputation for guile and cunning, but there are brutes among them: those who seek to dominate their victims through sheer power and force of will.\n\nExecutor Kaenius is one such domanaar.\n\nThey stalk the battlefield, singling out our strongest soldiers and viciously cutting them down.\n\nPut an end to their rampage.", objectives = "Hunt down Executor Kaenius and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91247] = { title = "Prey: Imperator Enigmalia (Hard)", description = "Imperator Enigmalia is personally responsible for the deaths of at least a dozen Farstriders. I say \"at least\" because this particular domanaar makes it somewhat difficult to identify the bodies, so utterly destroyed are they.\n\nGo and avenge our fallen soldiers.", objectives = "Hunt down Imperator Enigmalia and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91248] = { title = "Prey: Knight-Errant Bloodshatter (Hard)", description = "Death knights are unstable killing machines at the best of times. Knight-Errant Bloodshatter has forsaken any oath or promise that would ostensibly bind one of his kind to the bottom rungs of civilized society, and has gone completely rogue.\n\nHe is starting to become a liability.\n\nRecoup his anguish so that we can make the best of such an unfortunate situation.", objectives = "Hunt down Knight-Errant Bloodshatter and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91249] = { title = "Prey: Vylenna the Defector (Hard)", description = "Vylenna the Defector lives up to her name. After a recent engagement on the field of battle, she became so preoccupied with profaning the dead that she completely abandoned the duties ascribed to her.\n \nThen her dereliction turned violent.\n\nA veritable font of anguish if you ask me...", objectives = "Hunt down Vylenna the Defector and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91250] = { title = "Prey: Lost Theldrin (Hard)", description = "Those of us who succumbed to our base desire for mana were slowly weeded out of civil society, if they survived at all. Theldrin is one such example, only it is a testament to his cunning and will to live that he has made it as long as he has.\n\nHe accepts no aid, choosing instead to stalk careless students and idle Magisters. His sole obsession is the mana that others possess...\n\nSee to it that he never harms another elf again.", objectives = "Hunt down Lost Theldrin and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91251] = { title = "Prey: Neydra the Starving (Hard)", description = "Poor Neydra... I knew her, in a previous life. She was full of vitality. Full of ambition. Unfortunately, she let that ambition get the best of her. She grew too enamored with the raw power of the arcane. She became resentful of all other things. Of all other people...\n\nAnd now she is a murderous creature who beheads rats and attacks innocents in a desperate attempt to garner enough arcane energy to slake her unquenchable thirst.\n\nIt's funny, the paths life takes us...", objectives = "Hunt down Neydra the Starving and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91252] = { title = "Prey: Thornspeaker Edgath (Hard)", description = "This one presents a prickly problem indeed. Thornspeaker Edgath has made a name for himself by using his druidic powers not to preserve Azeroth, but to twist its strength both against his enemies and innocent bystanders alike. He has no regard for anything that is not a beast or growing in the ground.\n\nIt is time we clip this thorn.", objectives = "Hunt down Thornspeaker Edgath and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91253] = { title = "Prey: Thorn-Witch Liset (Hard)", description = "Thorn-Witch Liset is a curse upon civilization and a blight upon the land itself. She twists the very trees and beasts, communing with the dark, evil things that live on the very edges of the natural realm.\n\nI despise the natural realm.", objectives = "Hunt down Thorn-Witch Liset and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91254] = { title = "Prey: Grothoz, the Burning Shadow (Hard)", description = "The Twilight's Blade are an embarrassing band of mediocre cultists and uninspired conspirators. Grothoz is the brains of a particularly stupid cabal that has been active in a nearby region. \n\nAs his stupidity prevents him from using his whole brain, let us unlock his potential for him...", objectives = "Hunt down Grothoz, the Burning Shadow and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91255] = { title = "Prey: Dengzag, the Darkened Blaze (Hard)", description = "Do you know why the Twilight's Blade call Dengzag the \"Darkened Blaze?\" It is because they are stupid, small-minded, and utterly bereft of imagination. What a silly name indeed. \n\nI, however, am not small-minded. I have quite the prodigious mind, and it is currently intent on putting an end to Dengzag and whatever his tiny brain is up to. \n\nGet to it.", objectives = "Hunt down Dengzag, the Darkened Blaze and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91256] = { title = "Prey: High Vindicator Vureem (Nightmare)", description = "High Vindicator Vureem is a victim of his own unyielding faith in the Light and the superiority it gives him. His crusade continues unabated and unresolved. He exists in a constant state of fury at the imperfectness of the world and those within it.\n\nIn the absence of total purity, Vureem sees only violence and the shadows of his own dogma. \n\nWhat say we put his worldview to the test?", objectives = "Hunt down High Vindicator Vureem and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91257] = { title = "Prey: Crusader Luxia Maxwell (Nightmare)", description = "We are not sure if Luxia Maxwell is a deserter or has simply decided to embark on her own personal crusade. Regardless, reports are coming in of her attacking both friend and foe alike, yelling aphorisms of purity and duty.\n\nShe has become a liability to the defense of Silvermoon. \n\nGo and harvest her anguish.", objectives = "Hunt down Crusader Luxia Maxwell and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91258] = { title = "Prey: Praetor Singularis (Nightmare)", description = "The domanaar...\n\n<Astalor shudders.>\n\nI do not profess to know much about them, other than their proclivity for subterfuge, guile, and the absolute destruction of anything that stands before them. Praetor Singularis is no exception. They have been confounding our forces at every turn.\n\nGo and put an end to their games.", objectives = "Hunt down Praetor Singularis and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91259] = { title = "Prey: Consul Nebulor (Nightmare)", description = "I have heard that there is one under Xal'atath's command who takes particular delight in dominating their foes. Whispers of a domanaar that taunts its victims with whispers and riddles before annihilating their mortal coil with void magic.\n\nConsul Nebulor is their name.\n\nGo and show them the limits of their power.", objectives = "Hunt down Consul Nebulor and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91260] = { title = "Prey: Executor Kaenius (Nightmare)", description = "The domanaar have a reputation for guile and cunning, but there are brutes among them: those who seek to dominate their victims through sheer power and force of will.\n\nExecutor Kaenius is one such domanaar.\n\nThey stalk the battlefield, singling out our strongest soldiers and viciously cutting them down.\n\nPut an end to their rampage.", objectives = "Hunt down Executor Kaenius and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91261] = { title = "Prey: Imperator Enigmalia (Nightmare)", description = "Imperator Enigmalia is personally responsible for the deaths of at least a dozen Farstriders. I say \"at least\" because this particular domanaar makes it somewhat difficult to identify the bodies, so utterly destroyed are they.\n\nGo and avenge our fallen soldiers.", objectives = "Hunt down Imperator Enigmalia and slay them.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91262] = { title = "Prey: Knight-Errant Bloodshatter (Nightmare)", description = "Death knights are unstable killing machines at the best of times. Knight-Errant Bloodshatter has forsaken any oath or promise that would ostensibly bind one of his kind to the bottom rungs of civilized society, and has gone completely rogue.\n \nHe is starting to become a liability. \n\nRecoup his anguish so that we can make the best of such an unfortunate situation.", objectives = "Hunt down Knight-Errant Bloodshatter and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91263] = { title = "Prey: Vylenna the Defector (Nightmare)", description = "Vylenna the Defector lives up to her name. After a recent engagement on the field of battle, she became so preoccupied with profaning the dead that she completely abandoned the duties ascribed to her.\n\nThen her dereliction turned violent.\n\nA veritable font of anguish if you ask me...", objectives = "Hunt down Vylenna the Defector and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91264] = { title = "Prey: Lost Theldrin (Nightmare)", description = "Those of us who succumbed to our base desire for mana were slowly weeded out of civil society, if they survived at all. Theldrin is one such example, only it is a testament to his cunning and will to live that he has made it as long as he has.\n\nHe accepts no aid, choosing instead to stalk careless students and idle Magisters. His sole obsession is the mana that others possess...\n\nSee to it that he never harms another elf again.", objectives = "Hunt down Lost Theldrin and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91265] = { title = "Prey: Neydra the Starving (Nightmare)", description = "Poor Neydra... I knew her, in a previous life. She was full of vitality. Full of ambition. Unfortunately, she let that ambition get the best of her. She grew too enamored with the raw power of the arcane. She became resentful of all other things. Of all other people...\n\nAnd now she is a murderous creature who beheads rats and attacks innocents in a desperate attempt to garner enough arcane energy to slake her unquenchable thirst.\n\nIt's funny, the paths life takes us...", objectives = "Hunt down Neydra the Starving and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91266] = { title = "Prey: Thornspeaker Edgath (Nightmare)", description = "This one presents a prickly problem indeed. Thornspeaker Edgath has made a name for himself by using his druidic powers not to preserve Azeroth, but to twist its strength both against his enemies and innocent bystanders alike. He has no regard for anything that is not a beast or growing in the ground.\n\nIt is time we clip this thorn.", objectives = "Hunt down Thornspeaker Edgath and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91267] = { title = "Prey: Thorn-Witch Liset (Nightmare)", description = "Thorn-Witch Liset is a curse upon civilization and a blight upon the land itself. She twists the very trees and beasts, communing with the dark, evil things that live on the very edges of the natural realm.\n\nI despise the natural realm.", objectives = "Hunt down Thorn-Witch Liset and slay her.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91268] = { title = "Prey: Grothoz, the Burning Shadow (Nightmare)", description = "The Twilight's Blade are an embarrassing band of mediocre cultists and uninspired conspirators. Grothoz is the brains of a particularly stupid cabal that has been active in a nearby region. \n\nAs his stupidity prevents him from using his whole brain, let us unlock his potential for him...", objectives = "Hunt down Grothoz, the Burning Shadow and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91269] = { title = "Prey: Dengzag, the Darkened Blaze (Nightmare)", description = "Do you know why the Twilight's Blade call Dengzag the \"Darkened Blaze?\" It is because they are stupid, small-minded, and utterly bereft of imagination. What a silly name indeed. \n\nI, however, am not small-minded. I have quite the prodigious mind, and it is currently intent on putting an end to Dengzag and whatever his tiny brain is up to. \n\nGet to it.", objectives = "Hunt down Dengzag, the Darkened Blaze and slay him.\n\nHunt Progress is made by completing Prey activities, World Quests, rares, and treasures in your selected zone." }
WordHunterWoW_QuestEN[91270] = { title = "The Most Important Thing", description = "We will be strong for the Pit!\n\nBut Boletus right. Another thing needed. Must have great name.\n\nBest teams all have good name. Fungus Force. Spore Storm. Cap Clash. And champions, Glow Guard!\n\nAll good names.\n\nWe need amazing name. Best name. So will be best team.\n\nYou help choose?", objectives = "Speak to each of your teammates to choose a name.", progress = "Find best name?", completion = "Fungal Fell...owship, ok. Now we ready.\n\nWill run into pit together, shout the Fungal Fello...sip, eh...\n\nCrowd will cheer, then will be new champions!" }
WordHunterWoW_QuestEN[91271] = { title = "A Fish!", description = "There is a deliciously delectable dish that I am dying to share with my guests. We start with just the right fish, then chop it up, drop it in a blend of citrus and our special savory seasonings, and let it bask in the glorious flavors.\n\nIn the shake of a tail feather, it becomes a magical delight for the senses!\n\nWe are the talk of the town, you know. Could you please procure for us the perfect fish?", objectives = "Catch the best fish for the dish.", progress = "I have a great feeling about this one!", completion = "Excellent work, <name>! You have procured a perfectly, pleasingly, plumply proportioned pescatarian prize!\n\nJoyous day!" }
WordHunterWoW_QuestEN[91274] = { title = "Severing the Void", description = "The High Exarch has formed an impressive defensive line. It will hold the Devouring Host's current numbers. But I can see void pylons behind the lines. Those will call forth more Devouring Host and overwhelm the Vanguard of Light.\n\nTheir power is too dangerous for us to destroy directly, but if we can re-activate the sentinels that fell in the initial assault, they could destroy the pylons for us.", objectives = "Activate 5 Quel'Danas Sentinels to destroy the Void Pylons.", progress = "We need to activate all the sentinels if we want to destroy the void pylons.", completion = "With those void pylons destroyed, the Devouring Host has weakened. We may have a chance of winning this." }
WordHunterWoW_QuestEN[91281] = { title = "Midnight", description = "Locate one of the images of Lady Liadrin that have appeared across Azeroth.", objectives = "Travel to the nearest Image of Lady Liadrin.", completion = "I am glad you came, <name>. We need your help urgently." }
WordHunterWoW_QuestEN[91283] = { title = "Greedy Emissary", description = "", objectives = "" }
WordHunterWoW_QuestEN[91284] = { title = "A Path Not Yet Chosen", description = "I'm trying to figure out what career path to follow, but I keep second-guessing myself. The Farstriders, the Blood Knights, the Magisters... they all seem so incredible that I can't decide.\n\nI was hoping if I spoke to each and earned a recommendation, I might finally understand where I'm meant to be. Would you help me?", objectives = "Collect Recommendations from the Farstrider, Blood Knight, and Magister trainers.", progress = "I really hope I find where I belong...", completion = "Wow... I can't believe I actually got all three recommendations. They all said such kind things, but now I feel even more torn than before!\n\nDo you think... perhaps you could help me choose?" }
WordHunterWoW_QuestEN[91288] = { title = "A Test of the Hunt", description = "So, you want a Farstrider recommendation? We don't hand those out like festival ribbons.\n\nIf you want to earn it, then you'll need to do what every other recruit does. Bring me lynx pelts, clean and proper.\n\nNo shortcuts, no excuses. Let's see if you've got the spine for it.", objectives = "Gather 8 Invasive Lynx Pelts in the Sunstrider Isle.", progress = "Have you gotten those pelts yet or are you quitting already?", completion = "Well now, look at that. Clean cuts, no mess... maybe the kid's got more fire than I thought.\n\nHere, take this recommendation. Tell them a Farstrider never forgets who earns their place--and to keep their aim sharp. We'll be watching." }
WordHunterWoW_QuestEN[91291] = { title = "A Test of Blood", description = "Ah, you seek a Blood Knight's recommendation, do you? In that case, you'll need to prove your worth... against me. \n\nOnly those with true strength and honor may join our ranks! Prepare yourself. This won't be a simple challenge, but if you can best me, I'll gladly offer my recommendation!", objectives = "Defeat Jesthenis Sunstriker in the Sunstrider Isle.", progress = "Well, what do you think?", completion = "Impressive! You've got more in you than I expected.\n\nYou've proven your strength, honor, and determination--qualities every Blood Knight must possess.\n\nTake this recommendation and wear it with pride. The order is always looking for those who are worthy." }
WordHunterWoW_QuestEN[91292] = { title = "A Test of the Arcane", description = "Ah, you seek a recommendation from a Magister, do you? Very well... but first, you must prove your understanding of the arcane.\n\nGo to the nearby crystals we have for training, extract their energy, and channel it into this staff. Show me that you can harness the arcane, and I will see you worthy of my recommendation.\n\nShould you fail, don't bother returning. My time is too valuable for such trivial matters.", objectives = "Charge the Arcane Transfer Staff 4 times in Sunstrider Isle.", progress = "Well? Is the staff charged, or are you wasting both our lives?", completion = "Hmm, it seems you have a bit more talent than I anticipated.\n\nThis staff is properly charged. Well done, though I'm sure you barely broke a sweat.\n\nTake this recommendation, and remember--the arcane demands respect, not just power." }
WordHunterWoW_QuestEN[91301] = { title = "How to Train Your Protege", description = "I did everything they asked--the trials, the lessons--and they all said I did well... but I still don't know where I truly belong.\n\nEach path felt right in its own way, and now my heart feels pulled in three directions.\n\nPlease... could you help me decide?", objectives = "Turn in the chosen recommendation to Instructor Thalendir in Silvermoon City.", completion = "Ah... so the boy has chosen at last. He has heart--too much perhaps.\n\nYes. This will be recorded and honored. You've done more than deliver a message--you've helped shape a life. Thank you." }
WordHunterWoW_QuestEN[91302] = { title = "Abundance: Abundant Grove", description = "", objectives = "" }
WordHunterWoW_QuestEN[91314] = { title = "Untethered Potential", description = "{class}--I heard you have explored Untethered Space? That place is soaked with pristine void energy. I would like to explore it myself, but the last who have ventured into were consumed by the Void.\n\nI need help with my research. There are Phase-Lost creatures in the Voidscar Cavern that I could use to examine their essence. If you could collect that for me, I would be grateful. \n\nGo carefully.", objectives = "Collect 5 Phase-Altered essence in Untethered Space.", progress = "Were you able to collect the Phase-Altered essence?", completion = "This will provide a lot to forward my research on Untethered Space. I thank you.\n\nI can't imagine what discoveries we can begin to unravel about K'aresh." }
WordHunterWoW_QuestEN[91328] = { title = "Secret Ingredients", description = "Our gregarious guests have partaken so much from our stores that we are running dangerously low of our special Solaarian sintalia.\n\nThe rich taste of belanise, with its intoxicating scent, contrasts perfectly with the sharp tartness of the local berries. Carefully prepared then soaked in our special blend of spirits, then served--it's to die for!\n\nJust between us, if the berries are not handled just right, the infusion can be quite deadly. Otherwise... delicious, invigorating, purifying, glorious!", objectives = "Collect 6 Belanise Blossoms and 5 Sinara Berries for the Solaarian Sintalia.", progress = "Are you gathering carefully?", completion = "Magic! Perfection! You could not be more skilled if I had wished you into existence.\n\nThat is an interesting thought. Could I have?" }
WordHunterWoW_QuestEN[91339] = { title = "Smothered in the Crib", description = "I summoned my first imp in a dirty, haze-filled lounge beneath Murder Row after a dozen failed attempts. Each time, I reached further for what made so-called greater powers submit to mortals. I finally managed it after wetting my hands with the hot blood of a young rabbit. Bloodthistle never satisfied me again.\n\nI have matured my technique since then. Seek the whelps of these beasts. Siphon their energy into my reliquary of darkness. From their sacrifice, we will draw the power to defeat Kalgorg.", objectives = "Drain 9 juvenile wildlife with the Reliquary of Darkness.", completion = "This too is the natural order of things." }
WordHunterWoW_QuestEN[91340] = { title = "For Violence's Sake", description = "Like many warlocks, I bind my demons with terms of a contract. I should have realized the Void and violence of this world could affect the rules I took for granted. Kalgorg used that power to break its bindings and end our arrangement. \n\nWhen we confront Kalgorg, the scent of blood and violence must be upon us. Slay the beasts you find to demonstrate to Kalgorg we are willing to do the same to it. Control over the Void is found and lost within the blink of an eye.", objectives = "Kill wildlife on the surface of the Den of Predaxas.", completion = "<Lucia looks you over and then rewards you with a cruel smile.>\n\nSplendid. You are as capable as you look." }
WordHunterWoW_QuestEN[91341] = { title = "Unlimited", description = "Now, we descend. The Void energy below is unlike any I've felt before, as if gravity itself yields to the Void. Once you enter the cave, its influence will be upon you.\n\nKalgorg has already slain and claimed power from the creatures within. Their violent deaths have left behind some kind of cursed terrain, but we must proceed and claim the power within. Fill the reliquary to the brim. \n\nI know not what to expect from my voidwalker. We will need all the power we can manage.", objectives = "Gather Void Power within the Lair of Predaxas.", progress = "The trail of carnage it left behind... I'm almost proud.", completion = "Kalgorg waits before us. Now we spend the power you've been collecting reclaim it." }
WordHunterWoW_QuestEN[91342] = { title = "If You Want It Done Right", description = "With all the problems facing Eversong, the Farstriders have their hands full!\n\nI'm a capable arcanist. I've always admired the Farstriders--why not lend my talents to their cause? They do so much work by hand, when a bit of magic would allow them so much more time for adventuring!\n\nAlas, my enchanted broom idea has not quite gone as I'd hoped. They're so ornery, they end up attacking the recruits instead of cleaning!\n\nPerhaps this is a problem for elbow grease after all.", objectives = "Slay 8 Ornery Sweepers.", progress = "Captain Dawnrunner warned me about trying to solve all my problems with magic... Clearly I have much yet to learn.", completion = "The sweeping will still need to get done, but at least now no one will be attacked." }
WordHunterWoW_QuestEN[91343] = { title = "Ambition's Reward", description = "You have filled the reliquary with power I can draw on. Now, we reap the reward of our preparations.\n\nKalgorg waits just ahead, draining the beast that once made this cave its lair. Weaken Kalgorg, and I will bind it as I first did years ago.", objectives = "Subdue Kalgorg the Unshackled.", completion = "Kalgorg consumed much of the Void energy within that cave, which means its influence is less likely to overwhelm my kin. I suppose some good was done.\n\nI must pay Kalgorg the slightest compliment. Were I a subdued void beast, I'd also try to escape. For that, it has my respect.\n\n<Lucia turns to Kalgorg with a sharp smile.>" }
WordHunterWoW_QuestEN[91345] = { title = "To the North Tower", description = "Ranger Valsarin is a chef at Farstrider Hold. He's decent in a kitchen, but his passion is field cooking.\n\nThere was a time when you could wander any path in Eversong and find the ingredients for a good meal. A Farstrider's dream! With enough hard work, we can help the forest recover, and it starts with rehabilitating the soil.\n\nMeet Valsarin at the North Tower and he can tell you more.", objectives = "Meet Ranger Valsarin at the North Tower.", completion = "Hope you like getting your hands dirty." }
WordHunterWoW_QuestEN[91346] = { title = "Supplicants to the Goddess", description = "We have long tended to the roots with the help of the creatures who live and grow here. Think of it as a symbiotic relationship from which we, the creatures, and the roots all benefit. That said, my partner Riverscale isn't contributing very much lately!\n\nPlease help me find a way to motivate him again.\n\nFirst, you must cleanse off the essence of the outside. Cleanse yourself in the waters of Har'kuai.", objectives = "Cleanse yourself in the Waters of Har'kuai.", completion = "This may seem inconsequential, but it's all a part of the process." }
WordHunterWoW_QuestEN[91347] = { title = "Strider Stampede", description = "It's hard to believe this used to be the Dead Scar.\n\nUp here, close to the city, the land has almost completely recovered. Which is good, because we've got a lot of mouths to feed.\n\nHawkstriders are the perfect helpers for preparing the soil. Their tough claws can easily spread seeds and squash bugs!\n\nMeet me down in the Tranquil Repose and I'll saddle one up for you.", objectives = "Mount up the Saddled Hawkstrider and prepare the Tranquil Repose for gardening.", progress = "Nothing like planting seeds.", completion = "I don't know what to make of those big blooms... but whatever we're doing, the land seems pleased." }
WordHunterWoW_QuestEN[91348] = { title = "See a Mana 'bout a Wyrm", description = "Mana wyrms may not be as glamorous as lynxes or hawkstriders, but they're crucial to keeping magic flowing through the forest.\n\nThey congregate on the ley lines to molt, but sometimes they get a little agitated. And we have to help them out! Aggressively!\n\nI've set up some ley channels to get things started. Find wyrms that look like they could use a little help, and beat them up until they shed their arcane carapace. Don't worry--all that mana returns to the forest eventually!", objectives = "Aggressively assist 8 Agitated Wyrms with their molting.", progress = "Don't worry! They bounce right back.", completion = "Another successful molt... We'll be out here in a few weeks to do it all again!" }
WordHunterWoW_QuestEN[91349] = { title = "The Dark Part of the Woods", description = "Much of the forest has recovered, but to the south... Everything that Eversong has faced--the Scourge, the fel, and now the Twilight's Blade--all that magic leaches into the soil. It builds up in the creatures until they're completely overwhelmed...\n\nMy instruments can detect corruption in these animals. We can cull the ones that are too far gone and save the ones that aren't. It isn't fun... but it's for the good of Eversong!", objectives = "Test 8 creatures for corruption, and deal with the consequences.", progress = "It's hard work, but it will bring peace eventually.", completion = "These poor cubs... They survived only by the grace of that strange magic!\n\nI know better than to believe in the old tales... but what else could it be?" }
WordHunterWoW_QuestEN[91350] = { title = "A Real Assignment", description = "Captain Dawnrunner was supposed to check on the Enclave and then meet us here. She's as capable a ranger as any! It's a bad sign if she's been detained.\n\nFarstrider Enclave is usually where they do wilderness training. With all the trouble however, everyone's been dispatched elsewhere. She could be up there alone, in serious danger!\n\nThere's no time to lose. I'm going to save my Captain and prove myself as a Farstrider!", objectives = "Find Captain Dawnrunner at Farstrider Enclave.", completion = "This is what happens when there's no one around to sweep up!\n\nEveryone wants to adventure, but no one wants to sweep." }
WordHunterWoW_QuestEN[91359] = { title = "Fungal Lashers B Gone", description = "We are blessed to live in Harandar, but this is also our responsibility. The roots of the World Trees wind through these lands. We tend them, and they thrive. That is why it is so important for Riverscale to be back on duty.\n\nWe need to keep these grounds clear of these fungal lashers before they leach off the roots. As a plus, Riverscale really loves lasher fronds. Can you find and bring some back for him?", objectives = "Collect 6 Harmonious Fronds in the outskirts of Har'kuai.", progress = "It's important that we keep the lashers from sapping important nutrients from the World Tree.\n\n...and I like spoiling my obstinate little boy.", completion = "I wish that I didn't have the laziest helper in the history of helpers, but such is life!\n\nIf his favorite treats won't get him up, nothing will." }
WordHunterWoW_QuestEN[91360] = { title = "Weeding Out the Unwanted", description = "The roots of the World Trees are infused with both nutrients and the magic of Harandar. As the large vessels that they are, they will draw to them unwanted fauna and flora. Some of them are harmless, but we want to keep the roots clear.\n\nHaranir can often be allergic to the green weeds that flourish beside the roots of the World Trees. If you rip them out by the root, you would be saving us a lot of time--and hives!", objectives = "Pull 8 Allergenic Weeds in the outskirts of Har'kuai.", completion = "You're a weed-pulling, no-rash juggernaut!" }
WordHunterWoW_QuestEN[91361] = { title = "Back on Duty?", description = "Finally! I knew the little guy could do it.\n\nNo, that is a bald-faced lie. If this grovecrawler could somehow find a way back into his cocoon, he would already be there.\n\n<Cyenna sighs.>\n\nHis second favorite treat is the potatoad. If that doesn't work, his third favorite treat is the petalwing. That should get him back onto his mite-hunting duties.\n\n...I have the backbone of a wet frond.", objectives = "Help Riverscale gain his confidence by killing 8 Potatoads and Petalwings by the outskirts of Har'kuai.", completion = "I knew you could do it, Riverscale! Who's a good grovecrawler? Who's the best crawler of them all?\n\nWho's a big strong grovecrawler who knows how to teach strangers how to care for World Trees?\n\n<Cyenna looks up at you.>\n\nYou knocked him out of his laziness, <name>. I can't thank you enough for your help." }
WordHunterWoW_QuestEN[91363] = { title = "Harvest of Darkness", description = "You... make yourself useful.\n\nAs a master of terrible beasts, it is my job to mold these hatchlings into dreaded beasts. I pit them against each other and they grow ever more violent.\n\nBut the elves here insist that I will yield better results with just a bit of... tender loving care. Let us put this to the test.\n\nThis runt is Fidoficus. You will show him tenderness and affection, and then we will see how ferocious he becomes.\n\nCollect some delicious dietary treats for him and return to me.", objectives = "Collect 10 Void-Infused Morsels and 6 Glaring Glowcaps outside of the Howling Ridge.", progress = "These ingredients will make for a highly nutritious and equally delectable meal.", completion = "Fidoficus will be renowned for his ferocity.\n\nI can see the violence growing in him.\n\nOne day, he will be a worthy pet for a domanaar such as myself." }
WordHunterWoW_QuestEN[91364] = { title = "[DNT] QUEST NOT USED", description = "In order for Fidoficus to become a truly menacing force of destructive power, he needs a strict diet of macro-nutrients. \n\nWe Domanaar have no need for such corporeal sustenance. And therefore, I am not familiar with the process of cooking. \n\nTake the ingredients you've gathered and create something nourishing. \n\nAnd tasty. Not that I'd care. <want to hit beats where the Dom lets slip that it cares for the creature, at least a little>", objectives = "" }
WordHunterWoW_QuestEN[91375] = { title = "The Silence at Fungara Village", description = "Fungara Village has been silent for some time now.\n\nWe've largely been occupied with the Lightbloom and the threat it presents, so we haven't had time to check in on the fungarians to the east. Usually, they are rowdy yet manageable... but it's rare that they go completely silent.\n\nI am going to investigate. If you wish to prove yourself an ally, you would do well to join me.", objectives = "Seek Ghikal outside of Fungara Village in Harandar.", completion = "Normally, I would refuse the intervention of an outsider without a second thought... but given the situation, perhaps you can be of some help." }
WordHunterWoW_QuestEN[91376] = { title = "Little Monsters", description = "When I sent a request for aid from Har'alnor, I did not expect them to send me an outsider. No matter.\n\nThe denizens of Fungara Village have gone quiet. Normally, I would be thrilled: they're horribly screechy. But the way they are shambling about... it is like they have forgotten that they yet live.\n\n<Ghikal shudders.>\n\nI tried to get close, but they attacked me on sight.\n\nI will need samples of their flesh. Go and bring them to me, so I can see what has happened here.", objectives = "Collect 10 samples of Strange Mycelium from the former denizens of Fungara Village.", progress = "I do not know what is going on, but to err on the side of caution... do not let them bite you, hrm? Whatever plagues them may be infectious.", completion = "Goddess forfend. This is not fungarian flesh at all.\n\nWhat ARE they?" }
WordHunterWoW_QuestEN[91377] = { title = "Spawn of the Dead", description = "It is obvious that something terrible has happened in the village. I can see the corpses of their largest specimens strewn across the southern reaches from here, but something is off about them too. Fungarians don't usually just leave the corpses of their kin lying about.\n\nAnd though I am watching from afar, I swear that some of them are... twitching.\n\nInvestigate. Find out what you can, and report back to me.", objectives = "Investigate 5 Blooming Corpses in Fungara Village.", completion = "This is so much worse than I thought.\n\nWe have to find the source of this and destroy it before it infects something bigger and more dangerous than a fungarian." }
WordHunterWoW_QuestEN[91378] = { title = "You Are Legend", description = "Whatever these things are, they're not fungarians. Not anymore. \n\nHar'alnor has enough to worry about with the Lightbloom as it is. It cannot afford to be trapped between its forces and these... things.\n\nDo what must be done. Destroy as many of them as you can.", objectives = "Kill 15 Decanimated fungarians in the northern reaches of Fungara Village.", progress = "Do not feel regret. These things are not alive anymore. Not in any way that matters.", completion = "You are quite the accomplished slayer of aberrations. Perhaps you should consider a vocation in monster-hunting." }
WordHunterWoW_QuestEN[91379] = { title = "Decayed Land", description = "As far as I can tell, these fungarians are all already dead. Something is animating their corpses from within, like puppets attached to unseen vines.\n\nThis fungal matter that's infesting them must be coming from somewhere... and judging from the size of the ones further north, we'll find plenty of it there. Find it, get rid of it, but for Aln'hara's sake don't breathe it in.", objectives = "Destroy 8 growths of Fruiting Mycelium in Fungara Village.", completion = "We've culled the worst of the growths to the north... but there are smaller ones already beginning to sprout. Where are they coming from?\n\nThere must be a source, and we'll have to find it if we mean to solve this thing." }
WordHunterWoW_QuestEN[91380] = { title = "Belly of the Beast", description = "I normally raise my beasts on a diet of raw, bloody carcasses and souls ripped asunder by the Void.\n\nBut we shall try your mortal ways.\n\nI hear you... cook? And that makes the treat better?\n\nDo this. Then, take him on a walk around the Howling Ridge. Even I know exercise is good for digestion.\n\nOnly the most ferocious of creatures is worthy of serving me. I hope neither you nor Fido disappoint me.", objectives = "Feed and walk Fidoficus around the Howling Ridge to promote its growth and savagery.", completion = "Is the beast's savagery growing?\n\nI'm sure I will begin to hear of his violence from those around the Howling Ridge." }
WordHunterWoW_QuestEN[91381] = { title = "Reticent Evil", description = "I do not understand. We've searched high and low, north and south. Everywhere we go, we find animated corpses and small fruiting fungus, but where is the central body? Where is--\n\nOh, goddess. Of course.\n\nThe water, {class}. Check the water.", objectives = "Destroy the Agericus Decanimatus.", completion = "It is done, then.\n\nYou did well to survive untainted. The wilds are a dangerous place, and survival is never a guarantee.\n\nNow go. I must remain and ensure that these abominations cannot spread any further." }
WordHunterWoW_QuestEN[91382] = { title = "Mighty and Superior", description = "The beast is fed and exercised. Imagine, mortal... one day his maw will grow to fit you inside it a thousand times over. \n\nNow, we will test his potential for true violence. \n\nThere is a beast that has laid claim to a den south of the Howling Ridge. \n\nFidoficus trusts you now. Go with him and bear witness to his might.", objectives = "Bear witness to Fidoficus's savagery as it slays Den-Gorger Zitoc.", progress = "Fidoficus has grown fearsome, and perhaps you have claim to some of his growth.", completion = "Fidoficus will grow so terribly large, that it is he who will be walking you. \n\nOnly then will he be worthy of joining me as my attack behemoth." }
WordHunterWoW_QuestEN[91383] = { title = "Tidy Up", description = "Captain Dawnrunner is fine, thank the sun. The only danger was... we didn't keep up on our chores.\n\nIt's not heroic, it's not romantic, but we can't go on with Farstrider Enclave in this state. The rangers here are overwhelmed. We can all pitch in to help them get it cleaned up again.\n\nI can't believe it all comes back to sweeping. That's what being a Farstrider is really about.", objectives = "Clear out 5 Messy Nests and sweep up 5 Dusty Webs.", completion = "My rangers are earning their keep today, that's for certain." }
WordHunterWoW_QuestEN[91384] = { title = "Recovery Mission", description = "We've been deploying Farstriders across the forest to fight the Amani, the Lightbloom, the Void... but for all our heroics, there's no one left to tend to the wildlife! Or maintain the building! Or keep track of supplies!\n\nAnd now our beloved Enclave looks like a hawkstrider pen. I've had enough!\n\nI may not be able to help, but I trust you all can gather anything that was taken and get this place looking respectable again.", objectives = "Retrieve 12 Scattered Supplies from around Farstrider Enclave.", progress = "If we want to be of any use to the rest of Eversong, first we must pick up after ourselves.", completion = "This is a good start. All it takes is a handful of us putting in a little effort." }
WordHunterWoW_QuestEN[91385] = { title = "A Ranger's Spirit", description = "Taemin has proved himself as capable as any Farstrider today. But I'm afraid he might not see it that way.\n\nHe came to us with such lofty ideas about the rangers--all those swashbuckling adventure stories, all the romantic old legends. But at the end of the day, being a ranger is mostly... chores. Difficult, boring, important chores.\n\nWhy don't you go talk to him, and make sure he's not too disappointed?", objectives = "Find Recruit Taemin.", progress = "The beauty of the forest? It never gets old.", completion = "The legends are real... Eversong must be pleased with us!" }
WordHunterWoW_QuestEN[91386] = { title = "Mad to Measure", description = "These... tourists! These uncultured, ungrateful slobs!\n\nThis Vanguard of Light has brought a lot of business to Silvermoon, to be certain. But none of them actually appreciate what Thalassian craftsmanship means. They have no respect for the elven arts--they just want shiny, glittery souvenirs!\n\nI am no spring runner dancing for their amusement... but I can hardly turn them away, can I? Perhaps an assistant would make this atrocious task easier.", objectives = "Assist Solwin Brightstitch with making clothes for Pushy Paladins.", progress = "If only a single soul among these brutes showed any appreciation... alas, it seems even this small ask is too great.", completion = "All right... but only because I'm curious about the craftsmanship.\n\nIt'll take more than a little politeness to change my mind about these pernicious paladins." }
WordHunterWoW_QuestEN[91388] = { title = "Uncommon Threads", description = "Our patron--Gaari, I suppose--should count himself lucky. These mana wyrms produce the finest silk in Eversong. I know Magisters who would kill to have a robe trimmed in this, and yet here we are, using it for a mending job. Ah well.\n\nOnce the wyrms have eaten their fill of arcane energy, you can siphon the silk from them onto these bobbins.\n\nIf they are reluctant to release their silk, you may have to, ah... beat it out of them. But I've been assured it's entirely ethical.", objectives = "Siphon 8 Full Bobbins of Manasilk from weakened wyrms in the North Sanctum.", progress = "This is the easy part, of course.", completion = "Ah... beautiful, glittering manasilk. So ripe with potential." }
WordHunterWoW_QuestEN[91389] = { title = "Clothes Make the Man", description = "It is not merely the material that makes an arcanoweave cloak so fine, but the weaving process itself.\n\nTo mend one, particularly one that has built up so much history and latent arcane energy... I am about to embark on a very dangerous bit of tailoring indeed. Finally, a real testament to my skills.\n\nI am excited. I hope nothing explodes. Meet me inside when you're prepared.", objectives = "Meet Solwin inside, then fend off any manifestations as he mends the cloak.", completion = "It is a thing of beauty... I am glad to know it is in the hands of someone who loves it so." }
WordHunterWoW_QuestEN[91390] = { title = "Special Assignment: What Remains of a Temple Broken", description = "", objectives = "" }
WordHunterWoW_QuestEN[91391] = { title = "Still Scouting", description = "When the Alliance originally fought the Horde here, Kurdran served as a scout. He's still an excellent one. He took his gryphon to Blackrock Mountain to see what kind of forces we may be dealing with there.\n\nMeet up with him and see what kind of trouble you can cause.", objectives = "Meet Kurdran at Blackrock Mountain.", completion = "Arator, <name>--thanks fer coming. Plenty o' Dark Horde in there." }
WordHunterWoW_QuestEN[91392] = { title = "Greedy Emissary", description = "", objectives = "" }
WordHunterWoW_QuestEN[91398] = { title = "Tomes of Terror", description = "Knowledge is power, and de ogres been reading.\n\nBring me dey tomes so dey never grow dis powah again.", objectives = "Kill ogres in Atal'Kaldan and collect 4 tomes.", progress = "Get me de tomes.", completion = "Thank ya. Dese are going straight into de fire." }
WordHunterWoW_QuestEN[91399] = { title = "Ashes of the Void", description = "De void elementals have one use.\n\nDe dust dey drop is useful for shadow magic rituals.\n\nCollect some for our tribe.", objectives = "Kill void elementals and collect their ashes.", progress = "Don't worry, we been doin' dese rituals for centuries.", completion = "Our hunters gonna make good use of de powder. Thank ya." }
WordHunterWoW_QuestEN[91400] = { title = "Blades of the Fallen", description = "After de battle we left a lot of our weapons behind.\n\nPlease go collect dem so de Twilight's Blade doesn't get dem.", objectives = "Collect 12 Amani weapons from Atal'Kaldan.", completion = "Thanks for collecting dem. Now our foes won't get de advantage of fine Amani crafting." }
WordHunterWoW_QuestEN[91401] = { title = "Dead by Dusk", description = "De Twilight's Blade cultists have de audacity to try and take back our temple. Kill de peons and bring me their femurs.", objectives = "Collect 20 femurs from Twilight's Blade cultists in Atal'Kaldan.", progress = "Why femurs? None of ya business.", completion = "I got a plan for de bones. Thanks." }
WordHunterWoW_QuestEN[91402] = { title = "Ultra Deadly Ultradon", description = "I saw some of de void elementals doing a sketchy ritual in de center of the battlefield. It looked like dey were summoning some void creatures.\n\nMake sure whatever dey summon is dealt with.", objectives = "Kill the Eminent Ultradon in the center of Atal'Kaldan.", completion = "Never seen one of dem before and hope I don't see dem again. Nicely done." }
WordHunterWoW_QuestEN[91403] = { title = "Probable Paralytic", description = "Halazzi says dat de Vilebranch have made a new venom dat para... parliz--makes its victims not move--so they can drag them off to be sacrificed. He says it's frog venom.\n\nI said that doesn't make sense. Frogs are poison, right? Halazzi said frogs are normally poisonous, not venomous. But these have sharp horn bits on them, so maybe they have venom! I didn't know frogs could have venom, did you?\n\nLet's find out if these do--then de Witherbark can make an anti-venom!", objectives = "Collect 8 Venomous Horns from Horned Frogs.", progress = "Halazzi says venomous is when dey bite or stab you, and poisonous is when you bite or eat dem! Isn't dat interestin'?", completion = "Look at all de samples you found! De chief will know who can make anti-venom for sure." }
WordHunterWoW_QuestEN[91404] = { title = "A Most Vile Venom", description = "De Vilebranch are cookin' up more bad things. You should go to de source and make dem stop!\n\nHalazzi has smelled their venom-mixin' place someplace to de southeast, and he thinks it's more den just frog venom.\n\n...Oh, Halazzi also said to bring back some kind of huge fang. Frogs don't have fangs, though. Well, find it anyway!", objectives = "Kill Venomhexxer Raxxis and find the fang Tobui described.", progress = "Did you look for de big fang?", completion = "Hey, dat's a spider fang. Dat must have been one huge spider!" }
WordHunterWoW_QuestEN[91405] = { title = "Validating the Venom", description = "This means there are both frog and spider venoms in de mixtures. Halazzi says he senses somebody beseeched Shadra with dat fang. Dey must be a really big spider if their fang is dat big!\n\nHalazzi doesn't like that de Vilebranch had it. I can tell. He's unhappy. His ears get all flat like de wings of a kite.\n\nSo we gotta help out. Take de samples and de fang to de Witherbark Chief. We Witherbark have alchemists dat can brew anti-venoms for both spiders and frogs.", objectives = "Speak to the Witherbark Chief and locate an anti-venom alchemist in the village.", completion = "De Vilebranch are de ones doin' somethin' with Shadra?\n\nCould de spiders be workin' against de Witherbark? This doesn't make sense." }
WordHunterWoW_QuestEN[91406] = { title = "Far from the Hinterlands", description = "As a Torntusk of de Revantusk tribe, I am cautious of Witherbark because of our history with dem in de Hinterlands. My family moved here because of dem.\n\nThe Witherbark here in Zul'Aman seem to respect us, but de Witherbark I remember in de Hinterlands killed and backstabbed their allies for power.\n\nThey worshipped de spider loa, Shadra.\n\nWhen de Hinterlands's Witherbark temple Shadra'Alor fell, de Witherbark must have fled somewhere. Look around for evidence of Hinterlands Witherbark and of Shadra.", objectives = "Investigate the Witherbark from the Hinterlands for signs of Shadra.", completion = "All de places dey mentioned are right next door to Shadra'Alor! Dey probably worshipped Shadra.\n\nWe can't trust dem. Dey are like de venoms dey use. Dey will poison de rest of de tribe against de Revatusk--against us all!" }
WordHunterWoW_QuestEN[91407] = { title = "The Eye of the Loa", description = "I lost friends to venoms made from Shadra's spiders in de Hinterlands. I gotta know if Shadra's lurkin' around here, twistin' de minds of these Witherbark. No Revantusk will be safe in Zul'Aman with Shadra-worshippin' Witherbark around!\n\nMaybe I seem paranoid, but I have my reasons. And you have Halazzi's ear. You could ask him to reveal to you any hidden spiders, yes? I know those long ears can hear dem skitterin'!\n\nThere is a shrine behind me. Stand in front of it and see if he'll grant you a boon.", objectives = "Find evidence of Shadra in the Witherbark Bluffs with Halazzi's aid.", completion = "De spiders fled? I thought dey would put up more of a fight. And you said dey were small? Hm.\n\nWell, it doesn't matter. Halazzi has set us on this hunt now. We need to see it through." }
WordHunterWoW_QuestEN[91408] = { title = "Seeking Shadra", description = "We will untangle dis mess about Witherbark and Vilebranch soon enough. De loa Shadra and her schemes must be our first priority.\n\nI watched the spiders run in terror from you, and somethin' struck me. De spiders are not just running in panic--they're going somewhere... somewhere dey feel safe, and even I can see dem now. \n\nDey are not hiding anymore. Dey are on de run! Our hunt continues.\n\nLet's follow dem.", objectives = "Follow the spiders to find where they lead.", progress = "Where dis trail leads, we follow.", completion = "Let's hear him out, but keep your hand on your weapon." }
WordHunterWoW_QuestEN[91409] = { title = "Dreaming of Spiders", description = "There are three relics of Shadra. I only had two. I had de fang in de village and de eye hidden here. Dey musta stolen de fang somehow, then came for de eye!\n\nWe never had de Shell of Shadra--it was lost when we left Shadra'Alor. It's possible de Vilebranch have de shell.\n\nDe fang and de eye should let us talk to Shadra briefly, even if we lack de last ritual relic to summon her.\n\nCome with me. I will show you how.", objectives = "Attempt the ritual with the fang and eye to speak to Shadra.", progress = "De two artifacts should be enough to speak to a vision of Shadra.", completion = "This is de Shadra I remember from Shadra'Alor. She will assist us if we help her.\n\nShe keeps her promises." }
WordHunterWoW_QuestEN[91410] = { title = "Shared Loa", description = "De Witherbark Chief knows many of us came from de Hinterlands with our worship of Shadra'Alor, but believed Shadra was long dead.\n\nWe should let him know how Halazzi helped us to find and restore Shadra, and of Shadra's presence in de Witherbark crypt. He also must learn of de rapport with de Revantusk.\n\nI will stay with Shadra for now. Will you carry de message?", objectives = "Speak to the Witherbark Chief about Shadra.", completion = "With Shadra aligned with us against de Vilebranch, we will punish dem grievously for their evil acts." }
WordHunterWoW_QuestEN[91411] = { title = "Maisara Caverns: Deep in Maisara", description = "Shadra has asked dat we recover de third piece of Mixer Jamanga's ritual, de Shell of Shadra. With it, maybe we can bring her back.\n\nShe recognized both de Witherbark and Revantusk as her allies. I felt her approval upon all of us. I believe this is de right choice.\n\nHalazzi set us on dis path, and we each got our roles to see it through. Gather your allies and go into Maisara Caverns! I would expect one of their leaders to hold de shell. Kill dem and take it back.", objectives = "Recover the Shell of Shadra from within Maisara Caverns.", progress = "I think dat Shadra will honor her word.", completion = "I can't imagine dat was easy. Halazzi must have blessed your hunt." }
WordHunterWoW_QuestEN[91412] = { title = "Return of the Venom Queen", description = "It is time to bring Shadra to her proper place as a loa of de Witherbark and Revantusk. She will be small at first, but one day could be great like Halazzi and Nalorakk!\n\nEven a small loa will be a good ally against de Vilebranch venoms. She is de Loa of Spies, and will block their thievery of our people and relics, just as Halazzi hides them in the mists.\n\nHold de Shell of Shadra in de center of de room, and we will call de loa to us!", objectives = "Follow Mixer Jamanga's ritual to restore Shadra.", progress = "This is more than de return of a loa--it is a bridge between tribes.", completion = "This journey has been... eye-opening. \n\nHad you asked me at the start if we would be allies with Shadra, I would have laughed in your face!" }
WordHunterWoW_QuestEN[91413] = { title = "A Twilight Oath's End", description = "<The ancient runes on the page seem to twist under your gaze. Their power seems to be rapidly fading.>\n\n<Ve'nari would be interested in this.>", objectives = "Bring the Mark of the Twilight Oath to Ve'nari in the Oasis on K'aresh.\n\nProvided item:", completion = "Salhadaar cheated death to revive Dimensius, and cheated death again by escaping your wrath.\n\n<Ve'nari pauses for a moment.>\n\nA pity he escaped, but the All-Devouring has perished. Thank you." }
WordHunterWoW_QuestEN[91417] = { title = "Seek out Arator", description = "I see that my son is spending his time with the wounded. Do a father a simple favor and see if he could use your assistance.", objectives = "" }
WordHunterWoW_QuestEN[91419] = { title = "Elemental Dominance", description = "", objectives = "" }
WordHunterWoW_QuestEN[91420] = { title = "Swap Meet", description = "<The mysterious mineral thrums in your hand. Someone in Tazavesh will find a use for this. Look around the Veiled Market for an interested party.>", objectives = "Bring your discovery to Om'myuz in Tazavesh.\n\nProvided item:", completion = "<Om'myuz takes a closer look at the ore.>\n\nThat is quite the intriguing rock you've found. I would like to inspect it further, and any others you find. What say you to a trade?\n\nOther Cartel Om members in the Veiled Market may also be interested in trading wares, should you come across them." }
WordHunterWoW_QuestEN[91426] = { title = "The People's Champion", description = "I think we've done all we can for the moment, {name}. Let's return to the muster point.", objectives = "Return to the muster point with Arator." }
WordHunterWoW_QuestEN[91427] = { title = "Mausoloa Desecrations!", description = "", objectives = "" }
WordHunterWoW_QuestEN[91429] = { title = "Mausoloa Sarcophagi!", description = "", objectives = "" }
WordHunterWoW_QuestEN[91430] = { title = "Runaway Limbs!", description = "", objectives = "" }
WordHunterWoW_QuestEN[91437] = { title = "Call for Participants", description = "<You find a scroll in your pocket that was not there before.>\n\nHey, it's Nostwin! You doing anything? No? Come help us do TIME SCIENCE!\n\nEternus can tell you more.\n\nOkay thanks bye!", objectives = "Speak with Eternus at the Infinite Bazaar near Dalaran.<You find a scroll in your pocket that was not there before.>\n\nHey, it's Nostwin! You doing anything? No? Come help us do TIME SCIENCE!\n\nEternus can tell you more.\n\nOkay thanks bye!", completion = "Excellent timing, <name>. Now the research can begin." }
WordHunterWoW_QuestEN[91438] = { title = "Infinite Research: Heroic Worldly Deeds", description = "All across the Broken Isles there are people in need. They search for hope but are hard pressed to find any. You can be that hope.\n\nSeek out those in peril in the Broken Isles and be the champion they so desperately need.\n\nIt is through such acts that legends are made.", objectives = "Complete 3 world quests in Heroic World Tier.", completion = "A single heroic act can turn the tide. A single whisper of hope can turn back despair. This is what gives legends their power." }
WordHunterWoW_QuestEN[91439] = { title = "Infinite Research: Heroic Invasion Points", description = "The Legion does not fight conventionally. They deceive, manipulate, and undermine their opposition at every turn.\n\nThere are no battle lines against the Legion. They will open rifts at a weak point and then spill out of it sowing death and destruction. When they invade, it is on their terms.\n\nHowever, this strategy is not invincible. Potent champions, able to move and react swiftly, can stop these invasions at their source. Stop the Legion Invasion. Show people that the Legion can be defeated.", objectives = "Complete a Legion invasion point in Heroic World Tier.", completion = "The power you and your artifact possess were able to halt a Legion invasion. But was it you, or the artifact you wield, that is responsible? On that I will require more information." }
WordHunterWoW_QuestEN[91440] = { title = "Infinite Research: Hero of the Broken Isles", description = "Heroic deeds are a matter of perspective. What may seem trivial to a mighty hero such as you, could mean the world to another.\n\nSeek out those in need and aid them in whatever task they deem important. In doing so your legend will grow.", objectives = "Complete 5 quests in Heroic World Tier.", completion = "Your name is on the minds of the people, and is shared around the fire. The greater your legend becomes, the more powerful your name will be. But does the power of one's name eclipse that of the artifact they wield? This is the burning question." }
WordHunterWoW_QuestEN[91441] = { title = "Infinite Research: Heroic Greater Invasion Points", description = "Once the Legion has sown confusion and chaos, then they will begin their real assault. Huge invasion rifts will open and the Legion will march forth in great numbers. The defenders, scattered to protect against smaller rifts, will lack sufficient strength anywhere to stop them.\n\nThat is when champions like you are most needed.\n\nSeek out one of the Legion's major invasions and throw everything you have at it. \n\nShow the people that with enough determination you can cancel the apocalypse.", objectives = "Complete a greater Legion invasion point in Heroic World Tier.", completion = "Just as I predicted. You were able to stop a massive Legion invasion. It was not you, or your artifact that did this. Rather it was the combination of both that won the day." }
WordHunterWoW_QuestEN[91442] = { title = "Eco-Dome Al'dani", description = "We have received word from Ve'nari that the Wastelanders continue to stand in the way of progress on K'aresh. They threaten the most promising eco-dome.\n\nThe restoration directive of K'aresh must not be interrupted.\n\nPut an end to these inefficiencies.", objectives = "Biergoth wants you to confront Soul-Scribe within Eco-Dome Al'Dani.", progress = "Have you put an end to their efforts?", completion = "This is a promising beginning to our new relationship with K'aresh.\n\nGood work, outlander." }
WordHunterWoW_QuestEN[91443] = { title = "Infinite Research: Advanced Combat Studies, Rare", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a rare study, so focus on fighting rare opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", objectives = "Kill 4 rare enemies in Heroic World Tier.", progress = "We need more fight data to complete our study, and time is running short.", completion = "Well done, <name>. Moratari will be overjoyed to see these new data points." }
WordHunterWoW_QuestEN[91444] = { title = "Infinite Research: Advanced Combat Studies, Elite", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be an elite study, so focus on fighting elite opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", objectives = "Kill 5 elite enemies in Heroic World Tier.", completion = "Well done, <name>. Moratari will be overjoyed to see these new data points." }
WordHunterWoW_QuestEN[91445] = { title = "Infinite Research: Advanced Combat Studies, Comprehensive", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a comprehensive study, so feel free to fight whatever you wish so that we can get a baseline understanding of your abilities.\n\nAnd remember, this is for the greater good.", objectives = "Kill 75 enemies in Heroic World Tier.", progress = "We need more fight data to complete our study, and time is running short.", completion = "Well done, <name>. Moratari will be overjoyed to see these new data points." }
WordHunterWoW_QuestEN[91446] = { title = "Infinite Research: Advanced Combat Studies, Rare Elites", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a rare elite study, so focus on fighting rare elite opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", objectives = "Kill a rare elite enemy in Heroic World Tier.", completion = "Well done, <name>. Moratari will be overjoyed to see these new data points." }
WordHunterWoW_QuestEN[91447] = { title = "Infinite Research: Advanced Combat Studies, Demonology", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a demonology study, so focus on fighting demonic opponents so that we can get a better understanding of your abilities.\n\nAnd remember, this is for the greater good.", objectives = "Kill 30 demons in Heroic World Tier.", progress = "We need more fight data to complete our study, and time is running short.", completion = "Well done, <name>. Moratari will be overjoyed to see these new data points." }
WordHunterWoW_QuestEN[91448] = { title = "Infinite Research: Heroic Terrors of the Broken Isles", description = "It is time to put both you and your artifact to the test.\n\nSeek out a Terror of the Broken Isles and defeat them.\n\nI am certain that, no matter the outcome, you will provide us with much to think about. I will be watching with great interest.", objectives = "Kill a world boss in Heroic World Tier.", completion = "A fascinating outcome, <name>. This will shed some much needed light on our research." }
WordHunterWoW_QuestEN[91449] = { title = "Infinite Research: Advanced Combat Studies, Empowerment", description = "In order to better understand the power of both you and your artifact in this timeline we need to undertake some combat studies. It is like social studies, but with blunt force trauma.\n\nThis will be a study of the empowered enemies in the experimental, fractured timeline. We need to understand how your abilities fare in the face of terrifying change. \n\nAnd remember, this is for the greater good.", objectives = "Kill 10 empowered enemies in Heroic World Tier.", completion = "Well done, <name>. Moratari will be overjoyed to see these new data points." }
WordHunterWoW_QuestEN[91450] = { title = "We Ready Now", description = "Thank you, {name}! We ready for Pit.\n\nWe trained to be strong. You hurt us. Now we more strong.\n\nYou tell Boletus we ready now.", objectives = "Return to the Grudge Pit.", completion = "Already trained for the ring?\n\nWas very fast. Much impress.\n\nWhat is team's name?\n\nNeed name to shout when run into the Pit.\n\nAnd crowd needs name to shout when you beat other teams.\n\nOr if..." }
WordHunterWoW_QuestEN[91451] = { title = "Stalk Market", description = "<The mysterious plant thrums in your hand. Someone in Tazavesh will know what to do with it. Look around the Veiled Market for an interested party.>", objectives = "Bring your discovery to Om'mit in Tazavesh.\n\nProvided item:", completion = "<Om'mit turns the plant over in his hands.>\n\nA void-infused stalk from a dead wasteland? This is utterly useless to you. In fact, let me take it off your hands in exchange for plants with more... familiar properties.\n\nOther Cartel Om members in the Veiled Market may also be interested in trading wares, should you come across them." }
WordHunterWoW_QuestEN[91452] = { title = "Range of Knowledge", description = "I've always dreamed of being a Farstrider--the adventure! The romance! The beauty of nature! When they put out a call for help, I knew I had to join.\n\nCaptain Dawnrunner assigned me to the library initially, but with everything going on, we all have to be flexible.\n\nI don't mind, but I had hoped to collect all the overdue books before being sent on a real assignment. If you find any, would you bring them to the library for me?\n\nAnd feel free to give them a read! There are some interesting volumes!", objectives = "Retrieve 3 overdue books from around Farstrider Hold and return them to the library.", progress = "It really takes everyone to get through times like these.", completion = "It might seem like a small thing, but the small things add up." }
WordHunterWoW_QuestEN[91454] = { title = "Phase-Lost Adventurer", description = "Covered in slime and saliva, the journal bears a partial entry of a previous Phase Diver.\n\n<Day 27\n\nUntethered Space is much more vast than I expected, with monsters stronger than I have seen on K'aresh. \n\nThere is a nearby cave I will explore tomorrow. It is brimming with Phase-Altered Essence. This could bode useful for better understanding the ecology out here.>\n\nResearcher Essarae would be very interested in this.", objectives = "Take the journal to Researcher Essarae in Shan'dorah.", completion = "<Essarae flips to a random page in the journal.>\n\nThis is brimming with knowledge of Untethered Space. I would like to read it further. \n\nThank you for aiding my research." }
WordHunterWoW_QuestEN[91457] = { title = "Abundance: Watha'nan Crypts", description = "", objectives = "" }
WordHunterWoW_QuestEN[91458] = { title = "Prey: Endurance Hunter", description = "", objectives = "" }
WordHunterWoW_QuestEN[91459] = { title = "Manaforge Omega: A Walking Shadow", description = "Hero, can you hear me? There's a translocator the Shadowguard uses to send cargo to their reserves that can carry you directly to their post beneath the Manaforge. An ambush they'll never see coming!\n\nThere is of course, a catch. We do not have clearance to use their supply lines... so we need you to procure some for us. Take down the highest-ranking member of the Shadowguard you can find, return with identification, and we'll forge you a one-way ticket to the front lines.", objectives = "Defeat Nexus-King Salhadaar within Manaforge Omega on Normal difficulty or higher.", completion = "That certainly qualifies as high-ranking, <name>! After I work my magic, that translocator is as good as ours. Next stop, enemy territory!" }
WordHunterWoW_QuestEN[91460] = { title = "Manaforge Omega: A Walking Shadow", description = "Hero, can you hear me? There's a translocator the Shadowguard uses to send cargo to their reserves that can carry you directly to their post beneath the Manaforge. An ambush they'll never see coming!\n\nThere is of course, a catch. We do not have clearance to use their supply lines... so we need you to procure some for us. Take down the highest-ranking member of the Shadowguard you can find, return with identification, and we'll forge you a one-way ticket to the front lines.", objectives = "Defeat Nexus-King Salhadaar within Manaforge Omega on Heroic difficulty or higher.", completion = "That certainly qualifies as high-ranking, <name>! After I work my magic, that translocator is as good as ours. Next stop, enemy territory!" }
WordHunterWoW_QuestEN[91461] = { title = "Manaforge Omega: A Walking Shadow", description = "Hero, can you hear me? There's a translocator the Shadowguard uses to send cargo to their reserves that can carry you directly to their post beneath the Manaforge. An ambush they'll never see coming!\n\nThere is of course, a catch. We do not have clearance to use their supply lines... so we need you to procure some for us. Take down the highest-ranking member of the Shadowguard you can find, return with identification, and we'll forge you a one-way ticket to the front lines.", objectives = "Defeat Nexus-King Salhadaar within Manaforge Omega on Mythic difficulty.", completion = "That certainly qualifies as high-ranking, <name>! After I work my magic, that translocator is as good as ours. Next stop, enemy territory!" }
WordHunterWoW_QuestEN[91462] = { title = "To the Central Tower", description = "Ranger Asterae is one of our veterinarians. She usually cares for our lynxes, but the mana wyrm molt is too crucial to the health of the forest to go unmonitored.\n\nThe wyrms regulate the flow of magic from the ley lines to the rest of the woods. When the ley lines were disrupted, so was their molting season. It's not so dire as it once was, but they still need help from time to time.\n\nMeet Asterae at the Central Tower. She can tell you more.", objectives = "Meet Ranger Asterae at the Central Tower.", completion = "It's a good thing we came. There are more mana wyrms here than usual." }
WordHunterWoW_QuestEN[91463] = { title = "To the South Tower", description = "Despite being new to the Farstriders, Taemin has the hardest assignment. Eversong Woods has mostly recovered, but the further south you go, the more dangerous things get.\n\nHe's a capable mage, though. And we need his nose for magic.\n\nWe'll meet you down there once things are wrapped up here. Captain Dawnrunner was going to provide backup. She should be there by now.", objectives = "Meet Arcanist Taemin at the South Tower.", completion = "I-I'm not worried. This is what being a Farstrider is all about!" }
WordHunterWoW_QuestEN[91464] = { title = "Stormarion Assault", description = "", objectives = "" }
WordHunterWoW_QuestEN[91465] = { title = "Stormarion Assault", description = "", objectives = "" }
WordHunterWoW_QuestEN[91466] = { title = "Aiding the Green Dragons", description = "Nozdormu and Queen Alexstrasza believe the best path forward is to aid the Green Dragons.\n\nLike the Black Dragons, the Greens lack a true aspect to lead them. \n\nMerithra is currently hosting guests within the Emerald Gardens. Meet with her to see if you can aid her.\n\nI will continue tracking the incarnates and the other dracthyr.", objectives = "Speak to Merithra at Merithra's Watch in the Ohn'ahran Plains.", completion = "Thank you for coming, <name>. My guests are eager to see the Emerald Gardens, and I am pleased to host them.\n\nShall we get started?" }
WordHunterWoW_QuestEN[91467] = { title = "Incarnates on the Move", description = "{name}, I thought I'd find you here. I bring word from the other aspects and my scouts.\n\nThe incarnates are on the move. I know not what they're planning, but you should be aware of their actions.", objectives = "Speak with Emberthal to find out about the Incarnates.", completion = "The incarnates are looking for something. It's imperative we get more of the flights empowered to stop them." }
WordHunterWoW_QuestEN[91475] = { title = "Abundance: Abundant Voidburrow", description = "", objectives = "" }
WordHunterWoW_QuestEN[91476] = { title = "Behind Enemy Lines", description = "My friend, we've finished working on some new tools to ensure you'll do some real damage to the Shadowguard. Come by and let's sort it out together.", objectives = "Report to Zo'turu at Shadow Point.", completion = "My friend! Thanks to our informants inside the Manaforge, we've uncovered some technology that can help you bring it down. This translocator has been calibrated to project your soul back here for a few moments, allowing you to access whatever you may need--but be warned. The pull of Omega's energy fields are strong, and will rip your essence back to your body's position in short order. I'm told it's... quite painful. Still, any advantage is a good advantage. Make haste!" }
WordHunterWoW_QuestEN[91477] = { title = "Behind Enemy Lines II", description = "Our knowledge of technomancy deepens. Let's improve your weaponry inside the Manaforge.", objectives = "Report to Zo'turu at Shadow Point.", completion = "My friend! We've secured new technology to help you bring down the Shadowguard - put it to good use!" }
WordHunterWoW_QuestEN[91478] = { title = "Behind Enemy Lines III", description = "Our knowledge of technomancy deepens. Let's improve your weaponry inside the Manaforge.", objectives = "Report to Zo'turu at Shadow Point.", completion = "My friend! We've secured new technology to help you bring down the Shadowguard - put it to good use!" }
WordHunterWoW_QuestEN[91479] = { title = "Behind Enemy Lines IV", description = "Our knowledge of technomancy deepens. Let's improve your weaponry inside the Manaforge.", objectives = "Report to Zo'turu at Shadow Point.", completion = "My friend! We've secured new technology to help you bring down the Shadowguard - put it to good use!" }
WordHunterWoW_QuestEN[91480] = { title = "Behind Enemy Lines V", description = "We've got one last upgrade to give, my friend. Come by for one last tune-up and we'll make you the strongest you've ever been!", objectives = "Report to Zo'turu at Shadow Point.", completion = "With this, you are as powerful as our humble band of soundrels can make you. May it serve you well against Dimensius!" }
WordHunterWoW_QuestEN[91481] = { title = "Speed Siphoner", description = "Great work so far! We've finished some tech that should be useful during your assault on the Manaforge.", objectives = "Report to Zo'ropo at Shadow Point.", completion = "Zo'ropo brings you a new weapon. Use this to feed off of the Manaforge's arcane radiation and turn their energies against them." }
WordHunterWoW_QuestEN[91482] = { title = "Speed Siphoner II", description = "We've found a way to optimize the Speed Siphoner. Come back to HQ and let me give you a boost.", objectives = "Report to Zo'ropo at Shadow Point.", completion = "Twice as fast, twice as stable. Hunt them down." }
WordHunterWoW_QuestEN[91483] = { title = "Hacking the Mainframe", description = "Our saboteurs have made great progress on hacking Omega's security systems; swing by and let me tell you about what we've learned.", objectives = "Report to Zo'ropo at Shadow Point.", completion = "There are consoles inside the Manaforge that keep the flow of energy running smoothly within the facility. We've cracked security on the first set of them, allowing you to turn the tables on enemies near Loom'ithar and Soulbinder Naazindrhi. You'll only be able to use one, but sabotaging them should allow you an edge in battle. Good luck in there." }
WordHunterWoW_QuestEN[91484] = { title = "Hacking the Forgeweaver", description = "We've progressed further in our infiltration of the Manaforge's defenses. Return to HQ and I'll clear you for access.", objectives = "Report to Zo'ropo at Shadow Point.", completion = "We found a weakness in Forgeweaver Araz's engineering bay that should allow you access to another console nearby. Keep up the pressure, and we'll let you know once the whole facility is ours. Happy hunting." }
WordHunterWoW_QuestEN[91485] = { title = "Hacking the Planet", description = "Hero... we're in. We have full control of Manaforge Omega's security. I'll brief you on your next trip back.", objectives = "Report to Zo'ropo at Shadow Point.", completion = "Manaforge Omega's security systems are under our direct control. Thanks to the damage you've done in there, we can get you access to consoles extending all the way to Salhadaar, and whatever lies beyond. We've also ensured you can use every console you come across. That's all I can do for you. Get in there and finish the fight." }
WordHunterWoW_QuestEN[91486] = { title = "Attuned to the Aether", description = "Hello! I've learned valuable information about how exposure to Omega's manaflow is impacting you - let us discuss back at Shadow Point when you have a moment.", objectives = "Report to Ba'choso at Shadow Point.", completion = "My research shows that due to the Reshii Wraps' influence on your physical form, the powerful manasurges and reactors inside Omega can be used to your benefit! While this is only a fraction of your power, it seems that arcane enhancements made to your armaments are made ever more powerful while in their vicinity. This warrants further testing..." }
WordHunterWoW_QuestEN[91487] = { title = "Welcome to the Team", description = "", objectives = "My friend, we have made much progress together in bringing down the Shadowguard. For your sacrifices and efforts, my colleagues and I consider you one of us. Please, take this modified Gearglider as a show of our gratitiude - may it carry you safely to your next mission." }
WordHunterWoW_QuestEN[91489] = { title = "A Curious Companion", description = "", objectives = "<The purrkin looks at you warmly. For the first time since you've arrived in K'aresh, it seems to actually *enjoy* your attention. As it pushes closer, its soft mew confirms your suspicions - she seems to want to join you. At least for now.>" }
WordHunterWoW_QuestEN[91490] = { title = "Dousing Teldrassil", description = "", objectives = "" }
WordHunterWoW_QuestEN[91492] = { title = "The Tale of Aln'hara's Bloom", description = "", objectives = "" }
WordHunterWoW_QuestEN[91493] = { title = "Not What I Ordered", description = "<A bite wound wrecks Hathvelion's forearm.>\n\nSnapdragons... cruel creatures made to kill and feed. Their poison moves as you move. The naga bred the perfect pet.\n\nI'm here on a tip from Lyssara Duskmourne. Sunsail Anchorage's shipping routes have been sabotaged by the naga, and those routes converge... here.\n\nI intercepted a few shipments. Could you help me search them? My team is still out in the field, but they should report back soon.", objectives = "Inspect 5 Intercepted Shipments.", progress = "The blood elves could just use magic to trade. But there's something dependable about a sturdy wooden box.\n\n<Hathvelion thumps the table beside him and smiles.>\n\nPlus, I hear food and drink aren't as tasty after being transported by magic.", completion = "Lyssara's suspicions proved correct. The naga must be collecting arcane magic from sources all around Eversong. We must put a stop to it, immediately." }
WordHunterWoW_QuestEN[91494] = { title = "One Elf's Trash, Another Elf's Treasure", description = "The arcane arts are not my specialty. I'm more versed in tangible magic--herbs, mixtures, distillation, topical applications, extraction, suture, painkilling...\n\nRegardless--that wand. To my uneducated eyes, it looks usable. Why don't you test it on the arcana container? Maybe it could help us against the naga. If it's truly broken, no harm done.", objectives = "Test the Discarded Wand on the Container of Unstable Arcana. Then, empower the wand in Daggerspine Landing.", progress = "Maybe the wand was too weak for its original owner. Whatever the case, we can try to put it to good use.", completion = "You can just say I had a hunch about that wand.\n\n...although, be careful. It's powered up now. Don't accidentally drop it." }
WordHunterWoW_QuestEN[91495] = { title = "Familiar Faces in Peril", description = "Fair winds guide your steps. My wish has come true--Eversong flourishes. But like before, evil threatens all that is good.\n\nTwo townsfolk are unaccounted for since the naga arrived: Enith--Goldenmist's most curious apothecary, and Varnis--he's a student visiting from the city. It is my charge to find them.\n\nMy fellow ranger, Vedoran, must still be in the field. I wonder if he's found something important. Will you keep an eye out for him?", objectives = "Find Apothecary Enith, Apprentice Varnis, and Ranger Vedoran in Daggerspine Landing.", progress = "The Farstriders are grateful for your assistance.", completion = "It is a relief to know they are safe and sound. I hope Varnis will be all right. I saw him scamper back, face as white as a ghost, refusing to speak. He gathered his things and left.\n\nThank you, <name>. I hope no other villagers will be tempted to enter the naga's base!" }
WordHunterWoW_QuestEN[91504] = { title = "Arcane Amassing", description = "Well, you heard Numia. She'll have my bow split in two if I don't rest.\n\nRanger Vedoran reported activity at the lighthouse. A swarm of mana wyrms are gathered there, and of course, more naga.\n\nIf that's where the head of the snake lives, chop it off! My rangers Vedoran and Krann'an will accompany you. And take the wand with you. It proved its worth. Powered up, it should pack a punch against whatever you face.", objectives = "Slay Princess Naz'jena in Daggerspine Point.", completion = "The lighthouse itself was coming apart due to the increasing arcane energies, both latent and collected. How ominous indeed. I'll deliver a report to Regent Lord Lor'themar straight away.\n\nThanks to you, my rangers and the town are saved. For that, please rest and drink.\n\n...the wand exploded?! I suppose we now know why it was thrown away.\n\nYou know, a bow would never spontaneously combust." }
WordHunterWoW_QuestEN[91505] = { title = "Daggers in My Spine", description = "The naga have a history of abusing arcane magic. I bet my boots this is no different--arcane is their lifeblood and source of power. They are clever to operate now while Eversong is besieged by other threats.\n\nSince I became a Farstrider, I have safeguarded Eversong's western coast. My strike team set up watch on Goldenmist's perimeter already. Fortunately, the naga do not seem interested in the town yet, but they are far too close for comfort.\n\nOur course of action is simple: clear them out!", objectives = "Slay 12 Daggerspine naga in Daggerspine Landing.", progress = "We can't let the naga get any closer to Goldenmist.", completion = "You've struck fear and death into their water-spawned hearts! Well done.\n\nWe'll keep an eye on their base and prevent them from rebuilding." }
WordHunterWoW_QuestEN[91506] = { title = "Tale of the First Shul'ka and the Flame", description = "", objectives = "" }
WordHunterWoW_QuestEN[91507] = { title = "The Tale of Russula", description = "", objectives = "" }
WordHunterWoW_QuestEN[91522] = { title = "Order from Chaos", description = "Thank you for coming to speak with me, {name}. I know you are very busy these days.\n\nBut it is that very demand on your time that I wish to speak with you about. With all you have accomplished of late, I feel that there is bound to be some valuable data to be gleaned from your experience.\n\n As a {class} without equal, I would like to ask you about your deeds of late. Can you spare a moment for Moratari?", objectives = "Talk to Moratari and answer her questions.", progress = "Once I record this data point you can return to your busy schedule.", completion = "What an intriguing insight into those events.\n\nI watched them from afar, but it is so much more fascinating to hear the version of the events as you experienced them.\n\nThank you for sharing that." }
WordHunterWoW_QuestEN[91523] = { title = "Prey: Concealed Threat", description = "", objectives = "" }
WordHunterWoW_QuestEN[91525] = { title = "Head Hunting: Loom'ithar", description = "Our intelligence describes a colossal beast within the Manaforge, responsible for producing the fabric that gives the Shadowguard their very form. Take it down and we'll hinder their ability to produce reinforcements. Oh, and Ba'choso says to bring some of the silk back with you - he may be able to fashion it into something useful.", objectives = "Defeat Loom'ithar within Manaforge Omega on any difficulty.", progress = "Have you procured a sample?", completion = "Its quality is unlike anything I've ever seen! I'll get to work right away. Now, let's discuss your payment." }
WordHunterWoW_QuestEN[91526] = { title = "Head Hunting: Forgeweaver Araz", description = "My friend, I hope your assault is going well. It's time for you to dispatch the Forgeweaver; using his mastery of technomancy he oversees both the Manaforge's production pipelines... as well as the ritual to return Dimensius to this plane. His workshop will be further in and heavily guarded, but cutting him down should stop their plans of resurrection for good.", objectives = "Defeat Forgeweaver Araz inside Manaforge Omega on any difficulty.", progress = "Does the Forgeweaver yet live?", completion = "<name>... I should have seen that coming. His devotion to Dimensius knew no bounds, and he certainly had contingencies in place to make sure the ritual would be completed. We'll have to attack from another angle. We found some debris from his inner sanctum that made its way here - if you have the skill, we can teach you how to use it for your own ends." }
WordHunterWoW_QuestEN[91527] = { title = "Head Hunting: The Soul Hunters", description = "Careful in the wastes, my friend. Scouts report that a trio of Demon Hunters are training south of the Manaforge - with one of them exhibiting power like we've never seen. You can avoid their path if you wish, but ignoring them could open you up to being flanked should they decide to engage. I recommend taking them out if you can, as well as providing us some samples of their newfound strength.", objectives = "Defeat The Soul Hunters within Manaforge Omega on any difficulty.", completion = "Soul energy like I've never seen it. While we cannot return them to the way they were, I believe you can use these runes to empower yourself even *through* death. Take them with you, and use them wisely." }
WordHunterWoW_QuestEN[91528] = { title = "Head Hunting: Horrors of the Forge", description = "By now no doubt you've seen some of the Manaforge's Elite coming to Salhadaar's aid. I'm sending you a list of names now - focus on these targets, and you may uncover spoils to aid your assault.", objectives = "Defeat powerful Elite enemies within Manaforge Omega on any difficulty.", progress = "Have you eliminated your targets?", completion = "Nicely done, champion. The resources they were hoarding will find a much better home with your companions." }
WordHunterWoW_QuestEN[91529] = { title = "Head Hunting: Nexus-King Salhadaar", description = "The hour of Salhadaar's demise is upon us. While he may posture upon his Voidwing, he grows desperate at the feet of the All-Devouring. The army he commands is not enough for your might - strike him down.", objectives = "Defeat Nexus-King Salhadaar within Manaforge Omega on any difficulty.", completion = "Though not the end he deserved, we will celebrate his defeat nonetheless. See Zo'ropo to trade for a well-deserved reward. You have my eternal gratitude for deposing him." }
WordHunterWoW_QuestEN[91530] = { title = "Seeing Eye to Eye", description = "", objectives = "My friend, this little creature arrived at our hideout saying things like 'you killed my father, prepare to die'. We're not exactly privy to everything happening within the Manaforge, but surely you and this... young man can settle it like adults? Ideally away from our headquarters, and while using inside voices? \n\nI'm sure it's all a misunderstanding. Good luck working it out!" }
WordHunterWoW_QuestEN[91533] = { title = "What We Leave Behind", description = "Lothraxion deserved to pay for his arrogance with his life. Hieron didn't. Without him, I'd be dead. I know that Maella and Darkglen feel the same way.\n\nHieron's journal, the one you recovered for us, ended up with me. I knew Hieron, but Astre knew him better. The two of them had found a closeness I admired. Astre deserves to hold onto it.\n\nLast I saw Astre, Hieron was tending to their wounds back at Locus Point.\n\nYou were there when Hieron passed. They should know of his heroism and sacrifice.", objectives = "Deliver Hieron's journal to Riftblade Astre at Locus Point.", progress = "I've recovered some since we last parted ways here, but the whispers continue to plague me. They're insidious, torturing me with what I lack, how I've failed. And--\n\nWait. Is that...? Where did you get that?", completion = "<Astre accepts Hieron's journal and the letter with an empty and distant expression.>" }
WordHunterWoW_QuestEN[91535] = { title = "Home Sweet Grave", description = "<Astre spends a long time in silence, thumbing through Hieron's journal.>\n\nKilled on another world, defending a city that didn't want him. There was so much we planned to do. Now...\n\n<Astre trails off, their eyes focusing on the journal's pages.>\n\nOh. The tea recipe that Hieron was telling me about. He was excited for its properties--called it a purgative for the soul. He never had a chance to brew it.\n\nI know it seems stupid, {name}. I just want to taste Hieron's tea. The leaves should be nearby.", objectives = "Collect 8 Ghostflower Leaves around the base of Locus Point.", progress = "<Astre thumbs through Hieron's journal with a detached expression.>", completion = "I've got the kettle ready." }
WordHunterWoW_QuestEN[91536] = { title = "Like a Weed", description = "<Astre looks from Hieron's journal to the worn letter. Their expression flickers with anger.>\n\nBlood elves. They were our people until we embraced the Void. In their ignorance, they exiled us. Yet they are happy to ask us to fight their battles for them.\n\nThey say we threaten the Sunwell. The truth is, they are afraid of us.\n\nLet's protect something of actual value. Kill any beasts that threaten those flowers for Hieron's tea. Silvermoon can save itself.", objectives = "Kill wildlife around Locus Point.", completion = "I'm not exactly sure how this tea is supposed to help. But I trust Hieron's notes." }
WordHunterWoW_QuestEN[91537] = { title = "Confronting It", description = "I've put the kettle on. I trust you to brew it, if you wouldn't mind. It shouldn't take more than a moment before the tea is ready to drink.\n\nLet me try it first, just in case it's poisonous. I'm the one that asked to try it.", objectives = "Brew the Ghostflower Tea for Astre.", completion = "I thought I could spare myself this pain by pushing it down.\n\nYou barely even know me. But you've already done so much for me. Thank you." }
WordHunterWoW_QuestEN[91539] = { title = "A Radiant Echo", description = "<Within your hand, you hold a small Azerite sphere. Its light is steady and bright, but the sound it emits is plaintive and longing. It tugs at you, ever so slightly.>", objectives = "Bring the Radiant Echo to a Worldsoul Memory, then release it." }
WordHunterWoW_QuestEN[91541] = { title = "Unchecked Emotions", description = "Ren'dorei learn early to check our emotions. That by controlling ourselves, we can control the Void. Otherwise, our unsuppressed feelings can lead us to ruin.\n\nBut I felt just now the powers of facing my feelings head-on. Maybe I could have done it on my own... But the tea, and your aid, made it easier.\n\nWe should share Hieron's recipe with the others. I'll retrieve the kettle you brewed.", objectives = "Meet with Riftblade Astre at the Howling Ridge.", completion = "I was never the best at magic, but my cantrips can at least keep tea warm." }
WordHunterWoW_QuestEN[91542] = { title = "The Town Inside Me", description = "I can't say that drinking the tea is a pleasant experience. But it helps. I want the others to experience that too.\n\nThat Hieron left us with a gift like this is so... him. He was always doing little things like that for others. For me.\n\nShare the tea with the others, then join me at Obscurion Citadel. I know better than to be alone in a place like that.", objectives = "Serve Ghostflower tea to Umbric, Maella, and Sideras in the Howling Ridge.", completion = "So this is where it happened.\n\nI came here simply to mourn. But... there's something else." }
WordHunterWoW_QuestEN[91543] = { title = "Retaking Control", description = "This world is violent and dangerous, but it has an order to things. After you and the others took down the domanaar that ran this citadel and its arena, the food chain must have fallen to disarray.\n\nHarrowers swarm the skies and darken the horizon. I worry they'll seek new hunting grounds closer to our settlements if they aren't dealt with.\n\nPoint them out for me and I'll use my grappling hook to pull them to the ground. Hieron's survival gear proves its use when we need it, as always.", objectives = "Kill flying Harrowers and Siphoids in Obscurion Citadel.", progress = "Have they been dealt with?", completion = "Perhaps some new class of beast will grow strong without these flying monsters to hunt them. Let's hope they threaten the domanaar instead of us." }
WordHunterWoW_QuestEN[91544] = { title = "Familiar Energies", description = "I know that Hieron died here, but I feel echoes of someone else--of a great clash, where Void met Void. Hieron must have crossed blades with someone... something else. Something that's still out there.", objectives = "Scry Void Rifts with Riftblade Astre in Obscurion Citadel.", completion = "That domanaar is trying to open a portal to Silvermoon! How is this possible?" }
WordHunterWoW_QuestEN[91545] = { title = "Stronger Than Before", description = "That must be the monster that killed Hieron. It's tearing open a backdoor for the Void's forces to pour into Silvermoon.\n\nThis damn city. I'm not doing this for them.\n\nSignal Umbric. Let's do this. Together.", objectives = "Kill Notatus the Riftscarred.", completion = "A violent alien world can be home, so long as it's got the right people.\n\nI've got mine right here." }
WordHunterWoW_QuestEN[91546] = { title = "To Be Changed", description = "There is one unresolved matter...\n\n<Astre reaches into their pocket and reveals the worn letter you had unpackaged alongside Hieron's journal. They run their fingers over it with a pensive expression.>\n\nHieron wanted her to have it. She should know what happened to him.\n\nThis is on me. Silvermoon again... Guess I'll see you when I'm back, {name}.", objectives = "Speak to Umbric about meeting with Astre in Silvermoon City.", progress = "At least I'm not visiting my parents.", completion = "I'm glad I went through with this. Thanks for coming with me.\n\nLet's get back to the others in the Voidstorm, <name>." }
WordHunterWoW_QuestEN[91550] = { title = "A Game of Silence and Shadow", description = "You're different! That makes you kinda cool... and kinda really suspicious. We wanna see what you're made of!\n\nSo here's the game: we hide, and you try to find us. If you do, well... guess we'll have to train more for next time. But if you don't? Then maybe our parents will finally let us go on our first solo hunt!\n\nThis isn't just a silly game, okay? It's a trial called Silence and Shadow. It's serious. Very, very serious.\n\nAre you ready?", objectives = "Find 4 hiding children.", completion = "That monstrous petalwing took him! And we stood there... frozen like fungus! \n\n<Ilomai shakes her head and gathers her resolve.>\n\nWe don't have time to be scared. We move. Now." }
WordHunterWoW_QuestEN[91551] = { title = "De-nest-stration", description = "If mom and dad find out, we are going to be stuck on fish gutting duty for the rest of our lives! \n\nThe elders keep telling us that fear is only useful if it sharpens the mind. Right now, we need clarity, not panic.\n\nWe have to get rid of those nests. Maybe if they are gone, we can eventually find the one they took Shao'mal to. And this way, we can finally drive off those stupid birds!\n\nWe're going to find him. Will you help us?", objectives = "Search 5 Petalwing Nests for Shao'mal in Harandar.", completion = "Great job! Those petalwings might think twice now before settling down in our pla--I mean hunting area!" }
WordHunterWoW_QuestEN[91552] = { title = "Feathered Fury", description = "This would have never happened if those stupid petalwings weren't here!\n\nScare them off, chase them, whatever it takes--we just can't let them stay here. If they stay, they'll just keep hurting people. We can't let that happen.", objectives = "Defeat 8 Lightbloom Petalwings in Harandar.", completion = "You did it? Great! That's really great!\n\nWith more of those petalwings gone, we can finally focus on helping Shao'mal!" }
WordHunterWoW_QuestEN[91553] = { title = "Haranir Never Say Die!", description = "That's the one! The big one! The one that took him!\n\nWe didn't stop it before. But this time, we will. We are haranir. And haranir never back down. Haranir never give up.\n\nWe're bringing him back. And we're ending this. Are you with me?", objectives = "Defeat the Behemoth Petalwing in Harandar.", completion = "Thank you so much for rescuing me... not that I needed it of course. Anyway, you seem to be pretty good yourself. So after talking with everyone, we all agreed to make you a part of our group! \n\nBe proud. This is an honor only few have received, but you've earned every bit. You are officially one of us! Be proud, stand tall, and never give up!" }
WordHunterWoW_QuestEN[91555] = { title = "Defenders of the Vale", description = "", objectives = "" }
WordHunterWoW_QuestEN[91556] = { title = "Loa's Flame", description = "I will have to take what's left of de supplies back on foot.\n\nDe boat... it's no good now. De hull's cracked, and de frame's split. Won't carry another soul across de water.\n\nBut it'll still serve one final purpose.\n\nIt can be his pyre. We will burn it, de weapons, de armor he wore--everything with him.\n\nVengeance is done. Now we let de fire take him to de loa and to his rest.", objectives = "Prepare the funeral pyre for Tolbani in Atal'Abasi.", progress = "Not long now, Tolbani.", completion = "I hope it brings his spirit peace. And mine." }
WordHunterWoW_QuestEN[91557] = { title = "Message to the Molt", description = "Ah, champion! There are so many unique specimens to identify and catalogue here that I can't keep up.\n\nSpeaking of which, Lady Darkglen took time out of her busy schedule and coordinated an expedition to a particularly dangerous region north of here. I trust in her power, but I've not heard from her or her team in a while and am growing concerned. With any luck, they are simply caught up in their own research.\n\nThat being said, would you please find Lady Darkglen in the Molt and check in on her?", objectives = "Find Lady Darkglen in the Molt.", completion = "Verigien sent you? Good timing. Our expedition has run into an unforeseen problem." }
WordHunterWoW_QuestEN[91558] = { title = "Pestilent Petals", description = "A strange pathogenic presence has infected my fellow ren'dorei.\n\nWhen we arrived, I was awestruck by the colorful vibrancy of this decay-filled valley and its many blood-stained flowers. I had hoped to gather some for my collection... to study of course, but this pathogen was living in the same pestilent pools these blood petals thrive in. Are they naturally resilient, or do they have purifying qualities we can harness for a cure?\n\nDear {name}, please, cautiously gather blood petals for my research.", objectives = "Collect 10 Mature Blood Petals in the Molt.", progress = "Did you collect enough yet?", completion = "Absolutely beautiful! I only hope these flowers can provide a clue to cure my brethren." }
WordHunterWoW_QuestEN[91559] = { title = "Virulent Vermin", description = "The pathogen appears to spread unevenly among the Molt's wildlife.\n\nWhen my fellow ren'dorei were infected, they grew confused and unresponsive. The local fauna appear more resistant. I suspect some of the Molt's denizens have a stronger resistance than others. Perhaps by examining these beasts we can extract elements for a curative elixir.\n\nCould you gather livers from the creatures nearby?", objectives = "Gather 6 Specialized Livers from creatures within the Molt.", progress = "How goes the hunt? Have you gathered what we need?", completion = "Marvelous. Let us dissect these immediately, before they spoil." }
WordHunterWoW_QuestEN[91560] = { title = "Expunging Explorers", description = "Let us hope we are able to concoct a cure from the reagents you acquired.\n\nI have already prepared the base potion, but now we need to carefully mix in the blood petals and livers you procured. With some calculated determination and a bit of luck, we should be able to craft an antidote and administer it to the afflicted ren'dorei scouts nearby.\n\n{name}, assist Blocciniux by mixing in the gathered ingredients.", objectives = "Craft an antidote and cure the infected ren'dorei in the Molt.", progress = "Were you successful? Did the antidote work?", completion = "Riftwalker Lorn is dead? This is troubling news. \n\nYou have my gratitude for saving as many of the ren'dorei as you did." }
WordHunterWoW_QuestEN[91561] = { title = "Bloodborne Pathogen", description = "The bloodborne pathogen has mutated!\n\nThe ooze-like carriers of this pathogen usually die quickly, but this new variant is stable even without a host. If it escapes from here, it could infect more ren'dorei and spread across Voidstorm, or worse yet, Azeroth. Our entire operation is at risk.\n\nWe must stop this mutated variant before it spreads!", objectives = "Destroy the Mutated Pathogen in the Molt.", progress = "Have you contained the spread of this deadly pathogen?", completion = "With the mutated pathogen dealt with and the antidote in hand, we should be safe from further outbreaks. Thank you for your assistance, <name>." }
WordHunterWoW_QuestEN[91563] = { title = "Halazzi's Hunt", description = "All of these spiders... \n\nThere must be someting dat we are missing. Halazzi knew exactly how to reveal them, though.\n\nGo to Halazzi's temple. I have no doubt that there is more to dis. Seek out his loa speaker.", objectives = "Seek out the Loa Speaker in Halazzi's Temple.", completion = "Halazzi says he called you here to help. Is dat true, hash'ura?" }
WordHunterWoW_QuestEN[91565] = { title = "Voidscar Arena: The Grief Spire", description = "You, hero!\n\nVidious here wars with his nemesis, Ziadan, who has brought the most cutthroat, volatile members of the Horde here to fight for her. Murderers and traitors!\n\nThe leaders of the Alliance do not listen to our calls for action and vengeance! We must take matters into our own hands and support Vidious.\n\n<Amari looks you up and down and raises an eyebrow.>\n\nAnd if it is not hatred of the Horde that drives you, consider what valuable information you may glean by helping a powerful domanaar.", objectives = "Use the portal to the Grief Spire and report to Vidious.", completion = "Ah, another <class> of the Alliance. What is it that drives you, I wonder?\n\nI've heard so many sordid tales! Did the Horde butcher your family? Destroy your home? Betray you on the battlefield?\n\nOr are you one of the soft-hearted ones? Here merely for knowledge and power to benefit your home, not vengeance?\n\nIt matters not to me, so long as you fight in my name." }
WordHunterWoW_QuestEN[91566] = { title = "Voidscar Arena: The Hate Spire", description = "Lok'tar ogar, {class}.\n\nThis domanaar, Ziadan, wars her old foe, Vidious, who has brought the most bloodthirsty, vengeful members of the Alliance here to Slayer's Rise to fight in his name.\n\nZiadan now gives the Horde a chance to stand up for our honor. Our leaders may not sanction this conflict, but when have we let anyone keep us from fighting the good fight?\n\nEven if you have no grievance with the Alliance, Ziadan's efforts keep Vidious from turning his eye on Azeroth. Report to her for your orders.", objectives = "Use the portal to the Hate Spire and report to Ziadan.", completion = "You. You look ready for a battle.\n\nYour Horde is noble. You fight for honor. For glory. Sometimes, for the joy of it.\n\nYour eternal conflict with the Alliance is delicious. I shall savor it." }
WordHunterWoW_QuestEN[91582] = { title = "Pruning the Lattice", description = "", objectives = "" }
WordHunterWoW_QuestEN[91583] = { title = "Voidscar Arena: The Bastion of Valor", description = "Ziadan recently added your great foes, the Horde, to her ranks. However, it is not your fellow mortals that I see sieging my home.\n\nNo, I see monsters of Voidstorm, twisted and empowered, instead. Something is afoot. Has Ziadan added yet another new force to her army?\n\nGo and fight these monsters. Bring me any clues you find as to the source of their newfound power.", objectives = "Collect 12 Spiteful Shadowgraft from wild creatures in the Bastion of Valor.", progress = "What have you found?", completion = "Ah, of course! Shadowgraft.\n\nThis metal sends a creature surging with power, driving them into a blind, violent frenzy. It cannot be removed without killing the beasts." }
WordHunterWoW_QuestEN[91585] = { title = "Fresh from the Garden", description = "Age has caught up with me this morning and I have pulled something. \n\n<Yu'relen clutches his back.>\n\nStill, our village meal must be prepared. Otherwise, it will mean the loss of much more than just an empty stomach.\n\nIf you would gather some ingredients for the meal, your aid would not go unappreciated.", objectives = "Collect 6 Frillfish Fillet and 4 Root Drift Jelly in Harandar.", progress = "I hope you brought back a good harvest.", completion = "Excellent. Even an old cook can work wonders with good hands beside him." }
WordHunterWoW_QuestEN[91586] = { title = "Soil-Based Alternatives", description = "This meal is more than tradition--it is a promise.\n\nThe haranir, rutaani, and fungarians share no love, but in Har'mara they share this table. To honor that pact, each must be fed in their own way. That is what this meal means.\n\nFor the rutaani, they will need nutrient-rich soil as they draw sustenance through their roots. A few bags of it should do.", objectives = "Collect 6 Nutrient-Rich Soil in Harandar.", progress = "I hope you bring news of good soil.", completion = "Good. The rutaani will accept this without complaint. Peace rests on gestures such as these." }
WordHunterWoW_QuestEN[91587] = { title = "Carcass Cuisine", description = "The fungarians are caretakers of decay, transforming death into life's renewal. \n\nThey require a sporeglider carcass to sustain their vast community. There is one--larger than most--that has taken to warding off the root drifters we need to sustain our village.\n\nIts end will feed many, and ease our burden. Balance, in more ways than one.", objectives = "Defeat the Sporeglider Bloomterror in Harandar.", progress = "Did you bring the rind?", completion = "This carcass breathes new sustenance into the fungarians and the peace we uphold." }
WordHunterWoW_QuestEN[91588] = { title = "Harandar's Kitchen", description = "Now comes the true work: preparing what's been gathered. \n\nThe vegetables must be washed, the bones removed, and the fish roasted. A shared meal is only worthy if made with care. Only then may the meal carry the weight of peace.", objectives = "Prepare and cook the meal in Harandar.", progress = "How is the preparation coming along?", completion = "All is ready. Let those who share in this meal remember that unity is not ease--it is effort." }
WordHunterWoW_QuestEN[91589] = { title = "Root Dash Delivery", description = "It's simple fare, but made with care and meaning. Please, take it to the gathering place. I am sure the villagers will show up when the food comes.\n\nDespite the simplicity, if it brings quiet among them, it has done its part.", objectives = "Set up the communal meal in Harandar.", progress = "Once the meal is set, our job will be done for today.", completion = "You have done more than fill bowls--you have upheld something fragile and vital. For the peace of Har'mara, we thank you." }
WordHunterWoW_QuestEN[91590] = { title = "Prey: Concealed Threat", description = "", objectives = "" }
WordHunterWoW_QuestEN[91591] = { title = "Prey: Concealed Threat", description = "", objectives = "" }
WordHunterWoW_QuestEN[91592] = { title = "Prey: Concealed Threat", description = "", objectives = "" }
WordHunterWoW_QuestEN[91594] = { title = "Prey: Endurance Hunter", description = "", objectives = "" }
WordHunterWoW_QuestEN[91595] = { title = "Prey: Endurance Hunter", description = "", objectives = "" }
WordHunterWoW_QuestEN[91596] = { title = "Prey: Endurance Hunter", description = "", objectives = "" }
WordHunterWoW_QuestEN[91597] = { title = "Voidscar Arena: For My Alliance", description = "My bastion is besieged by Ziadan once more!\n\nYou Alliance have proven to me you are strong. I am eager to see you in action upon the battlefield. \n\nMy own forces could use a taste of your courage. Take this Voidclarion and embolden the void underlings that fight for me. Let them know they have your backing. Let them feel the glory of your Alliance!", objectives = "Empower 8 Griefbound forces at the Bastion of Valor in Slayer's Rise.", completion = "Excellent. The battle is only truly balanced when it tips toward my favor." }
WordHunterWoW_QuestEN[91598] = { title = "Voidscar Arena: Pre-Provoked Violence", description = "So, Ziadan would stoop so low as to use shadowgraft? Can she not adequately stir the bloodlust of her Horde minions? She's lost her touch.\n\nI need no such army to overpower her. I have you.\n\nShow her how it's done. Decimate her forces before they reach beyond the bounds of Slayer's Rise. They could threaten your precious mission here, after all.", objectives = "Slay Void creatures or players in the Bastion of Might in Slayer's Rise.", completion = "What?! If Ziadan is also besieged by shadowgrafted creatures, that means...\n\nAn interloper." }
WordHunterWoW_QuestEN[91599] = { title = "Voidscar Arena: A Familiar Grudge", description = "It is time to take the fight to Ziadan.\n\nShe undoubtedly has her own favorite pet--someone from your world who takes this conflict personally. She is particularly fond of the flavors of rage.\n\nI prefer aching, heart-wrenching grief, myself, and we shall prove which fuels you mortals with greater strength.\n\nAmong their forces is a dark warlock that has slain many of your kind. I've tasted their rage in the air.\n\nGo. Savor the fight.", objectives = "Slay Manus Deathwake at the Bastion of Might in Slayer's Rise.", completion = "Very good. The Horde is filled with such hateful, violent souls." }
WordHunterWoW_QuestEN[91600] = { title = "Voidscar Arena: Setting It Aside", description = "I knew shadowgrafting was beneath Ziadan. I would not spend eons locked in conflict with one so uncouth.\n\nTherefore, our little game has an uninvited guest. Not you, of course. We love watching you kill for us.\n\nTo the far north is the Voidscar Arena. The last time another domanaar tried to come between us, they built that citadel. It has laid empty for ages.\n\nIf another domanaar intends to challenge us, they will have staged their forces there.", objectives = "Meet the domanaar at the Voidscar Arena in Slayer's Rise.", completion = "Who is our enemy, then? Who seeks to rise and claim more power while Xal'atath's back is turned?\n\nTenebre? Chrysalius? Decimus?" }
WordHunterWoW_QuestEN[91601] = { title = "Prey: Apex Predator", description = "", objectives = "" }
WordHunterWoW_QuestEN[91602] = { title = "Prey: Apex Predator", description = "", objectives = "" }
WordHunterWoW_QuestEN[91603] = { title = "Voidscar Arena: Two Against One", description = "You. Alliance weakling.\n\nShadowgraft requires a potent font to power it--likely more than one, given this many creatures. They will be nearby. Destroy the power sources, then meet us on the next ridge.\n\nRemember: if this domanaar succeeds, their conquest will not end in Slayer's Rise. They will find a way to your homeworld. They would shadowgraft Azeroth herself. Put an end to this.\n\nMeanwhile, I suppose I shall relish in this opportunity to observe Vidious's weaknesses up close.", objectives = "Drain the Shadowgraft Graftnodes atop the Voidscar Arena in Slayer's Rise.", completion = "This will prevent further spread of the grafting. However, we must still deal with what remains ourselves. \n\nHow troublesome." }
WordHunterWoW_QuestEN[91604] = { title = "Prey: Apex Predator", description = "", objectives = "" }
WordHunterWoW_QuestEN[91605] = { title = "Voidscar Arena: The Wrong Side", description = "Indeed, the Voidscar Arena is crawling with Void once again. A domanaar rules here, I have no doubt.\n\nThey have not yet emerged to parlay. Our mysterious interloper must not be present. That is well.\n\nLet's have you put an end to this charade. Destroy their forces. Destroy their resources. And turn their tools against them. Make them feel the disdain I feel for them.\n\nZiadan and I shall investigate this interloper.", objectives = "Slay 12 Spiteful monsters, use 4 Graftshaper Tools, and destroy 6 Shadowgraft Energy Containers near the top of Voidscar Arena in Slayer's Rise.", completion = "We shall find glory in a battle yet." }
WordHunterWoW_QuestEN[91606] = { title = "Voidscar Arena: Clearing House", description = "A waste of a great monstrosity. Imagine its cunning were it not frenzied! It would have made a fine addition to my collection.\n\nThe shadowgrafting must end. I doubt this domanaar is doing the work himself. There must be a grafter nearby. \n\nWhile Ziadan and I weaken this monster, find and slay the grafter. Then these shadowgrafted monsters will never breach your precious world.\n\nIf nothing else, that will finally draw out our enemy.", objectives = "Slay Trelus the Grafter at the top of the Voidscar Arena in Slayer's Rise.", completion = "Charonus. Weak. Fickle. One of the first domanaar to bow to Xal'atath. \n\nUnsurprising. Still, let's hear if his offer is of any interest. Premature murder is so boring." }
WordHunterWoW_QuestEN[91612] = { title = "Infinite Research", description = "", objectives = "" }
WordHunterWoW_QuestEN[91613] = { title = "Infinite Research Promotion: Timely Assistant", description = "", objectives = "<name>, you have been an excellent assistant with our research. I think you deserve a promotion.\n\nFrom now on, you will be able to take on more research assignments simultaneously.\n\nIt's ironic, isn't it, that we never seem to have enough time. Make good use of your time here. Don't make me regret granting you this power.This quest line will unlock:" }
WordHunterWoW_QuestEN[91614] = { title = "Focusing the Energies", description = "In addition to shards of nightmare, we need Blood of Sargeras to reactivate the portal to the Rift of Aln.\n\nThis rare reagent can be obtained from around the Broken Isles. Rumor has it that emissaries are in search of hardened adventurers, and may offer these in reward.", objectives = "Collect 3 Blood of Sargeras.", completion = "Excellent, Archdruid. These will do nicely." }
WordHunterWoW_QuestEN[91615] = { title = "A Thirst For Blood", description = "Blood is the fountain of life and the fuel of my creations. Unfortunately, Deathlord, my supply is running low and the quality as of late has been disappointing at best.\n\nIf my undead offspring are to reach their full potential, I will need pure blood of the highest quality. Bring me the Blood of Sargeras and I will use it to fuel my finest creations!", objectives = "At last, I have enough Blood of Sargeras to fuel my creations! You will see, Deathlord, what my genius is truly capable of creating...\n\nNow, I must ask that you leave me to my work... there is much to do, and we have little time to waste!" }
WordHunterWoW_QuestEN[91616] = { title = "Required Reagents", description = "The Sentinels know of a trusted and talented enchanter who specializes in enchantments that affect demons.\n\nShe provides her services for free to the Sentinels, but she does require specific reagents to perform her enchantments.", objectives = "Collect the required crafting reagents.", completion = "This should do." }
WordHunterWoW_QuestEN[91618] = { title = "A Few Things First", description = "Lately I've been working with the ore of this land, leystone it's called. I've found its qualities to hold remarkable strength and durability. We'll need a lot of it for this.\n\nThere is felslate, but that's probably too tainted for what you're looking to do with this barding.\n\nYou know, I also like to adorn my pieces with something sparkly, like a jewel. I've heard that the elves of Suramar have particularly beautiful ones. Perhaps you could acquire one for this project.", objectives = "Obtain 1 Leystone Ore and a Suramarian Sapphire.", progress = "I doubt you'll have a problem getting the leystone, but the sapphire might be a bit harder to acquire.", completion = "You got them! Now to upgrade your barding.\n\nNever say a blacksmith can't improve on a leatherworker's work, I always say. I mean never. I mean... well you know what I mean." }
WordHunterWoW_QuestEN[91619] = { title = "Blood of Sargeras", description = "We will require a powerful reagent to bind the magic in our weapons and armor. A rare material that will do just the trick is Blood of Sargeras.\n\nWe will need a plentiful quantity. Bring me whatever you can muster.", objectives = "Collect Blood of Sargeras.", completion = "Yes, this is just what we need to complete our preparations. These must have been difficult to come by. Thank you, Highlord." }
WordHunterWoW_QuestEN[91620] = { title = "Noggenfogger's Reasonable Request", description = "Oh, the gall of that little green twerp! Marin Noggenfogger is blackmailing us. He says that if we do not meet his \"very reasonable requisition request\", he is going to close off access to the crucible.\n\nMarin's asking for a hefty amount of Aethril. He said something about you recently holding a blade to his throat and that he's simply returning the favor.\n\nOf course, if you would rather, I can eliminate him.", objectives = "Collect Aethril.", completion = "No hard feelings, right? Business is business, baby, and business is good. I saw an opportunity and I took it, just like you.\n\nTo show my continued allegiance with your little organization, and as a gesture of goodwill, here's a little sample of the product. It's magic. Bottoms up!" }
WordHunterWoW_QuestEN[91621] = { title = "A Taste For Blood", description = "Such an egg is quite precious, fleshling. Yet, my hunger gnaws so deep...\n\nSuch a barter will cost you... greatly.\n\nBring me 3 Blood of Sargeras, and I will give you the egg.", objectives = "<Ma'haat the Indomitable guzzles the Blood of Sargeras down his throat as he speaks.>\n\nYesh... thish ish... just what I wanted. The egg ish... yoursh!" }
WordHunterWoW_QuestEN[91624] = { title = "Spark of Starlight", description = "A vision of starlight permeates your mind.\n\nCustodian Khubon might have more information regarding these Fractured Sparks of Starlight.", objectives = "Speak to Custodian Khubon in Dornogal.", completion = "This is a fractured spark of starlight.\n\nEvery week, one of these fragments will appear while on your adventures. In its current state it's rather useless, but combining it with another fragment will grant it power. Reagents like these are malleable, robust, and the prize for many crafters.\n\nCombining two of these fractured fragments will create a unique crafting material that can help an item achieve expertise beyond that of mortal ability." }
WordHunterWoW_QuestEN[91627] = { title = "Saltheril's Haven", description = "{name}, I presume? Very good. Your reputation precedes you.\n\nLord Saltheril sends his most sincere greetings, along with a cordial invitation to join him at his estate south of Silvermoon.\n\nA portion of the grounds have been carved out as a decadent haven for those seeking refined company and pleasant conversation. He believes you would bring a... unique perspective.\n\n<He looks you over with a hint of polite disdain.>\n\nReceiving an invitation is a rare honor. His lordship hopes you will accept.", objectives = "Speak to Lord Saltheril at Saltheril's Haven.", completion = "Ah, <name>. Welcome to my Haven--a sanctuary from the world's turmoil since the days of Anasterian.\n\nSome presume this to be merely a frivolous party, but on these beautiful gilded grounds, decisions have been made over wine that have shaped the fates of entire generations." }
WordHunterWoW_QuestEN[91628] = { title = "Honored Guests", description = "I am pleased you could join us. Today marks the start of a very special occasion.\n\nThe sin'dorei are no strangers to the war table, but its aristocracy prefers to play more coy. In wartime, the crown sends representatives to curry favor with the nobles. If they are pleased, they might lend gold to the war effort.\n\nIt is very much like courting a lover, with all the jealous games you might imagine.\n\nSo let us play the game, shall we? Deliver these invitations while we finish preparations here.", objectives = "Deliver Lord Saltheril's invitations to the Magisters, Blood Knights, Farstriders, and \"traders\" in Silvermoon.", progress = "Your presence is already turning heads. This will be quite the spectacle.", completion = "Ah, so the rumors are true about your efficiency.\n\nExcellent. Now we can begin the game." }
WordHunterWoW_QuestEN[91629] = { title = "High Esteem", description = "Invitations to my Haven are highly exclusive, especially at a time like this. Extending an offer, even a temporary one, is a great honor.\n\nMy favor carries quite a bit of weight amongst the aristocracy. If I invite an ally of one of our representatives, it suggests I think highly of them--and if I think highly of them, so too will our noble guests.\n\nBut is it not terribly fun if I let you choose an invitation instead?\n\nGo peruse any enticements they may offer, then make your selection.", objectives = "Visit the vendors at Saltheril's Soiree, then choose an ally of the Magisters, Blood Knights, Farstriders, or Shades of the Row to invite to Saltheril's Soiree this week.\n\nYour choice will determine which faction will offer \"Fortify the Runestones\" to your Warband this week.", progress = "Pick any invitation you desire.", completion = "I will have my valet send for them at once." }
WordHunterWoW_QuestEN[91630] = { title = "Stolen Sight", description = "I can explain, I swear it!\n\nI concealed my knowledge of Shadra before because so many people assume she is an evil force. Our lady is merciless, but only to her enemies. \n\nWhen de Witherbark left de Hinterlands, we had to leave our temple of Shadra'Alor. I brought two of her relics with me: de eye and de fang.\n\nDe Vilebranch stole de fang. Dey are near where I hid the Eye of Shadra, collectin' venom from her children! Please kill de Vilebranch trespassing in the crypt. We can't let dem find de eye.", objectives = "Defeat the Vilebranch leading the attack on Shadra's children and recover the Eye of Shadra.", progress = "I can understand why dey want de venom, but de artifacts are just for communin' with Shadra. What would dey need with them?", completion = "They must mean to weaken us and our ability to commune with Shadra." }
WordHunterWoW_QuestEN[91631] = { title = "Epoch Progress", description = "", objectives = "Your power grows stronger, <name>.\n\nPlease, take this token of our gratitude for your assistance with our research. Let it echo with every you that exists in the fractures of this timeline." }
WordHunterWoW_QuestEN[91632] = { title = "The End of an Epoch Journey", description = "", objectives = "You have reached your full potential, <name>. Or have you? Perhaps this is only the beginning of your journey through this epoch.\n\nPlease, take this token of our gratitude for your assistance with our research. Let it echo with every you that exists in the fractures of this timeline." }
WordHunterWoW_QuestEN[91639] = { title = "Embrace Your Own Legend", description = "I will keep a close eye on your progress and watch your exploits with that artifact unfold with great interest.\n\nOnce you have embraced the power of your own legend, I would like to hear your perspective on how important the artifact you wield has been on your journey.", objectives = "Talk to Eternus at the Infinite Bazaar in Dalaran once you have embraced your own legend.", progress = "We are on a journey of learning and discovery. Let us walk it together.", completion = "You have grown stronger, but your artifact is stronger yet.\n\nIt would appear that my hypothesis holds true--artifacts appear to be the key to protecting Azeroth." }
WordHunterWoW_QuestEN[91691] = { title = "The Vanishing of Iridikron", description = "As you traveled through Zaralek caverns, Chronormu and I confronted Iridikron and the Infinite Dragonflight.\n\nWhile we defeated the Infinite Dragonflight's champion, Chrono-Lord Deios, I fear Iridikron escaped.\n\nAllow me to show you what happened, for it gives us a clue of what must be done next.", objectives = "See Nozdormu's vision of the conflict with Iridikron.", completion = "What Iridikron plans to do with that artifact is beyond my vision.\n\nWe must focus on Vyrakk and Vyranoth for now." }
WordHunterWoW_QuestEN[91693] = { title = "The Subtle Game", description = "Appearances are everything. If the court sees that I favor a certain group, they will follow suit.\n\nTake these tokens of my favor and hand them out to our honored guests as you see fit. I suspect they may invite you to partake in their plans and share in the profits, if you choose to align yourself with their cause.", objectives = "Hand out 3 tokens of Saltheril's Favor to the factions you wish to aid this week.", completion = "Splendid.\n\nI dearly hope you find some time to enjoy yourself while court is in season. While I do appreciate the sullen, results-driven sort, you could stand to smile." }
WordHunterWoW_QuestEN[91694] = { title = "Voidscar Arena: Breaking the Triad", description = "That glint in your eye! You've already identified me as an enemy and are thinking about how to slay me, yes? Good. \n\nI sent my forces to Ziadan and Vidious's bastions to overthrow them. Then, Xal'atath's bidding pulled me away and I missed all the action.\n\nFortunately, you are here now. You seem like even greater entertainment than watching these two smitten fools refuse to actually end one another.\n\nCome, then! I will prepare my arena and we will put on a real show! Slay me, if you can!", objectives = "Enter the Voidscar Arena and defeat Charonus.", completion = "What did Charonus bolster their army with? Azerothian captives? Figures. \n\nHe only would have taken the most bloodthirsty he could find, if that knowledge helps you sleep at night.\n\nGood work. Charonus will come between Vidious and I no longer.\n\nYou have been helpful. I will ensure you benefit from this aid rendered." }
WordHunterWoW_QuestEN[91695] = { title = "Tracking Down Incarnates", description = "We must turn our attention to Fyrakk and Vyranoth with Iridikron seemingly vanished from our sight.\n\nMerithra and the Green Dragonflight have been pursuing him and have a lead. \n\nThey've received the aid of Shandris Feathermoon in this task.\n\nShe awaits you within Valdrakken. Shandris will need your help with what is to come.", objectives = "Find Shandris Feathermoon within Valdrakken.", completion = "Ah, <name>. I was about to send a messenger to find you.\n\nI suppose this is Nozdormu's doing. The Bronze Dragonflight do tend to be proactive.\n\nLet's get started." }
WordHunterWoW_QuestEN[91700] = { title = "Darkness Unmade", description = "The Void energies concentrated in this citadel have given rise to numerous aberrant creatures.\n\nWildlife mutated by residual energy and horrors originating from beyond the anomalies, continue to feed and draw upon the energies here. It is most unpleasant!\n\nTo safeguard my future enterprises, these threats must be neutralized.", objectives = "Eliminated 2 Rare creatures in the Stormarion Citadel and surrounding area.", progress = "Have you eliminated the threats?", completion = "I feel much safer knowing those threats have been eliminated." }
WordHunterWoW_QuestEN[91721] = { title = "Surpass Your Own Legend", description = "While artifacts are key, we must not dismiss the power of the individuals who wield them.\n\nContinue in your fight against the Legion. Grow strong, stronger than you ever thought possible.\n\nThen we will compare the might of your legend against that of the artifact.", objectives = "Talk to Eternus at the Infinite Bazaar in Dalaran once you have surpassed your own legend.", progress = "The person wielding an artifact is of some importance. But how much? Which legend is the greater?\n\nLet us find out together.", completion = "I admit. I am pleasantly surprised to be proven wrong. Your power has grown and I cannot say with certainty which is the greater. You, or the weapon you wield." }
WordHunterWoW_QuestEN[91722] = { title = "Shape a New Legend", description = "It is clear now that the person is at least as important as the artifact they wield.\n\nPerhaps it is the quality of mortality that diminishes the importance of the individual through the lens of history. While an artifact is eternal, the people wielding them are fleeting.\n\nBut no flame that burns brightly burns forever.\n\nI want you to burn as brightly as you can. Empower your artifact and carve a new legend into the world for all to see.", objectives = "Talk to Eternus at the Infinite Bazaar in Dalaran once you have shaped a new legend.", progress = "An artifact cannot empower itself. Its power grows only when its wielder performs great deeds with it.", completion = "Humbling.\n\nIt is the very nature of finite existence that is the answer.\n\nMortality is the flame that shines brightest because it is free to choose a single moment of glory, rather than be burdened by the weight of eternity.\n\nChoose your moment well, <name>, and nothing, not even time, will be able to stop you." }
WordHunterWoW_QuestEN[91726] = { title = "Unstoppable Force", description = "This statue seems out of place here. Nothing else like it. But this is where Anduin Lothar fell against Orgrim Doomhammer at the Battle of Blackrock Mountain.\n\nMany fought on this field. Many didn't make it. Lothar... \n\nLet me tell ye what happened all those years ago.", objectives = "Ask Kurdran about the events of that day.", progress = "It was such a dark day, <name>. Painful to remember.", completion = "It's a tragic story, but maybe something better can be made o' it with those fragments of Turalyon's shield.\n\nPerhaps it can be restored--along with our friend." }
WordHunterWoW_QuestEN[91727] = { title = "Isles United", description = "I never doubted you for a second, {name}.\n\nI wanted to reflect on all that you accomplished in your fight against the Legion.", objectives = "" }
WordHunterWoW_QuestEN[91728] = { title = "Suramar Liberated", description = "You have come a long way, {name}. I never seem to tire of following your exploits. Even from afar, as a silent observer, I find myself absolutely invested in what you will do next.\n\nI do have one question though.", objectives = "Talk to Moratari and answer her question.", completion = "Very intriguing.\n\nI will, of course, record that as a data point.\n\nKnowing how you decide on a course of action will inform further hypothesis." }
WordHunterWoW_QuestEN[91729] = { title = "Armies Gathered", description = "The stakes have never been higher than now, {name}.\n\nI would very much like to know what you are thinking right now.", objectives = "Talk to Moratari and answer her question.", completion = "Fresh insights are invaluable in our efforts here, <name>.\n\nThank you for sharing yours." }
WordHunterWoW_QuestEN[91730] = { title = "Azeroth Saved", description = "{name}.\n\nYou have done it! Sargeras is gone and Azeroth is saved.\n\nI can only imagine what must be going through your mind at this moment.\n\nLet us remedy that.\n\nAllow me to record your thoughts and your words. Not as written by a historian who you never met, but by a friend who wished nothing more than to listen.", objectives = "Talk to Moratari and answer her question.", completion = "Too many histories are written about the WHAT, the WHY, the HOW, and the WHEN. Other than names, however, we so rarely get to truly know the WHO." }
WordHunterWoW_QuestEN[91731] = { title = "Midsummer Test", description = "", objectives = "" }
WordHunterWoW_QuestEN[91739] = { title = "Endeavor Reward", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[91747] = { title = "Not Quite Nalorakk", description = "Were you the one we saw enter Nalorakk's temple with Zul'jarra?\n\nI thought so! Zul'jarra spoke to him, didn't she?\n\n<Furgh growls in an unsettling way from deep in his throat.>\n\nThat doesn't make sense. The new Voice of Nalorakk says Nalorakk won't speak to anyone but him.\n\nHe gave some of the tribe trinkets to feel closer to Nalorakk. But the tribe now fights over them. The ursas think it's unfair they don't get any. But the chosen cling to them.\n\nWe must take them before more blood is spilled.", objectives = "Remove 8 Nalorakk Trinkets from the furbolgs in Spiritpaw Village.", progress = "I don't want them. We'll toss them on the fire.", completion = "I think the trinkets were corrupted too.\n\nI'm glad the trinkets are out of my tribe's claws." }
WordHunterWoW_QuestEN[91748] = { title = "Too Much Twilight", description = "This big bear called himself the Voice of Nalorakk and has \"chosen\" some of our tribe as his favorites. He doesn't know, but I saw him put dark, glowing lodestones in the totems around the village to give his chosen power.\n\nDark power radiates from them. The power smells wrong. Not like Nalorakk.\n\nOur guardian bears get agitated and upset near them. They can smell it too!\n\nWe must cleanse the camp. Get rid of those totems!", objectives = "Destroy 4 corrupted totems in Spiritpaw Village.", completion = "I don't know what this fake bear is planning.\n\nBut it's better that his lodestones are destroyed." }
WordHunterWoW_QuestEN[91749] = { title = "It's Just Not Right", description = "If Chief Groffa is leading the tribe into the dark, he needs to be stopped. The Voice of Nalorakk dazzled Groffa with trinkets. He keeps them locked away so no one else can have them.\n\nIf that is true, he's corrupted too. Even more than the others!\n\nStop him and get the gifts out of the village.", objectives = "Stop the Chief and recover the false gifts.", progress = "What is he hoarding in his camp?", completion = "<Furgh licks his chops. They are wet with drool.>\n\nThe bag feels... tempting. I don't like it!\n\nGood he kept this away from others, but also very bad for him." }
WordHunterWoW_QuestEN[91750] = { title = "Perils of Trust", description = "That was scary. We nearly lost Furgh!\n\n<Fleeg's fur twitches in fear and worry as he looks Furgh over.>\n\nFurgh said he heard the Voice of Nalorakk talking to him after touching the treasures.\n\nBut it can't be Nalorakk's voice. Nalorakk doesn't need trinkets!\n\nRip out the throat of this evil that dares to say it speaks for Nalorakk!", objectives = "Kill the false Voice of Nalorakk.", progress = "<Fleeg howls mournfully.>\n\nKill them for what they did to Furgh!", completion = "It was a Twilight's Blade monster!\n\nI hope Furgh and the others will be okay now that it is dead." }
WordHunterWoW_QuestEN[91757] = { title = "Until Our Next Hello", description = "Well, the moment is fast approaching now.\n\n<Moratari subtly nods in the direction of the raging temporal storm overhead.>\n\nYou would think after so many goodbyes I would be better at this, but alas, I simply prefer hello over goodbye. I know a lot of people around here are going to miss you too.\n\nYou should go say goodbye to them while there is still time.", objectives = "Say goodbye to the infinites at the Infinite Bazaar.", completion = "There. That was not so bad after all.\n\nThis is not goodbye. It is just a pause until our next hello.\n\nI look forward to it, <name>." }
WordHunterWoW_QuestEN[91759] = { title = "Don't Bring That Here", description = "", objectives = "" }
WordHunterWoW_QuestEN[91768] = { title = "Sweating Mana", description = "Default Description", objectives = "Log Description\n\nProvided item:" }
WordHunterWoW_QuestEN[91776] = { title = "Wildhammer and Free", description = "", objectives = "" }
WordHunterWoW_QuestEN[91778] = { title = "Too Deep and Too Dark", description = "", objectives = "" }
WordHunterWoW_QuestEN[91779] = { title = "Combat Training for Cultists", description = "", objectives = "" }
WordHunterWoW_QuestEN[91780] = { title = "Ethereal Delves", description = "There's even more tae do in delves, {name}! \n\nMeet me in Dornogal. There's loads to discuss!", objectives = "Meet Brann Bronzebeard within Dornogal.", completion = "Good tae see ye! We've got plenty tae discuss." }
WordHunterWoW_QuestEN[91781] = { title = "Seasonal Reminder", description = "We're back tae uncovering even more things within delves! \n\nLet's get ye up to speed on what's new first.\n\nAfter that I'll need your help with a wee problem of my own...", objectives = "Learn about Season 3 of Delves from the Delver's Documents, then purchase supplies from Reno Jackson and Sir Finley Mrrgglton.", completion = "Right, on to that wee problem I mentioned." }
WordHunterWoW_QuestEN[91782] = { title = "Repossessed!", description = "I think ye may have guessed what my problem is by now, {name}.\n\nMy clothes, my tools, my curios! Everything but my boots and hat, which I'm nae giving up again.\n\nAll repossessed by some cartel thug who said I was delinquent on my void storage payments, if ye can believe it.\n\nWould ye be willing to help Ol' Brann out of this pickle? I'm sure if ye just explain that this is all some sort of mistake, they'll give back all my hard earned gear.\n\nOr at least me britches.", objectives = "Recover Brann's lost gear.", progress = "Has it always been this breezy in Dornogal?", completion = "I can't believe it was a ruse all along.\n\nA shame about the curios, but at least ye got me britches back!" }
WordHunterWoW_QuestEN[91787] = { title = "The Journey Ends", description = "The Light takes many forms. But I know now what it means to me, and how I want to wield it.\n\nI'm not just a weapon like my father, nor can I devote myself purely to service like Dezco.\n\nBut I can protect people from the evil that threatens them. Right now, that's Xal'atath and her Devouring Host.\n\nWe should return to Lor'themar and do whatever is needed to defeat the Void.\n\nBeyond that, I shall see where protecting others with the Light takes me.", objectives = "Return to Silvermoon.", completion = "Thank you, <name>, for bolstering our defenders at the Sunwell.\n\nIt looks like Arator has sorted things out as well, and is ready for whatever may be ahead. It is good to have you both focused on the fight against the Void once more. \n\nArator is a good man. I'm grateful we didn't lose him to this conflict." }
WordHunterWoW_QuestEN[91789] = { title = "Apocron", description = "", objectives = "" }
WordHunterWoW_QuestEN[91790] = { title = "Brutallus", description = "", objectives = "" }
