WordHunterWoW_QuestEN[91792] = { title = "Si'vash", description = "", objectives = "" }
WordHunterWoW_QuestEN[91795] = { title = "Disrupt the Call", description = "We do not know where they intend to strike, but we do know they aim to summon more to their cause.\n\nDestroy the Twilight's Blade before they complete their rituals. We must not let a single champion of the void remain to inspire the new recruits.", objectives = "Defeat 3 Twilight's Blade rares in the Twilight Highlands.", progress = "There is much to do. Do not dawdle.", completion = "These champions of the Twilight's Blade are just as foolhardy as the other members of the cult. We will cut them all down, in time." }
WordHunterWoW_QuestEN[91798] = { title = "Fish Of The Day", description = "", objectives = "" }
WordHunterWoW_QuestEN[91799] = { title = "Trial of Flight", description = "", objectives = "" }
