WordHunterWoW_QuestEN[91805] = { title = "Boughs in the Burrows", description = "", objectives = "" }
WordHunterWoW_QuestEN[91806] = { title = "Big Game Hunting", description = "", objectives = "" }
WordHunterWoW_QuestEN[91808] = { title = "Resource Recovery", description = "", objectives = "" }
WordHunterWoW_QuestEN[91810] = { title = "Blistereel Boar Buffet", description = "", objectives = "" }
WordHunterWoW_QuestEN[91813] = { title = "The Spiritpaw", description = "I just chased away some furbolg dat were actin' real strange.\n\nDey were arguin' and then one walked toward Lilaju with his hands in de air.\n\nI charged at dem an' scared dem off. Dey are usually hostile and who knows what dey were gonna do?\n\nBut Lilaju wants to see what dey wanted.\n\nOur scouts saw dem follow de river east to de north side of de lake. Track dem down. See what dey want.\n\nIf it's a trick, then kill dem.", objectives = "Find the Spiritpaw furbolg that wanted to speak to Lilaju.", completion = "We meant no harm. We wanted to talk about Nalorakk.\n\nA bear showed up that says it speaks for our loa, but it feels wrong.\n\nMaybe with your help, we can sniff out a solution." }
WordHunterWoW_QuestEN[91821] = { title = "Out of Time", description = "There you are, {name}. This timeline is collapsing!\n\nPresumably you have noticed the great rift tearing through reality above us. We don't have much time remaining before we must retreat from this timeline.\n\nTo make matters worse, infernals from other timelines are starting to pour in. Send them back from when they came.", objectives = "Slay a Lost Legion Infernal on the Broken Isles.", completion = "Hmm, burning that pamphlet produced a very peculiar reaction from the flames.\n\n<Moratari begins taking notes, completely ignoring you.>" }
WordHunterWoW_QuestEN[91822] = { title = "The Regent's Request", description = "Lor'themar has requested our presence. He wasn't exactly forthcoming with the details, but the location he chose speaks volumes.\n\nSilvermoon Harbor. Quiet and out of sight. Not exactly the kind of place one picks for diplomacy or ceremony. No, this feels like something else entirely. Whatever he's planning, it won't be written down in any official record. \n\nCome. Let's find out what the Regent Lord has to say.", objectives = "Find out what Lor'themar is planning.", progress = "Let's not keep the Regent Lord waiting.", completion = "This should be interesting." }
WordHunterWoW_QuestEN[91823] = { title = "Lines Cut, Tongues Silenced", description = "The Twilight's Blade slipped into Tranquillien so easily because they'd stolen knowledge and secrets. About our defenses, our magic, our people. Once inside, they uncovered even more information. \n\nNow they pass that intelligence between themselves using enchanted orbs. Quiet whispers drifting through the dark. Every message tightens the noose around Quel'Thalas.\n\nFind the orbs. Break them. Every shattered crystal is a whisper silenced.", objectives = "Destroy the Communications Orbs in Zeb'tela Ruins.", completion = "Well done. The less they know, the safer our people are." }
WordHunterWoW_QuestEN[91824] = { title = "The Thieves' Trail", description = "From what I can see, it looks like the Twilight's Blade stole several arcane artifacts used by our Magisters to enhance long-distance communication. If they learn to wield them, they'll cast their reach far beyond what we can contain. They might even be able to hear our communications... and we can't have that.\n\nRecover the artifacts. If anyone gets in your way... you know what to do.", objectives = "Recover Quel'dorei Artifacts from the Twilight's Blade in Zeb'tela Ruins.", progress = "Those artifacts should never have fallen into the wrong hands.", completion = "Good. With these back where they belong, their reach just got a lot shorter. I only wish we'd uncovered who took them originally." }
WordHunterWoW_QuestEN[91825] = { title = "Dead Men Keep No Secrets", description = "From what I've seen, this group isn't acting without direction. There's someone leading them, a man hiding in one of their structures.\n\nIf I had to guess, he's the one holding whatever they considered too important to trust to crystal or courier. Documents, plans, names.\n\nFind him, silence him, and bring back whatever he was protecting.", objectives = "Retrieve the stolen documents from Gareth the Listener in Zeb'tela Ruins.", progress = "You made that look easy.", completion = "Excellent. All of their most important secrets, out of their hands." }
WordHunterWoW_QuestEN[91826] = { title = "Tripwire Tango", description = "This cache isn't locked with magic. It's craftsmanship. I can hear the mechanism ticking inside. Tiny cogwheels, tension springs, and probably a poison vial ready to shatter the moment someone tries to pick the lock.\n\nWe'll have to do this together. I'll take the pins, you keep the mechanism from snapping. One wrong move and it'll be enough to drop an ogre in mid-charge. Steady now.", objectives = "Disarm the mechanism and retrieve the documents from inside the chest.", progress = "Easy does it.", completion = "This is vital information. No wonder they went to such lengths to protect it." }
WordHunterWoW_QuestEN[91827] = { title = "No Loose Ends", description = "You handled yourself well.\n\nThese documents are too important to pass through couriers or ravens. I'd like you to deliver them personally to Lor'themar. He'll want to see the truth for himself and know who brought it back.\n\nKeep them close, and don't let anyone else near them.", objectives = "Return to Lor'themar Theron in Silvermoon City.", completion = "<Lor'themar examines the documents carefully. After a moment, he looks up at you and allows a faint smile.>\n\nExcellent work. I knew I could count on you both." }
WordHunterWoW_QuestEN[91828] = { title = "A Favor for the Lion", description = "A letter arrived for me. No seal, no name. Just folded parchment and handwriting I'd recognize anywhere.\n\nIt didn't say much. He never wastes words. \n\nI've known his family a long time. When they reach out, I answer.", objectives = "Read the letter and assist Valeera Sanguinar in Zul'Aman.", progress = "Yes?", completion = "I've been watching the path. Movement's light, at least for now." }
WordHunterWoW_QuestEN[91829] = { title = "One by One", description = "Every last cultist is a threat to the people we're trying to save. To Silvermoon itself.\n\nBlasted fanatics with blood on their hands and no intention of letting anyone walk out alive.\n\nWe're already in the camp. Let's make it count. I want them to feel this.", objectives = "Kill cultists of the Twilight's Blade at Speaker's Rest.", completion = "Clean work. The kind they don't come back from." }
WordHunterWoW_QuestEN[91830] = { title = "Intercepted", description = "The Twilight's Blade hit Tranquillien hard. Slipped in and took all the supplies and information they could ever need, right beneath everyone's nose.\n\nTime to return the favor.\n\nI've marked a few tents. Command posts, messengers' satchels, a supply ledger tucked under a wine crate. That's where they keep their orders, maps, and routes.\n\nGrab everything you can.", objectives = "Collect 6 Cult Orders from the Twilight's Blade camp at Speaker's Rest.", progress = "The right scrap of parchment can win a war. Or start one.", completion = "Now this is useful. Let's see how well their little operation runs when they're chasing ghosts and missing crates." }
WordHunterWoW_QuestEN[91831] = { title = "Keys Are Optional", description = "These people joined the Twilight's Blade looking for purpose, power, or place to belong. For a reprieve from the fear and a promise of certainty.\n\nNow they see it for what it is--a prison dressed up as faith. And they want out.\n\nWe go in together. Get them out before the cult realizes what's happening.", objectives = "Find and release 4 groups of Cult Deserters in Speaker's Rest.", progress = "Ready yourself. This might get messy.", completion = "That should be all of them." }
WordHunterWoW_QuestEN[91833] = { title = "Dirty Deeps", description = "De Vilebranch are sinkin' deeper into their cursed minds. Dey spit in de face of de loa, and believe dey have mastered death.\n\nI could see a certain... someone not likin' dat way of thinkin'.\n\nDey have taken our kin and now dey take our shaman. Meet my scout there and help dem break their plans.\n\nCut de head off de beast and de body will fall.", objectives = "Meet the Witherbark Scout at Maisara Deeps.\n\nProvided item:", completion = "Good timing, <race>! These hex masks are wicked powerful.\n\nWhatever VunVun sends our way, we will find a use." }
WordHunterWoW_QuestEN[91834] = { title = "Guardians Must Go", description = "Get rid of shield face and meet me in de hut below.", objectives = "Kill the Dark Hex Guardian and meet me below.\n\nProvided item:" }
WordHunterWoW_QuestEN[91835] = { title = "Send Dem Home", description = "My friend, dis is a mighty gift. Shadra is givin' us a blessin' for de tasks ahead.\n\nThese Vilebranch really are livin' up to their name. Dey drain de spirit from de Witherbark and create undead to serve dem.\n\nWe must free de Witherbark from these necrotic bonds.\n\nMy friend's still in there... I hope. Me and Bin'zin cut our tusks together growin' up. He grew into a strong shaman. Our village needs him, and he is like a brother to me.", objectives = "Free 8 Witherbark Prisoners.", progress = "Are the prisoners safe?", completion = "Oh, yes, <name>!\n\nIn one blow, there are more of us and less of dem!\n\nWe best make dem too afraid to ever take Witherbark again." }
WordHunterWoW_QuestEN[91836] = { title = "Respect de Totem", description = "When dey took Bin'zin, de priestess destroyed his totems and gave de shattered remains to her minions--like some grisly memento.\n\nTake de pieces back, one by one if ya have to. Dat disrespect will not stand.", objectives = "Collect 40 Totem Remnants.", progress = "How goes de lootin'?", completion = "In a world of horrors, we must enjoy de good we feel for causin' dem trouble.\n\nThese pieces will go back where dey belong.\n\nYa played it well, <name>." }
WordHunterWoW_QuestEN[91837] = { title = "Bring Back De Bones", description = "Big thanks for breakin' us free. Some were not so lucky.\n\nBring dey bones back to de Chief, he will know what to do.", objectives = "Collect 8 Bones of de Fallen." }
WordHunterWoW_QuestEN[91838] = { title = "De Vile Diminished", description = "These vile orbs are harvestin' de souls of our people and sendin' dark energy to de Knife Priestess. She's gettin' mighty powerful.\n\nDestroy de orbs so her ritual of death is ruined. With de gift of Shadra, ya will not fail.", objectives = "Destroy 5 Vile Orbs.", progress = "Did ya find all de orbs?", completion = "Do ya sense it? De death energy dat was oozin' about de place feels thin.\n\nIt will take but a breath to end dis ritual for good." }
WordHunterWoW_QuestEN[91839] = { title = "Sacrifice Denied", description = "Our shaman is home and Jin'zin's full of joy to see him again. She was always his little wildcat apprentice.\n\nDey will have sad moments--Tan'zin is a mighty loss.\n\nToday, ya brought him home. Go enjoy dat for a bit, {name}, before ya be on ya way.", objectives = "Check on Bin'zin.", completion = "All of this is my own fault. De Vilebranch so close to de village... I shoulda been more aware.\n\nMy mate leapt in de way of a death meant for me. \n\nOne moment I'm angry, then I feel de guilt for it, and de sorrow takes' over.\n\nAt de end of de day, I'm keepin' a strong face for Jin." }
WordHunterWoW_QuestEN[91840] = { title = "One Will Not Rise", description = "Now's our best shot! We end de sacrifices here! Stoppin' de dark energy has weakened her hold.\n\nThen, you can be de one to bring back her head.\n\nUh, and {name}--no tellin' de chief about me callin' him Big VunVun. He'll be turnin' me into a frog if he hears dat again.", objectives = "Deliver the head of Knife Priestess Hezzia to Vun'zarah in Witherbark Bluffs.", progress = "I am pleased you're takin' my words so literally.", completion = "Ah! My day's gettin' better already! De Witherbark are grateful, <name>.\n\nDak'zor didn't say... nevermind. I don't wanna know." }
WordHunterWoW_QuestEN[91842] = { title = "Disarm the Dark Horde", description = "The Dark Horde have no love fer their equipment. Look at their weapons! Cracked, rusted, blunt, and bent. Ach!\n\nThe only way they function is by making more shoddy tools to constantly replace the ones they've broken.\n\nIf ye see any of their weapon racks, destroy 'em. Let's see how well they fight without their rusty blades.\n\nA bare-fisted orc is nothing to sneeze at, but it'll further delay any daft plans they've got.", objectives = "Destroy 8 Dark Horde Weapon Racks.", completion = "Did ye destroy their weapons racks?\n\nAye, that'll do. We've bought everyone nearby a few months of peace while they resupply." }
WordHunterWoW_QuestEN[91843] = { title = "Recap: The Harbinger", description = "To understand the story of The War Within, one must first begin with the mysterious entity known as the Harbinger, and how the heroes of Azeroth uncovered the truth...", objectives = "Read along with the Tome of History and learn about the events which sparked The War Within.", progress = "Xal'atath was a mysterious foe with ties to the Void. Her presence portended dire things for Azeroth...", completion = "Alleria uncovered the mystery of the Harbinger, revealing Xal'atath. However, it would not be long before the Harbinger made her move." }
WordHunterWoW_QuestEN[91844] = { title = "Infinite Research Promotion: Honorary Chronographer", description = "", objectives = "<name>, you have been an excellent assistant with our research. I think you deserve a promotion.\n\nFrom now on, you will be able to take on more research assignments simultaneously.\n\nIt's ironic, isn't it, that we never seem to have enough time. Make good use of your time here. Don't make me regret granting you this power.This quest line will unlock:" }
WordHunterWoW_QuestEN[91845] = { title = "Infinite Research Promotion: Senior Executive Chronographer", description = "", objectives = "<name>, you have been an excellent assistant with our research. I think you deserve a promotion.\n\nFrom now on, you will be able to take on more research assignments simultaneously.\n\nIt's ironic, isn't it, that we never seem to have enough time. Make good use of your time here. Don't make me regret granting you this power.This quest line will unlock:" }
WordHunterWoW_QuestEN[91846] = { title = "Infinite Research Promotion: Principal Chronoquery Investigator", description = "", objectives = "<name>, you have been an excellent assistant with our research. I think you deserve a promotion.\n\nFrom now on, you will be able to take on more research assignments simultaneously.\n\nIt's ironic, isn't it, that we never seem to have enough time. Make good use of your time here. Don't make me regret granting you this power.This quest line will unlock:" }
WordHunterWoW_QuestEN[91847] = { title = "Infinite Research", description = "", objectives = "" }
WordHunterWoW_QuestEN[91848] = { title = "Infinite Research", description = "", objectives = "" }
WordHunterWoW_QuestEN[91849] = { title = "Infinite Research", description = "", objectives = "" }
WordHunterWoW_QuestEN[91854] = { title = "Deepening Shadows", description = "Champion, I could use your assistance. The natives here in Silvermoon are proving to be less hospitable than we had hoped. \n\nIn their defense, their city is facing down a darkness unlike anything Azeroth has ever faced, so tensions are high.\n\nCan you use your unique perspective and help de-escalate some of the hot spots that are emerging around Silvermoon?", objectives = "De-escalate rising tensions in Silvermoon City.", progress = "Tensions are high.", completion = "Well done. That Voidstorm is evoking fear and terror in everyone who sees it, myself included. \n\nBut I chose this life of standing up to evil and spitting in its face. Sadly not everyone had the luxury of that being a choice." }
WordHunterWoW_QuestEN[91855] = { title = "Worldsoul: K'aresh World Quests", description = "I know now that the heroes of Azeroth venture wherever help is needed. K'aresh is a strange, faraway place, but our allies there need us.\n\nGo there and help them. See what you can do to bring respite to the ethereals and brokers.", objectives = "Complete World Quests in K'aresh.", progress = "Our allies resist valiantly on a dead and shattered world. I admire them.", completion = "You are a credit to heroes everywhere. Thank you." }
WordHunterWoW_QuestEN[91863] = { title = "My First Home", description = "Welcome to the neighborhood! Feel free to explore and have a look at the plots available.\n\nSpeak to the steward to learn more about the process of becoming a homeowner or if you wish to create your own neighborhood.", objectives = "Familiarize yourself with the neighborhood and its residents, and then find a place to build a house.", progress = "Have you found your forever home?", completion = "Congratulations on acquiring your new house. We know you'll be very happy here and we look forward to seeing you around the neighborhood." }
WordHunterWoW_QuestEN[91864] = { title = "Recap: Fractured Visions", description = "All across Azeroth, many were having visions of a Radiant Song. Efforts to understand what seemed to be a warning centered on the heroes in Dalaran.", objectives = "Consult the Tome of History to learn about the fate of Dalaran in The War Within.", completion = "The island of Khaz Algar figured into Xal'atath's plans, and it was up to the champions of Azeroth to thwart them." }
WordHunterWoW_QuestEN[91865] = { title = "Catch Up: Khaz Algar", description = "The Earthen of Khaz Algar eventually welcomed the outsiders into their land, but all was not well with them. Divisions had grown among their people. To unravel Xal'atath's plot with the Nerubians, the Champions would have to address these issues.", objectives = "Consult the Tome of History to learn about the events in Khaz Algar in The War Within." }
WordHunterWoW_QuestEN[91866] = { title = "Catch Up: The Ringing Deeps", description = "The Champions travel with Brinthe of the Earthen and Moira, Dagran and Magni Bronzebeard to the Ringing deeps. There they find not all is well as a mysterious affliction has touched some of the workers.", objectives = "Consult the Tome of History to learn about the events in the Ringing Deeps in The War Within." }
WordHunterWoW_QuestEN[91867] = { title = "Catch Up: Hallowfall", description = "King Anduin Wrynn, Alleria and the Champions travel deeper into Azeroth, arriving at a place known as Hallowfall. It quickly become apparent that this place has also been touched by the machinations of Xal'atath.", objectives = "Consult the Tome of History to learn about the events in Hallowfall in The War Within." }
WordHunterWoW_QuestEN[91868] = { title = "Recap: Shadowy Pursuits", description = "King Anduin Wrynn, Alleria, and the champions travel deeper into Azeroth, arriving at a place known as Hallowfall. It quickly becomes apparent that this place has also been touched by the machinations of Xal'atath.", objectives = "Consult the Tome of History to learn about the events in Hallowfall and Azj-Kahet in The War Within.", completion = "With a few select allies, Anduin, Alleria, and the champions escaped Xal'atath's clutches, but this would not be the last encounter with her..." }
WordHunterWoW_QuestEN[91869] = { title = "Catch Up: A Light in the Dark", description = "The War Within continued on Khaz Algar as the peoples of the land began to unite against Xal'atath and her Dark Heart.", objectives = "Consult the Tome of History to learn about the events in The War Within." }
WordHunterWoW_QuestEN[91871] = { title = "Recap: The Dark Heart", description = "The champions and Alleria were invited to Undermine by Gazlowe as the peoples of Khaz Algar and beyond began to unite against Xal'atath and her Dark Heart.", objectives = "Consult the Tome of History to learn about the events in Undermine and K'aresh in The War Within.", progress = "Dimensius was defeated and Azeroth was saved from his threat, yet there was a cost.", completion = "This is the conclusion of The War Within, but it is not the last time we'll see Xal'atath or the Dark Heart..." }
WordHunterWoW_QuestEN[91872] = { title = "The Former Rootwarden", description = "{name}, I was the Rootwarden of Teldrassil. For years, I watched the roots here below the surface, but I was not aware of what was threatening the tree outside of Harandar.\n\nFor just as long, I have regretted that failure, but we cannot change the past.\n\nI wonder, however, if roots so great may still have life within them. Might there be something which can still be done?\n\nI do not know, but I do hope. Will you join me at the Shrine of Ages, to tend the roots?", objectives = "Meet Hagar at the Shrine of Ages.", completion = "I lived far longer before I became Rootwarden than after.\n\nYet Teldrassil will always be what defines my life." }
WordHunterWoW_QuestEN[91873] = { title = "Buffer Zone", description = "At this shrine, I have worked to gather roots that seem to still have the possibility of life within them. They are each greatly damaged, some more than others. My hope is some might recover, with enough time and enough care. In that way, I honor the great tree's memory.\n\nFor that to be possible, though, we have to keep them safe from the hazards of Harandar.\n\nPlease be sure that nothing nearby threatens them.", objectives = "Protect the shrine from local wildlife.", completion = "Thank you for helping to protect what may still live of Teldrassil.\n\nIt may be that nothing remains. Some of these roots still smolder.\n\nYet I vowed to serve as Rootwarden, and I will not fail a second time, if there is any hope. I choose each day to believe there may be--that Teldrassil could bloom again.\n\nThough I may only be preserving her memory." }
WordHunterWoW_QuestEN[91874] = { title = "Flare Up", description = "{name}, I see smoke rising above Har'mara. The roots are on fire--not here, but beneath the remnants of the tree!\n\nI have seen this happen many times, but we must always respond with haste.\n\nTake to the skies and douse them, immediately!", objectives = "Fly near the flames on the roots of Teldrassil to douse them.", completion = "<name>, the smell of smoke fills me with the same dread I felt on that terrible day.\n\nThere is much heat still trapped within the largest roots, and in the right circumstances, the burning begins anew.\n\nIf we have any hope of seeing the roots restored one day, we have to be vigilant against even small fires.\n\nAt best, they undo our work, but at worst, they could spread to consume what remains.\n\nThank you for helping me keep watch." }
WordHunterWoW_QuestEN[91875] = { title = "Natural Remedy", description = "If we ever hope to see new growth, Teldrassil's roots needs a great deal of special attention.\n\nThe source of this stream is one of the great roots. The water carries ash, which I believe still contains the tree's essence.\n\nThe stalkers in the stream carry a mixture of that ash and slime from their tendrils--a very potent mixture.\n\nBring me as much of it as you can carry, and I will combine it with reagents I've gathered. Then we'll be ready to apply it to the roots.", objectives = "Gather 8 clumps of Verdant Stalker Sludge.", progress = "Do you have the rejuvenating mud I asked for?", completion = "This will do nicely, for today. Just give me a moment to mix...\n\n<name>, do you smell smoke?" }
WordHunterWoW_QuestEN[91876] = { title = "Tending Hope", description = "Thank you for tending to those fires, {name}. While you were gone, I've used that sludge to make a salve. Help me spread it over Teldrassil's roots.\n\nIt may take years to see a difference, if we ever do. But though I failed, I made oaths to her, and I can still choose to keep them. I will never stop doing what I can to... help her perhaps grow again.\n\nIf I do not succeed, the next Rootwarden, or the one who comes after that, may be the one to finish this work. Even so, I shall not stop trying.", objectives = "Apply Hagar's salve to 12 Withered Roots.", completion = "Thank you, <name>, for your help. Because of you, I was able to keep up my routines even with those fires.\n\nPerhaps one day, we might see a sprout--even if it takes many years.\n\nAnd I shall be ever ready to resume my duties as Rootwarden, should hope bloom." }
WordHunterWoW_QuestEN[91884] = { title = "The Illusion of Motion", description = "You! Have YOU seen them?\n\nI've been tasked to investigate some of our scouts that have gone missing. My reconnaissance had come up empty until recently.\n\nNow I've been catching glimpses of the missing scouts, but... they appear formed of pure Void energy.\n\nEach time I chase the figures, they lead me further and further before disappearing!\n\nThe others think I'm crazy. You haven't seen anything like that, have you?", objectives = "Investigate the mysterious figures Nefina has seen around Locus Point.", completion = "Do you see them? Their cries for help... echoing... all around..." }
WordHunterWoW_QuestEN[91885] = { title = "Drain You", description = "Do you... see...? They follow... They plead... for help...\n\n<The voidwalker strains and shudders as it tries to communicate.>\n\nToo weak... too starving...\n\n<It feebly hands you a shard of dark matter.>\n\nThis... will feed me... then together... we find the missing elves...", objectives = "Slay Voidstorm wildlife and use the Void Splinter to feed the Starving Voidwalker.", completion = "I am better now... stable, but a fatigue still clings to me.\n\nIf we're to find your scouts, I will need your help." }
WordHunterWoW_QuestEN[91886] = { title = "Voices of Omens", description = "The voices of your elven allies rattle inside my head.\n\nI know of a way we can find them. There is a way to locate missing things... using old domanaar scanning devices.\n\nBut they require immense energy to function. Together, we can use these devices to focus the images of your lost friends. Their cries for help will become clearer, and then you can find them.\n\nCome. Lend me your strength.", objectives = "Help the Sentient Voidwalker power Domanaar Scrystones to help locate the missing scouts.", completion = "The voidwalker's been feeding on us all the while... but why the misdirection? Whatever the case may be, it's time to end this.\n\nAnd this time, WE will have the element of surprise." }
WordHunterWoW_QuestEN[91887] = { title = "Dominion of Deceit", description = "We were right to be cautious. The threats we've found here in the Voidstorm are corrupting and irredeemable.\n\nThis voidwalker's meticulous deceptions are unusual... I can't help but wonder why it would go through all the trouble. \n\n<She looks up at you from weary, withered eyes.>\n\nBut I'm too weak to go on. It really did a number on me. You have the upper hand now! It thinks you're walking into its trap.\n\nWalk in with weapons drawn and spells ready!", objectives = "Slay the Deceitful Voidwalker.", completion = "The creature ensnared so many of us in its web of lies.\n\nWe must remain steadfast. The Voidstorm is a terribly hostile place." }
WordHunterWoW_QuestEN[91918] = { title = "Delves: Measure Once, Cut Twice", description = "We've done well to see those deserters to safety, but don't fool yourself into thinking we've freed them all.\n\nI've heard whispers of a place they use to break those whose loyalty is in question. The location isn't common knowledge, but I know where to start looking.\n\nIf we're quick, we might find others before the cult decides they're too great a risk to keep alive.\n\nMeet me near the site. Keep your blades sharp and your steps light.", objectives = "Rescue the remaining Twilight's Blade Deserters from the Twilight Crypts delve on any difficulty.", completion = "That's all of them. Good work." }
WordHunterWoW_QuestEN[91927] = { title = "Ooze Booting", description = "", objectives = "" }
WordHunterWoW_QuestEN[91928] = { title = "What's For Lunch?", description = "My Shadowtrade Mercenaries will fight for Stormarion Cores, no questions asked, but they do get hungry also!\n\nFood is quite scarce here, so we need supplies!\n\nTake a mercenary out with you and find some food for them to eat. I'll make it worth your while!", objectives = "Slay Trigores for 3 Trigore Flanks and collect 20 Shadow-Grown Berries that grow in the area." }
WordHunterWoW_QuestEN[91929] = { title = "What's For Lunch?", description = "My Shadowtrade Mercenaries will fight for Stormarion Cores, no questions asked, but they do get hungry also!\n\nFood is quite scarce here, so we need supplies!\n\nTake a mercenary out with you and find some food for them to eat. I'll make it worth your while!", objectives = "Slay Unstable Oozeling for 12 Void Malgrease and collect 3 Domanaar Microwell." }
WordHunterWoW_QuestEN[91930] = { title = "The Abundant Lands", description = "De loa have reunited with us forest trolls, and de land reacts with glorious bounty!\n\nDo ya wish to take part? Then go north, and meet me at de entrance to Loaknit Den.\n\nThere I will introduce ya to prosperity and plentitude like ya never seen...", objectives = "Speak with Chel the Chip at Loaknit Den in Zul'Aman.", completion = "It is time to learn from de master himself." }
WordHunterWoW_QuestEN[91932] = { title = "The Abundant Awakening", description = "De Loa of Abundance accepts everyone, and everyone de Loa of Abundance accepts is granted de privilege of learnin' how best to serve abundance.\n\nSpeak with his glorious visage and become a fellow acolyte.", objectives = "Speak with the Loa of Abundance and learn the ways of harvesting abundance.", progress = "Do not fear. I am indeed the finest judge of your every action and choice.", completion = "Quite acceptable!\n\nYou may yet prove a glorious addition to the acolytes of abundance." }
WordHunterWoW_QuestEN[91933] = { title = "The Abundant Honor", description = "On to the next phase of your education: mercantilism!\n\nImagine yourself, offering the bounty of endless harvest to my glorious self, and reaping the abundant rewards I bestow upon you in kind.\n\nNow let us put that beauteous vision into practice! \n\nI will grant you a minute portion of unalloyed abundance. You, in turn, shall trade it to your fellow acolyte for one of many premium goods.", objectives = "Purchase an Abundant Beacon from Chel the Chip.", progress = "There are few things amongst mortals or gods that cannot be viewed through the lens of trade.\n\nSome of us are simply... less coy about that truth than others are.", completion = "Ah! I see you are already well-versed in the art of barter and trade!" }
WordHunterWoW_QuestEN[91937] = { title = "Portraits in the Vale", description = "", objectives = "" }
WordHunterWoW_QuestEN[91954] = { title = "Freezing Over", description = "", objectives = "We noticed this large creeper tracking you out in the wastes, but when it emerged it made no aggressive moves whatsoever. Judging by its reaction to your arrival, I believe you're the one its been looking for. You're becoming quite popular, no?" }
WordHunterWoW_QuestEN[91955] = { title = "Just Between Us", description = "The artifact we snatched from the timeline earlier was replaced with a simulacrum so none would notice the true artifact's absence.\n\nSuch a wealth of infinite energy should not be abandoned so readily. You should seek it out and reclaim it.\n\nOnce you have recovered the simulacrum you can scrap it for an embarassing sum of bronze and infinite power.", objectives = "Retrieve the Curious Simulacrum left in place of your \"borrowed\" artifact weapon by completing your artifact weapon's acquisition storyline as part of your Order Hall campaign.", completion = "Success!\n\nIt's almost a shame to destroy such a beautiful replica.\n\nBut you have the real thing, so I say scrap it and rejoice at the bounty of beautiful bronze!" }
WordHunterWoW_QuestEN[91958] = { title = "Den of Nalorakk: Unforgiven", description = "Nalorakk is de Loa of War. His trial must be a battle!\n\nThere would be no greater death for an Amani than to die in combat against de Loa of War. No greater thrill than fightin' him.\n\nDoes it not make your blood pump faster and harder in your veins, hash'ura?\n\n<Zul'jarra lets out a feral howl and laughs.>\n\nCome. Meet me at Nalorakk's Prowl and we will sit at his fire and face our last trial--together.", objectives = "Complete the Den of Nalorakk dungeon.", progress = "De final trial is at hand.", completion = "Heh.\n\nWe won against Nalorakk. We passed de last trial.\n\nMy tribe will sing songs and tell stories of dis day for generations." }
WordHunterWoW_QuestEN[91963] = { title = "Running Amok", description = "I've heard from the other scouts about that metal--the shadowgraft. The domanaar use it to enforce their control over others.\n\nI have to imagine that there's someone holding the reins still. Maybe it's Xal'atath, or maybe someone else. Gather pieces of their shadowgraft and maybe we can make sense of who.", objectives = "Gather Shadowgraft from foes at Obscurion Citadel.", progress = "Have you gathered enough for us to study?", completion = "There are multiple styles of shadowgraft in the samples you collected. It seems like there are multiple domanaar vying for control of the power vacuum left here in Obscurion. Xal'atath must not be in command here.\n\nWe'll take care of this one foe and let the rest of the domanaar fight among themselves." }
WordHunterWoW_QuestEN[91966] = { title = "Saltheril's Soiree", description = "", objectives = "" }
WordHunterWoW_QuestEN[91967] = { title = "You Know This Evil?", description = "Champion, we have a bit of a delicate situation.\n \nThe Vanguard of the Light has just informed me they have taken Magister Umbric into custody. Apparently he was trying to get close to the Sunwell.\n\nI do not have to tell you that tensions are high between my city and the Vanguard. We need Umbric to continue his research if we are to have a chance at contending with the Voidstorm.\n\nI want you to represent me in negotiating Umbric's release. Whether we like him or not, we need him.", objectives = "Negotiate with the Vanguard of the Light for Magister Umbric's release.", progress = "Umbric is necessary. So is the Vanguard. \n\nI have a lot of necessary and unsavory elements to deal with these days, but I will do so if it means my people are safe.", completion = "Thank you for your intercession. While I prize myself on doing what is necessary for Silvermoon and the Sunwell, I have a feeling my own patience would have worn thin and I would have said something that all of us would have regretted." }
WordHunterWoW_QuestEN[91968] = { title = "Welcome Home", description = "What a mess! Perhaps the previous owners left in a hurry. Best tidy up!\n\nThe items removed will be sent to the house chest. They can always be placed down again, if cobwebs are your thing.", objectives = "Pick up objects in your house." }
WordHunterWoW_QuestEN[91969] = { title = "Time to Decorate", description = "Now that we've got this place tidied up, let's decorate!\n\nThe community has chipped in with donations to make sure you have plenty of options to work with.\n\nLet's have a look!", objectives = "Decorate your home." }
WordHunterWoW_QuestEN[91970] = { title = "WANTED: Gelatonius", description = "Are you ready to test yourself against a true foe? In the center of the Gloom Mire is Gelatonius, a fungal giant of enormous proportions. \n\nKill him, if you think you can. I'm willing to be impressed, and to pay handsomely for this task.", objectives = "Kill Gelatonius in the Gloom Mire.", completion = "You return in one piece? Not bad, outsider. Not bad." }
WordHunterWoW_QuestEN[91971] = { title = "Hitting the Hammer", description = "The Twilight Hammer is dirtying up the ruins of Zeb'tala. Clean up the area and bring back some of their personal tokens. One never knows what curiosities may appeal to those vying for relevancy.\n\nThose mindless cultists may stomp around and act tough, but you will make quick work of them.", objectives = "" }
WordHunterWoW_QuestEN[91972] = { title = "Hold the Watch", description = "There is still a lot of friction on the border with Zul'Aman, but we must hold the watch on all fronts.\n\nCheck in with Bloodguard Nelric at the Thalassian Pass. It is rumored to be one of the most uneventful posts. I am certain he would appreciate a reprieve, if only for a few moments.\n\nStay alert, {name}!", objectives = "Check in with Bloodguard Nelric at the Thalassian Pass and hold the watch.", completion = "An uneventful watch is more rewarding than an empty conversation.\n\nThe Blood Knights appreciate your service." }
WordHunterWoW_QuestEN[91973] = { title = "Naga Blades", description = "It seems the locals currently find great appeal in naga blades--the brinier the better. On our southwestern shore, you will find the Daggerspine naga.\n\nThey have these grungy, barnacle-encrusted scimitars that would perfectly fit the bill.\n\nGo grab a few of those. They could have value in some of our upcoming discussions.", objectives = "" }
WordHunterWoW_QuestEN[91974] = { title = "Sunfire to the Blade", description = "I guess there is one benefit to being part of the courtly intrigue: one does hear things. We have this concoction of sunfire infused with the holy energy of the Blood Knights, courtesy of the court alchemists.\n\nTake this down to the Sanctum of the Moon and test it on the Twilight intruders. I look forward to hearing the results in detail.", objectives = "Kill 10 Twilight intruders at the Sanctum of the Moon with Holy Sunfire.", completion = "Anar'anel belore! You love to hear it. This news is sure to warm a few hearts for our cause." }
WordHunterWoW_QuestEN[91975] = { title = "That's Our Wood", description = "It seems the lure of the lightwood continues to be a problem.\n\nWe may as well take advantage of the trolls' hard work! Collect what they have harvested. We can make use of it.\n\nWhat we do not use for weapons, we can hand over to the carvers. The nobles will clamor over lightwood decor.", objectives = "" }
WordHunterWoW_QuestEN[91976] = { title = "Lightbloom Dimmed", description = "All of this small talk makes my ears twitch. I would be so much more useful doing field work. For now, you get to do the fun part.\n\nThe creatures within the Lightbloom are getting a bit dense. I need you to get out there and lower the volume.\n\nI am sure you'll run into many options while you are out there. Take a whack at a few for me.", objectives = "Kill Lightbloom creatures.", completion = "You have performed well. Silvermoon appreciates your service.\n\nI would have happily swapped places with you, but we all have our assignments." }
WordHunterWoW_QuestEN[91977] = { title = "Less Lawless", description = "The Tideborne are always running just over the legal line. They are an annoyance at best, but will push boundaries when given too much rope.\n\nThe ones in Sunsail Anchorage made the mistake of ripping off some nobles not too long ago. Maybe go smack them around a bit--remind them to respect their betters.", objectives = "Chastise 8 Tideborne.", completion = "Ah, that must have been such fun! My bar may be lower today, after the engrossing discourse on the harvesting cycle of the basic peacebloom.\n\nApologies. Know your service is appreciated." }
WordHunterWoW_QuestEN[91978] = { title = "Taxing the Tideborne", description = "Have you ever noticed, that sometimes there is benefit in letting someone think they are getting away with something? The Tideborne will continue to smuggle in plain sight, feeling clever at the taxes they're avoiding paying to Silvermoon.\n\nThis does add up, though, over time. When you have a moment, please head down to the harbor and relieve them of some of their back taxes.", objectives = "" }
WordHunterWoW_QuestEN[91979] = { title = "Chop It Down", description = "We received word there's a creature from Lightbloom Ath'Ran making trouble on the western coast. It has caused a bit of drama.\n\nHead over and resolve the issue.", objectives = "Kill the Rampaging Ent near Lightbloom Ath'Ran.", completion = "Good work. I'm sure that will make for some excellent kindling." }
WordHunterWoW_QuestEN[91980] = { title = "WANTED: Hellebora's Thorn", description = "See that huge creature over that way? That's Hellebora. She's set herself up too close to the road and we're concerned she's going to wander out of the mire and become even more of a threat. \n\nDeal with her, if you can, and bring me back one of her thorns as proof of your hunt.", objectives = "Kill Hellabora.", progress = "Hurry up and put Hellebora down before she wanders out of the mire.", completion = "You return with her thorn? Ah yes, a fine trophy. Well done." }
WordHunterWoW_QuestEN[91982] = { title = "WANTED: Toadshade's Petals", description = "The three-headed hydra, Hellabora, has been causing havoc in the lower end of Gloom Mire.\n\nGive her a good pruning and bring me back her petals as proof.", objectives = "Collect petals from Toadshade.", progress = "Less talking, more pruning. Go get those petals.", completion = "You've the petals? Let's take a look. Yes, these are from that hydra. Good work." }
WordHunterWoW_QuestEN[91983] = { title = "Lovely Plumage", description = "The beautiful members of the Silvermoon Court do so love their colorful embellishments.\n\nFor this, we can stock up while doing a good deed! Head over to Thuron's Livery and pick up some of the brightly colored feathers shed from the hawkstriders in training.\n\nVaelith gets clean up service and we get the lovely plumage.", objectives = "Collect 8 Bright Feathers.", progress = "Did you find loads of feathers?", completion = "You are so good at this!\n\nOne of these days, we should pile these feathers up and let everyone jump in them. I think you would be surprised how many proper lords and ladies would gleefully participate.\n\nFor now, we will explore feathery accents." }
WordHunterWoW_QuestEN[91984] = { title = "Sungrub Silk", description = "Oh, {name}, have you ever visited the Solaarian Sunbath? If not, it's highly recommended.\n\nThe sungrubs that wander nearby have a precious silk from which amazing fabric can be made. Solwin Brightstitch is reputed to be masterful in this, with his sartorial magic.\n\nThe raw materials are often sought out to have him create unique and personalized goods from scratch. Bring us some of that lovely silk. It will provide a soft cushion when faced with harder discussions.", objectives = "" }
WordHunterWoW_QuestEN[91985] = { title = "Windrunner Memorabilia", description = "The nobles do so love the unusual. Take a look around Windrunner Village. There are sure to be some interesting mementos still tucked away there.\n\nI will find an advantageous home for the pieces you bring back.", objectives = "" }
WordHunterWoW_QuestEN[91986] = { title = "Put a Little Snap in Their Step", description = "Those naga are, as ever, being a beachfront nuisance. Do they not understand that is a prime location?\n\nWe may not be able to reliably drive them off, but a little mischief would not be untoward.\n\nI found this tune that drives the snapdragons mad. They will just attack whoever is nearby. Take this and give it a shot!", objectives = "Drive 8 Daggerspine Snapdragons mad with a tune.", completion = "I feel bad for the snapdragons, but I can't help but laugh at the look of surprise on their face when their little buddies pounce on them.\n\nThank you for making the day a little more entertaining." }
WordHunterWoW_QuestEN[91987] = { title = "Potted Lashers", description = "It seems some of the nobles are botany-curious where the Lightbloom is concerned. They seek the exotic to adorn their windowsills and lurk in the dangerous section of their greenhouses.\n\nThat's where you come in, {name}!\n\nGo harvest those small and pernicious plants. Their bulbs will be the best for planting.", objectives = "Collect 8 Lightblooming Bulbs.", progress = "Any problems with the harvest?", completion = "The results of sharing these with the Silvermoon elite could range from passably amusing to disastrous.\n\nEither way, I look forward to seeing the results of their gardening efforts." }
WordHunterWoW_QuestEN[91988] = { title = "Brightwing Conservation", description = "The conservators at Brightwing Estate have a mischievous young dragonhawk named Cerul that likes to run away whenever their backs are turned. He doesn't go far, but it has become a game for him to get them to chase him.\n\nTake this delicious treat with you and use it to lure him back home.", objectives = "Lure Cerul back to his home in Brightwing Estate.", completion = "It makes everyone happy to have all the creatures home at Brightwing. Having a peaceful place to enjoy the coast is a benefit to all.\n\nThank you for letting Cerul enjoy a little play time!" }
WordHunterWoW_QuestEN[91989] = { title = "Ghostland Peppers", description = "The delicate blue ghostland peppers may not look like much, but they have a mean burn. Many nobles won't admit it, but they are quite popular in the noble games of \"Truth or Challenge.\"\n\nPlease procure a few for me. I like to watch them sweat.", objectives = "" }
WordHunterWoW_QuestEN[91990] = { title = "Sunset to Sea", description = "Naga have set up camp on the Sunset Strand. The sunset slugs that called it home are distraught and seem unsure what to do. This little tune will remind them of their home.\n\nGo inspire them to seek the freedom of the open sea.", objectives = "" }
WordHunterWoW_QuestEN[91991] = { title = "A Little Errand", description = "When conversations get tense, it can be challenging to keep words flowing in a productive way. At times like these, I find a little social lubrication is in order.\n\nSwing over to Goldenmist Village and pick up a cask of Vintner's Golden. It's proven to have a euphoric side effect that can be quite helpful.", objectives = "" }
WordHunterWoW_QuestEN[91992] = { title = "Where Has the Wine Gone?", description = "I entrusted one of my apprentices with the delivery of several cases of particularly expensive wine. He was to bring them here from my private storage, but he has not yet arrived.\n\nI should hate to ask you to retrieve him, but I cannot stress enough how expensive those bottles are.\n\nPlease see if you can locate him and my delivery. He should have been traveling from the north to arrive here.", objectives = "" }
WordHunterWoW_QuestEN[91993] = { title = "Diminutive Demand", description = "Keeping preciously small animals as pets is a popular pastime among the nobility. The more unconventional the animal, often obtained through magic, the more of a conversation piece it is.\n\nI have enchanted this wand with the appropriate shrinking spell. Use it on some of the colorful toads out near the ponds and bring them back here. The nobles will find them delightful.\n\nNaturally, the toads may not take kindly to the enchantment. But I trust you can handle that, should it occur.", objectives = "Using the Wand of Diminutive Proportions, shrink and capture 4 Gloombelly Toads near Stillwhisper Pond.", completion = "Oh, they are positively precious, are they not?\n\nI imagine we will see quite a few miniscule toads in handbags this coming season." }
WordHunterWoW_QuestEN[91994] = { title = "Pyrepetal Purposes", description = "Lord Saltheril, that old lynx, has put me in a bit of a bind.\n\nHe has requested a grand fireworks display to accompany tonight's dinner service, but we are dreadfully low on pyrepetal dust. It is an herb native to Eversong, highly flammable and quite dazzling when set aflame by pyromancy.\n\nCould you help us replenish our stores? We mostly harvest it from the woods near Scintilas Falls.", objectives = "" }
WordHunterWoW_QuestEN[91995] = { title = "What Horrible Magic", description = "Have you seen the encampments the naga have been constructing along our coast? Dreadful business.\n\nNot only do they menace our ships and disrupt our trade routes, but they might pose a real threat to Eversong's inland settlements if allowed to continue operations unchecked.\n\nTheir arcanists are particularly dangerous. Dispose of them and our guests will be in your debt.", objectives = "" }
WordHunterWoW_QuestEN[91996] = { title = "Fit for a Magister", description = "Battle prowess and magical skill are important, of course, but one cannot deny the power of appearances. A well-dressed army instills far more faith than one bedecked in rags.\n\nFortunately, a fine set of robes can be both flattering and functional. The mana silk produced at the North Sanctum can be woven into robes that deepen and intensify our magical reserves.\n\nBe a dear and gather some for us, would you? My wardrobe could use a seasonal refreshment.", objectives = "" }
WordHunterWoW_QuestEN[91997] = { title = "Power Clean", description = "The festivities have been wonderfully entertaining, which means the nobles have been leaving a bit of a mess around the estate. Lord Saltheril's servants have been keeping up with the cleaning, but the Magisters could lend a hand.\n\nEnchanting a few brooms to sweep the pavilion should be an easy but impressive feat.\n\nI was informed that an arcanist was employing the same tactic over at Farstrider Hold. Go retrieve some of his brooms and I will have them re-enchanted here.", objectives = "" }
WordHunterWoW_QuestEN[91998] = { title = "WANTED: Muckmire's Choking Vines", description = "Deep within the swamp is a creature of mud, leaves, and rage. His vines choke the life out of any who come near, and this dangerous creature cannot be allowed to live.\n\nDefeat Muckmire and bring me back his vines as proof of the deed.", objectives = "Collect the choking vines of Muckmire.", progress = "Be careful Muckmire doesn't drag you into the mud with him.", completion = "You look properly covered in mud and grime. Have you done it? \n\nAh yes, these are his vines. Well done." }
WordHunterWoW_QuestEN[91999] = { title = "A Bit of Bloodthistle", description = "You know, I bring Saltheril a lot of \"imported\" wine, but one of the first things I started supplying him with was bloodthistle. It's an herb that only grows around Eversong. It's got a smooth bite to it, sort of like mana. Nice and classy. His parties really go through the stuff.\n\nI took a look and I don't think he has enough to last this whole thing. We should get some more.\n\nThe best stuff grows over by the West Sanctum. Grab as much as you can carry. Trust me--it'll go fast.", objectives = "" }
WordHunterWoW_QuestEN[92000] = { title = "Bring the Ruckus", description = "This place is pretty fun so far, despite all the dry political talk. I know Saltheril is trying to get the nobles to buy up war bonds, but we could really use some more energy in here. If the nobles are all asleep, no one's buying anything.\n\nTell you what. Go invite some of my friends. They hang out under the bridge right outside of Silvermoon's gates.\n\nIf anyone can bring some energy to the soiree, it's us.", objectives = "Pass along Vyrin's invitation to 6 of his \"trader\" friends near the Path of Dawn.", completion = "The energy's high, the drinks are flowing, and people are having a good time!\n\nThat's how you start making deals." }
WordHunterWoW_QuestEN[92001] = { title = "One Smuggler to Another", description = "The whole point of this deal is showing the nobles what we bring to the table, both for Silvermoon and for them personally.\n\nThese other groups bring strength, power, and really nice armor. What we bring is resources: getting the sin'dorei what they need, when they need it, with no questions asked.\n\nI heard some folks over at Sunsail Anchorage have been trying out the same business, but they're putting gold in the wrong pockets. Swipe their stock and bring it here.", objectives = "" }
WordHunterWoW_QuestEN[92002] = { title = "Dangerous Showpieces", description = "You'd be surprised at the money you can make off of weapons. No, not the kind you're meant to use--the kind you stick up on the wall and have conversations about.\n\nUsually those weapons are expensive, or dangerous, or otherwise hard to get your hands on. The more rare and exclusive, the better.\n\nThe weapons those Twilight cultists are carrying around should sell pretty well, especially to buyers with edgier tastes. If you happen to come across any, I'll gladly take them off your hands.", objectives = "Collect 6 pieces of Twilight Weaponry from cultists at the Sanctum of the Moon.", progress = "If it has some blood on it, that's actually better.", completion = "Nice work. Eversong is safer because of your heroism, and I get to pocket a little more gold. I'd call that a win-win." }
WordHunterWoW_QuestEN[92003] = { title = "Artisanal Replicas", description = "Don't let the austere demeanor fool you. Nobles are just as susceptible to flashy party favors as the rest of us.\n\nI had my people bring over a batch of Felo'melorn replicas. They look great on display, and even better--they're enchanted. Swing them around and they leave a trail of fire.\n\nI haven't sold an enchanted batch before, so I'd like to do some testing before I hand them out. Saltheril wouldn't be too happy if I burned a guest to a crisp.\n\nWanna take one of the replicas for a test run?", objectives = "" }
WordHunterWoW_QuestEN[92004] = { title = "Shady Dealings", description = "I feel like I just got here and I'm already fresh out of half the poisons I brought.\n\nWhat? Don't look at me like that. Nobles are some of my top customers for poisons. Quieter than magic and cleaner than blades.\n\nI need to restock. The frogs way down in the south produce a poisonous slime that I can bottle without much fuss. Bring some of it to me and I'll get you a cut of the earnings.", objectives = "" }
WordHunterWoW_QuestEN[92005] = { title = "Throw the Dice", description = "We've been making friends with some of the guests by teaching them how to play dice. It's a nice way to draw people out of the crowd and get them in a quieter space where you can talk privately.\n\nI wasn't expecting so much interest, to be honest. We're running out of dice sets.\n\nI can carve some more, but I'll need materials. Usually teeth or bone are good picks. Actually, the fangs from those naga along the coast would be perfect. Now that's a conversation starter!", objectives = "Collect 12 Naga Fangs from naga near the Sunset Strand.", progress = "Any luck finding some of those fangs?", completion = "Oh, that smell is... very fishy. Definitely going to let these dry out for a while.\n\nYour exceptionally efficient help is appreciated, <name>." }
WordHunterWoW_QuestEN[92006] = { title = "We Need a Refill", description = "I talked to some of the servants earlier and it sounds like the casks are running low. That's a recipe for disaster at an event like this.\n\nFortunately, I've got a lot of contacts across Eversong who can help us restock.\n\nI need to stay here and play politics, but could you head over to Tranquillien and grab a few bottles? I'll give you a list.", objectives = "Purchase a case of Bloodthistle Brandy, Mana Burner, and Sun-Kissed Tranquilla from vendors in Tranquillien.", progress = "Trust me. Everything on that list is fantastic.", completion = "Nice work. I'll see about getting those casks refilled, but these bottles should keep everyone happy in the meantime." }
WordHunterWoW_QuestEN[92007] = { title = "Begged, Borrowed, or Stolen", description = "The oldest trick in the book is to create a problem on purpose, solve it yourself, and look like the hero.\n\nOne of the nobles just got word that some prized valuable was stolen from their estate while they were occupied here. It just so happens I might have put one of their servants up to it.\n\nGo talk to a man named Seridis over at the livery. He'll hand over the valuable to you, then you'll come back here and pretend you valiantly subdued the thief and retrieved the item.\n\nEveryone's happy.", objectives = "Speak to Seridis at Thuron's Livery, then retrieve the stolen item.", progress = "Making friends with the servants in noble households opens up a lot of doors. Sometimes literally.", completion = "Look at that. Everyone comes out a winner!\n\nThe noble gets his valuable back unscathed, Seridis gets paid handsomely, and you and I look brave and capable in front of the soiree." }
WordHunterWoW_QuestEN[92010] = { title = "WANTED: Slewstalk's Stalks", description = "Not far from here, Slewstalk lurks in the shallows. This creature has developed a taste for flesh and bones, and it won't be long until she wanders out of the Mire in search for warmer blooded prey.\n\nTake her out and bring me her luminescent stalks. They'll serve as proof and also make a fine centerpiece for an evening table.", objectives = "Collect luminecent stalks from Slewstalk.", progress = "Try to take Slewstalk down before she can get those long grippers of hers around you.", completion = "Ah, you return. And with glowing stalks to adorn my dinner table. Well done." }
WordHunterWoW_QuestEN[92012] = { title = "WANTED: Gorebarb's Pincers", description = "Gorebarb is a creature quite unlike most others who make Harandar their home. He's incredibly violent and his kind is not seen here very often. \n\nLet's see less of him. Kill him and bring me his pincers as proof of the deed.", objectives = "Collect Gorebarb's Pincers.", progress = "Take care that Gorebarb doesn't catch you with those pincers. I imagine his breath isn't pleasant at all.", completion = "Well, well. You managed to take down Gorebarb and retrieve the pincers? Ah, of course I never doubted you would." }
WordHunterWoW_QuestEN[92013] = { title = "WANTED: Dionaea's Thorntusks", description = "Many thornmaws make the mire their home, but none as are vicious as Dionaea. Unlike the others, she kills merely for the joy of it, and her gluttony threatens the delicate balance of the wildlife in this area. \n\nTake her out and restore the equilibrium. Bring me back her thorntusks as proof of the deed.", objectives = "Collect Dionaea's thorntusks.", progress = "Dionaea hunts for the thrill of it. She seems to be unable to satiate her hunger. Have you handled her yet?", completion = "You bring me the thorntusks? Excellent. May balance return to the Mire." }
WordHunterWoW_QuestEN[92018] = { title = "x.x Testing (YGR)", description = "", objectives = "" }
WordHunterWoW_QuestEN[92021] = { title = "Graveblossom Gardening", description = "My colleague Amalthea has taken ill. She requires a specialized poultice of sorts in order to ease the symptoms. I would forage for the plants myself, but the local fauna have grown so testy as of late!\n\nWhile you are out and about, could you gather some graveblossoms for me? I'd happily make it worth your while.", objectives = "Gather 8 Pristine Graveblossoms for Talandra Dawnsprite at Windrunner Village.", progress = "Oh, come now. While we stand here and chat about the weather, my associate continues to suffer under the travails of her malady! Get on with it.\n\nIt's gloomy, by the way. The weather. As usual.", completion = "There you have it! Eight flowers. Simple enough, no? Now, I just need a few more things...\n\nWhat? I didn't mention that there would be a shopping list? Oh, bother. Well, nothing to it but to do it now, hrm? You don't seem the type to leave things half-handled." }
WordHunterWoW_QuestEN[92022] = { title = "A Venomous Vocation", description = "My poultice requires venom samples from the local giant bat populations. Please retrieve some of those, as well. Six common vials' worth should do.\n\nDon't give me that look. They're bats. There are mad Light-plant-things to the east and a storm of voidwalkers swirling over our heads. Don't you dare give me guff about the dangers of big, fluffy bats. Now shoo. My colleague is depending on your prompt and efficient aid.", objectives = "Collect six vials of Potent Mournbat Venom from mournbats outside of Windrunner Village.", progress = "Strictly speaking, a stronger venom would have a more ample effect. But we're living in strenuous times. This Void hooplah has my usual supply lines at Sunsail completely occupied. We'll have to make do with mournbat venom. Now go.", completion = "There we are. See? I knew I could rely on you. We've only a few steps left to manage." }
WordHunterWoW_QuestEN[92023] = { title = "Suspicious Sundries", description = "Forgive me for my failure to provide specifics, traveler. The mournbat venom and the graveblossoms were only the first of the reagents I require for my associate's medication.\n\nLuckily, the final few things I require can all be easily obtained in Goldenmist Village to the north. Be a dear and fetch these last few things for me, won't you? With these, my toil will be nearly complete.", objectives = "Fetch a Vial of Quicksilver, a Flask of Dragon's Blood, and a Bottle of Magister's Reserve from the vendors at Goldenmist Village.", progress = "Eugh. Why do I smell grave soil on you?", completion = "That's an interesting bag of goods you're carrying there, friend. I don't suppose you're shopping on behalf of the \"apothecary\" in Windrunner Village?\n\nYou may wish to reconsider this course, if you value your well-being." }
WordHunterWoW_QuestEN[92024] = { title = "House Call", description = "That woman, that \"apothecary,\" has snared you in one of her schemes.\n\nI'd be careful around her, {class}. Rumors travel like wildfire in Eversong. And while I would never disparage a fellow artisan of Eversong without cause, I have heard enough rumors to know that your apothecary deals in more than simple herbs.\n\nTake your wine and your reagents, I suppose. But before you pass them off to your patroness, I'd recommend doing some digging--lest you find yourself wrapped up in something you come to regret.", objectives = "Investigate Talandra's home in Windrunner Village.", completion = "<Your findings leave little to the imagination. Whatever official enterprises Talandra purports to pursue, her personal affects betray a more sinister profession.>" }
WordHunterWoW_QuestEN[92025] = { title = "Flowers for Amalthea", description = "<The final pages of the tome detail a meeting place. Whatever Talandra Dawnsprite intends to do, she means to do it amidst the ghosts of Windrunner Spire.\n\nThe time for Talandra's ritual grows nigh.>", objectives = "Confront Talandra Dawnsprite at Windrunner Spire.", progress = "<Time is of the essence. Talandra's ritual approaches.>", completion = "Goodness! That was nearly quite the misunderstanding. I am glad you stayed your weapons long enough to hear me out.\n\nThe Scourge took much from the sin'dorei. For some, like Amalthea, it took everything and more.\n\nNeedless to say, my studies don't get me invited to many parties. But they allow me, from time to time, to ease Amalthea's torment. To that end, I would bear any indignity." }
WordHunterWoW_QuestEN[92028] = { title = "Pardon the Interruption", description = "{name}! Glad to see you. The defenders in the fortress could use your help.\n\nOne of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on.\n\nShe needs the help of someone who can properly interrupt the robot's attacks so it can be repaired.\n\nDo you have a moment to help?", objectives = "Activate Fightbot 11.2.7, then interrupt its abilities 3 times.", progress = "Some help! Hopefully you can find a way to interrupt this bot's abilities.", completion = "Great work! Now I should have time to fix whatever bug actually caused this in the first place.\n\nMaybe I can just say it's a feature and call it a day!" }
WordHunterWoW_QuestEN[92030] = { title = "A New Tradition", description = "Chon was just looking for you. You can find him at his house, serving drinks with Chen.\n\n<Lorewalker Cho laughs--a deep, warm rumble.>\n\nGo on, {name}! I won't be leaving anytime soon, that's for sure.", objectives = "Meet Chon Po in Wu-Song Village.", completion = "Ah, <name>... you have traveled far, but returned. You have reminded all who live here that the Spirit Festival is not just for the elemental spirits, but the spirits of all <race> who call this place home... even if they leave for a time. \n\nIn thanks, our tailors have crafted these for you. The maker's design celebrates your adventures, but also honors your origins... just as you have today.\n\nMaster Shang Xi would be so, so proud.\n\n\n\nTo you, my friend. To home." }
WordHunterWoW_QuestEN[92031] = { title = "Meet the Vandals", description = "<The Manaforge Vandals at Shadow Point are eager to see the Shadowguard and their allies removed from Manaforge Omega. It's probably a good time to pay them a visit.>", objectives = "Report to Zo'turu at Shadow Point.", completion = "Hero! Your reputation for toppling tyrants precedes you. Let's see about adding one more to that list." }
WordHunterWoW_QuestEN[92061] = { title = "Rising Storm", description = "That was an entropic wave. We felt them just before Xal'atath launched her assault on the Sunwell. \n\nChampion, you move faster than my best messengers. I need you to check in with the Vanguard commanders and see if their defenses will hold against this latest assault by Xal'atath's Devouring Host.", objectives = "De-escalate rising tensions in Silvermoon City.", progress = "Tensions are high.", completion = "Well done. That Voidstorm is evoking fear and terror in everyone who sees it, myself included. \n\nBut I chose this life of standing up to evil and spitting in its face. Sadly not everyone had the luxury of that being a choice." }
WordHunterWoW_QuestEN[92062] = { title = "Tending the Roots", description = "", objectives = "" }
WordHunterWoW_QuestEN[92078] = { title = "A New Recipe!", description = "", objectives = "You're back already! I believe I've found a use for the Manaforged Instruments you may have found within Araz's possession. Each are pieces of machinery that, if extracted properly, would yield a unique energy signal not dissimilar to the magic used to bind Ethereals. If you or anyone you know are particularly well-versed in Enchantmenting or Inscription, take these! They may hold secrets, or at the very least a novel experience for you. Good luck!" }
WordHunterWoW_QuestEN[92082] = { title = "Someone Like Me", description = "", objectives = "Hero... far be it from me to question your methods in taking down the All-Devouring, but I've noticed your snooping while inside Omega. Those cyphers you discovered are how we communicate with our contacts inside. I don't even know how you activated them - they were supposed to be heavily encrypted! Still... this is the kind of mischief I love to encourage. I'm not sure what use you'll get out of this disguise, but for all you've done for us, you've earned a treat. Just don't say you got it from me." }
WordHunterWoW_QuestEN[92084] = { title = "Halazzi's Guile", description = "Who are these people? Where did they come from?\n\nDid dey find their way here from Numazon? How? De mist keeps you from knowin' if you are comin' or goin'.\n\nAnd where is Halazzi?\n\nI need answers... now!", objectives = "Speak to Loa Speaker Tobui to discover how the Witherbark were rescued.", progress = "My vision is clearing, and so is my mind.", completion = "Like Akil'zon, Halazzi was watching. Waiting.\n\nHe never gave up on de Witherbark." }
WordHunterWoW_QuestEN[92085] = { title = "Claw Enforcement", description = "", objectives = "" }
